// ─── PRACTICES DATA ───────────────────────────────────────────────────────────
const ALL_PRACTICES = [
  { id: 1, emoji: "🪴", title: "Tend One Small Thing", subtitle: "Water a plant. Wipe a leaf. Watch it.", duration: "5–10 min", category: "Grounding", color: "#7A9E7E", front_detail: "No green thumb needed. Just presence.", science_title: "Attention Restoration Theory", science: "Caring for living things activates the parasympathetic nervous system — your rest-and-digest mode. Studies show even brief nature contact drops cortisol by up to 21%. Tending something small rewires the brain's reward loop away from productivity anxiety and toward quiet satisfaction. The key variable is not the plant — it's the directed, gentle attention.", how_it_helps: "Gives your mind one simple, beautiful task. No outcome. No metric. No email. Just life quietly doing its thing." },
  { id: 2, emoji: "✍️", title: "Three Sentences", subtitle: "Write three true things from today.", duration: "5 min", category: "Reflection", color: "#C1603A", front_detail: "Not a journal. Not a list. Just three honest sentences.", science_title: "Expressive Writing & Affect Labeling", science: "Dr. James Pennebaker's 30+ years of research at UT Austin found that brief expressive writing reduces rumination, improves immune function, and lowers psychological distress. Naming emotions calms the amygdala by engaging the prefrontal cortex. Three sentences is empirically sufficient.", how_it_helps: "Converts the noise of your day into signal. Creates a felt sense of closure. Gives you back your own story." },
  { id: 3, emoji: "🎵", title: "One Song, Full Attention", subtitle: "Sit. Play one song. Do nothing else.", duration: "3–5 min", category: "Presence", color: "#7B6E8D", front_detail: "No skipping. No scrolling. Just listen like it matters.", science_title: "Default Mode Network Reset", science: "Deep listening to music activates the default mode network — the same region involved in creativity, empathy, daydreaming, and self-understanding. A 2023 study found focused music listening reduces anxiety 65% more than passive background music. Your brain craves intentional sensory input, not ambient noise.", how_it_helps: "Interrupts the mental loop of work. Gives your nervous system a defined container of beauty. One song is a complete experience." },
  { id: 4, emoji: "🌫️", title: "5-5-5 Breath", subtitle: "In for 5. Hold for 5. Out for 5.", duration: "5 min", category: "Calm", color: "#6B8EA6", front_detail: "Do it standing by a window. Feel the shift.", science_title: "Vagal Nerve Stimulation", science: "Box breathing directly stimulates the vagus nerve, shifting from sympathetic (fight/flight) to parasympathetic (calm/restore). Heart rate variability improves measurably after just 5 minutes. This technique is used by Navy SEALs and trauma therapists alike.", how_it_helps: "Physically interrupts the stress response cycle. You cannot cognitively override anxiety — but you can breathe your way through it." },
  { id: 5, emoji: "🖊️", title: "Slow Sketch", subtitle: "Draw one object near you. Slowly.", duration: "10–20 min", category: "Making", color: "#C1603A", front_detail: "A mug. A shoe. A hand. Slow is the point, not the drawing.", science_title: "Flow State & Right-Brain Activation", science: "Betty Edwards' foundational research demonstrates that observational drawing forces a shift from the verbal-analytical left hemisphere to the spatial-intuitive right hemisphere. This produces measurable flow states — complete absorption where time distorts, the inner critic quiets, and self-consciousness dissolves.", how_it_helps: "You don't need talent. Skill is irrelevant. The point is the absorbed attention that comes from truly looking at something for the first time." },
  { id: 6, emoji: "🧂", title: "Cook One New Thing", subtitle: "One ingredient. One technique. No recipe needed.", duration: "15–30 min", category: "Making", color: "#C8825A", front_detail: "Toast spices. Caramelize an onion. Taste constantly.", science_title: "Embodied Creativity & Reward Anticipation", science: "Cooking activates multiple sensory cortices simultaneously — smell, touch, taste, sight, proprioception — creating multisensory integration, a deeply grounding state. The anticipation of eating something you made releases dopamine before you even taste it.", how_it_helps: "Grounds you in your body and senses after a day of abstract, screen-mediated, disembodied work. Produces something real. Something you can eat." },
  { id: 7, emoji: "🚶", title: "The Noticing Walk", subtitle: "Walk 15 min. Find 5 things you've never noticed.", duration: "15 min", category: "Presence", color: "#7A9E7E", front_detail: "Same block, new eyes. That's the entire practice.", science_title: "Novelty-Seeking & Neuroplasticity", science: "A landmark 2019 Stanford study showed that even familiar environments, explored with deliberate perceptual attention, stimulate hippocampal activity associated with memory consolidation and mood regulation. Walking specifically enhances bilateral brain processing.", how_it_helps: "Breaks perceptual habituation. Teaches your nervous system that your ordinary world is genuinely full of interest." },
  { id: 8, emoji: "🌿", title: "Forage Something Beautiful", subtitle: "Find one natural object. Place it where you'll see it.", duration: "10–20 min", category: "Grounding", color: "#6B9E6B", front_detail: "A leaf. A stone. A feather. A genuinely weird stick.", science_title: "Biophilia & Aesthetic Experience", science: "E.O. Wilson's biophilia hypothesis — supported by 40 years of environmental psychology — shows humans have a deep innate bond with natural patterns. Deliberately selecting and handling natural objects activates the somatosensory cortex in ways screen interaction cannot replicate.", how_it_helps: "Creates a physical anchor for your day. Something from outside that you brought inside. A small ritual of attention and curation." },
  { id: 9, emoji: "🎲", title: "Learn One Weird Fact", subtitle: "Pick a rabbit hole. Follow it. No productivity goals.", duration: "15 min", category: "Curiosity", color: "#9B7BB8", front_detail: "Octopus cognition. Medieval bread laws. Whale songs. Anything.", science_title: "Curiosity & Intrinsic Motivation", science: "Dr. Matthias Gruber's research at UC Davis shows curiosity-driven learning activates the dopamine system and hippocampus simultaneously, making information stick 40% better. Following intrinsic curiosity systematically rebuilds the intrinsic motivation that repetitive work environments erode over time.", how_it_helps: "Reminds your brain that it loves learning. That you are more than your job description. That the world is genuinely strange and beautiful." },
  { id: 10, emoji: "🤲", title: "Make Something Ugly", subtitle: "Clay, paper, doodles. No goal of it being good.", duration: "15–30 min", category: "Making", color: "#C1603A", front_detail: "The uglier the better. That is the point entirely.", science_title: "Non-Evaluative Creative Expression", science: "Art therapy research consistently shows that process-focused making significantly reduces activity in the prefrontal cortex — the area responsible for self-judgment and evaluation. The brain enters a state near identical to meditation. Imperfection is the active therapeutic mechanism.", how_it_helps: "Undoes the perfectionism that work relentlessly reinforces. Gives you permission to make something that exists purely for expression." },
  { id: 11, emoji: "☕", title: "Ritual Drink, Full Presence", subtitle: "Make your drink slowly. Drink it with nothing else.", duration: "10 min", category: "Presence", color: "#A0785A", front_detail: "Tea. Coffee. Water. Warm broth. Slow it all down.", science_title: "Mindful Ritual & Sensory Anchoring", science: "Deliberate sensory rituals activate the insula — a brain region central to interoception and self-connection. Research shows that ritualized consumption increases perceived pleasure and presence independent of the substance consumed.", how_it_helps: "Creates a clear transition between work mode and self mode. The ritual signals safety to your nervous system. You are here." },
  { id: 12, emoji: "🌅", title: "Watch the Light Change", subtitle: "Sit by a window. Watch light move for 10 minutes.", duration: "10 min", category: "Calm", color: "#D4945A", front_detail: "Golden hour. Cloud shadows. Anything moving in natural light.", science_title: "Temporal Perception & Awe", science: "Dacher Keltner's awe research at UC Berkeley shows witnessing slow natural phenomena expands perceived time and increases prosocial emotion. This 'perceived time expansion' directly counters the time scarcity that chronic stress creates. You literally experience more time.", how_it_helps: "Resets your relationship with time. Reminds you the world moves at its own pace, completely indifferent to your inbox." },
  { id: 13, emoji: "📖", title: "Read One Poem", subtitle: "Find one poem. Read it twice. Sit with it.", duration: "5–10 min", category: "Reflection", color: "#9B7BB8", front_detail: "You don't need to understand it. Just feel it.", science_title: "Aesthetic Language & Emotional Processing", science: "Reading poetry activates the same brain regions as music and autobiographical memory simultaneously. Its unique combination of linguistic precision and emotional ambiguity invites active meaning-making rather than passive consumption. The brain is forced to slow down and re-read.", how_it_helps: "Exercises your capacity for nuance. Gives language back its texture after a day of functional, transactional words." },
  { id: 14, emoji: "🧘", title: "Body Scan", subtitle: "Lie down. Slowly notice each part of your body.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "Toes to crown. No fixing. Just noticing what's there.", science_title: "Interoceptive Awareness & Stress Regulation", science: "Jon Kabat-Zinn's MBSR protocol, studied across hundreds of clinical trials, shows body scanning reduces cortisol, improves sleep quality, and significantly lowers anxiety scores. Interoceptive awareness is one of the strongest predictors of emotional regulation ability.", how_it_helps: "Reconnects you to your physical self after a day spent entirely in your head. Your body has been carrying the day. This is how you check in." },
  { id: 15, emoji: "🌱", title: "Plant a Seed", subtitle: "Any seed. Any pot. Any dirt. Watch over days.", duration: "15 min", category: "Grounding", color: "#7A9E7E", front_detail: "The waiting is the practice. Not the growing.", science_title: "Anticipatory Joy & Soil Microbiome", science: "Anticipated positive events activate the ventral striatum as powerfully as the event itself. Mycobacterium vaccae in soil triggers serotonin production when absorbed through skin. Gardening is biochemically antidepressant.", how_it_helps: "Gives you something living to look forward to that isn't a deadline or a deliverable. A commitment to something that grows in its own time." },
  { id: 16, emoji: "🎨", title: "Color Something", subtitle: "A coloring page. Print one for free. Just color.", duration: "15–20 min", category: "Making", color: "#E8845A", front_detail: "Choose colors instinctively. Don't plan. Don't think.", science_title: "Repetitive Fine Motor & Relaxation Response", science: "Coloring reduces amygdala activity and activates the frontal lobe in patterns associated with focused calm. The repetitive, spatially-contained hand movement triggers the relaxation response in a mechanism near identical to meditation.", how_it_helps: "A structured creative act that requires just enough focus to quiet mental noise, but not so much that it becomes effortful." },
  { id: 17, emoji: "🌊", title: "Cold Water on Your Face", subtitle: "Splash cold water on your face. Slowly. Three times.", duration: "2 min", category: "Calm", color: "#6B8EA6", front_detail: "Stand at the sink. Be completely, stupidly present.", science_title: "Mammalian Dive Reflex & Vagal Activation", science: "Cold water on the face activates the mammalian dive reflex — a deeply conserved evolutionary response that immediately slows heart rate and activates the vagus nerve. Heart rate drops 10–25% within seconds. Used in DBT for acute emotional dysregulation.", how_it_helps: "An instant, tool-free physiological reset. The simplest possible intervention. Just water and a sink." },
  { id: 18, emoji: "🎭", title: "Talk to a Stranger", subtitle: "A neighbor, shopkeeper, or someone at a cafe.", duration: "10–15 min", category: "Connection", color: "#C1603A", front_detail: "Not networking. Not catching up. Just actual talking.", science_title: "Weak Ties & Subjective Wellbeing", science: "UBC researchers found that brief positive interactions with 'weak ties' — acquaintances, service workers, strangers — increase daily wellbeing as much as interactions with close friends. Belonging is not reserved for intimacy.", how_it_helps: "Breaks the social tunnel vision of work relationships. Reminds you the world is full of people who are not your colleagues." },
  { id: 19, emoji: "🌙", title: "Gratitude Without a List", subtitle: "Think of one specific moment from today. Hold it.", duration: "5 min", category: "Reflection", color: "#9B7BB8", front_detail: "Not gratitude in general. One very specific thing.", science_title: "Specificity & Positive Affect Durability", science: "Dr. Martin Seligman's positive psychology research shows specificity is the crucial variable in gratitude's effectiveness. Vague gratitude habituates rapidly. Specific gratitude reactivates episodic memory and prolongs positive affect significantly longer.", how_it_helps: "Finds the real good without bypassing the hard. Anchors attention in what actually happened today, not an abstraction." },
  { id: 20, emoji: "🏺", title: "Rearrange One Shelf", subtitle: "One shelf. Move things. See what it becomes.", duration: "10–15 min", category: "Making", color: "#A0785A", front_detail: "This is curation. You are the editor of your own space.", science_title: "Environmental Mastery & Agency Restoration", science: "Research on environmental mastery shows that making small, intentional changes to your physical environment restores a sense of agency and competence. This directly counteracts learned helplessness, a common psychological cost of overstructured work environments.", how_it_helps: "You made a decision. It had no meeting. No approval. The result is immediately visible. That is its own category of satisfaction." },
  { id: 21, emoji: "🦋", title: "Sit Outside for 10 Minutes", subtitle: "No phone. No agenda. Just outside.", duration: "10 min", category: "Presence", color: "#7A9E7E", front_detail: "Morning, noon, or evening. All equally restorative.", science_title: "Green Micro-Doses & Cortisol", science: "A 2019 Frontiers in Psychology study found that just 20 minutes in nature significantly reduces cortisol and amygdala activity. Even 10 minutes of purposeful outdoor sitting produces measurable changes in physiological stress markers. Urban nature counts.", how_it_helps: "Your nervous system knows it's outside. You don't have to do anything. Just be there. That's enough." },
  { id: 22, emoji: "🎸", title: "Hum or Sing Something", subtitle: "Shower, kitchen, car. Make sound. Any sound.", duration: "5–10 min", category: "Making", color: "#7B6E8D", front_detail: "Not performing. Not recording. Just making sound.", science_title: "Vocal Resonance & Vagal Tone", science: "Humming and singing create internal vibrations that directly stimulate the vagus nerve through laryngeal resonance. Research shows singing raises oxytocin, reduces cortisol, and improves mood — with zero dependence on musical skill or an audience.", how_it_helps: "Your body was built to make sound. This is not a performance. It is physiological self-regulation that also happens to be joyful." },
  { id: 23, emoji: "📷", title: "One Intentional Photo", subtitle: "Find one beautiful thing. Photograph it carefully.", duration: "10–15 min", category: "Presence", color: "#C8825A", front_detail: "Not for anyone. One image. Made carefully. What did you actually look at?", science_title: "Savoring & Positive Memory Encoding", science: "Fred Bryant's savoring research shows that deliberately attending to positive experiences significantly increases their mood impact and long-term memory consolidation. Photography extends the savoring window far beyond what unaided attention typically sustains.", how_it_helps: "Slows you down enough to actually see something. Not document it. Not post it. Actually see it." },
  { id: 24, emoji: "🧩", title: "Work an Analog Puzzle", subtitle: "Crossword, jigsaw, wood puzzle. Hands on something real.", duration: "15–30 min", category: "Curiosity", color: "#9B7BB8", front_detail: "The kind that doesn't send you notifications.", science_title: "Fluid Intelligence & Structured Leisure", science: "Analog puzzles engage visuospatial reasoning and working memory while completely blocking digital interruption. Research on structured leisure shows they restore cognitive resources more effectively than passive rest or unstructured screen time.", how_it_helps: "Gives your mind a challenge that doesn't involve another person's expectations or your professional identity." },
  { id: 25, emoji: "🕯️", title: "Light a Candle, Sit in It", subtitle: "One candle. No other lights. Sit in it for 10 minutes.", duration: "10 min", category: "Calm", color: "#D4945A", front_detail: "No other lights. Just the flame. Be with the flame.", science_title: "Firelight & Ancestral Safety Signals", science: "Evolutionary psychology research shows that humans across all cultures exhibit reduced blood pressure, respiratory rate, and heightened prosocial calm in the presence of firelight. Candlelight mimics the ancestral campfire — a deeply encoded signal that the day is done and you are safe.", how_it_helps: "Tells your nervous system: the day is over. You survived it. You are safe now." },
  { id: 26, emoji: "🗣️", title: "Voice Memo to Yourself", subtitle: "Record 3 minutes of honest thoughts. Don't listen back.", duration: "5 min", category: "Reflection", color: "#C1603A", front_detail: "Like thinking out loud, but slightly slower and more honest.", science_title: "Verbal Processing & Narrative Closure", science: "Speaking about experiences simultaneously activates Broca's area and engages the hippocampus in narrative formation — the process of making events into story. This verbal processing creates psychological closure more effectively than rumination, which loops without resolution.", how_it_helps: "Sometimes you just need to say it. Not to anyone in particular. Just to say it out loud and let it leave." },
  { id: 27, emoji: "🌾", title: "Stretch One Tight Place", subtitle: "Find where you're holding tension. Stay there 2 minutes.", duration: "5–10 min", category: "Grounding", color: "#7A9E7E", front_detail: "Neck. Shoulders. Jaw. Hips. You know where.", science_title: "Proprioception & Somatic Tension Release", science: "Prolonged static stretching activates Golgi tendon organs, triggering autogenic inhibition — a protective spinal reflex that compels muscular release. Directing interoceptive attention to the sensation simultaneously interrupts cortical rumination loops.", how_it_helps: "You have been clenching all day without knowing it. This is how you find where, and how you let it go." },
  { id: 28, emoji: "🍃", title: "Make One Thing Beautiful", subtitle: "Arrange flowers, fruit, or objects for no reason.", duration: "10–15 min", category: "Making", color: "#6B9E6B", front_detail: "A table, a windowsill, a desk. Just for you. No audience.", science_title: "Aesthetic Agency & Orbitofrontal Activation", science: "Creating visual beauty activates the orbitofrontal cortex — the brain region associated with reward valuation and aesthetic experience. Deliberate aesthetic arrangement produces stronger and longer-lasting wellbeing effects than passive aesthetic consumption.", how_it_helps: "You made something beautiful that no one asked for and no one may ever see. That is its own complete category of satisfaction." },
  { id: 29, emoji: "📝", title: "Write a Letter You Won't Send", subtitle: "To anyone. From anywhere honest inside you.", duration: "15–20 min", category: "Reflection", color: "#9B7BB8", front_detail: "Past you. Future you. Someone you miss. Someone you've forgiven.", science_title: "Unsent Letter Technique & Emotional Completion", science: "Psychotherapy research shows unsent letter techniques process unresolved emotion more effectively than direct conversation. The removal of social consequence creates radical permission for honesty and emotional completion.", how_it_helps: "Completes conversations you couldn't finish. Frees up emotional working memory that was quietly still holding them open." },
  { id: 30, emoji: "🧺", title: "Do One Chore Meditatively", subtitle: "Fold laundry. Wash dishes. Sweep. Fully slowly.", duration: "10–20 min", category: "Presence", color: "#A0785A", front_detail: "The goal is not clean. The goal is full, unhurried attention.", science_title: "Mindful Task Engagement & Flow Induction", science: "A 2015 Florida State University study found that dishwashing mindfully — attending to warmth, smell, sound, and texture — reduced nervousness by 27% and increased mental inspiration significantly. Repetitive physical tasks with low cognitive load are natural containers for present-moment absorption.", how_it_helps: "Finds the contemplative in the ordinary. The boring chore becomes the practice. The house gets clean as a side effect." },
  { id: 31, emoji: "🌍", title: "Learn 5 Words in Another Language", subtitle: "Any language. Say them aloud. Learn them for no reason.", duration: "10 min", category: "Curiosity", color: "#6B8EA6", front_detail: "Not for travel. Not for a reason. Just for the beauty of it.", science_title: "Language Learning & Cognitive Flexibility", science: "Even minimal second-language exposure activates the anterior cingulate cortex and dorsolateral prefrontal cortex — regions associated with cognitive flexibility, error monitoring, and executive control. Novel phonemes literally force the brain out of its habitual processing pathways.", how_it_helps: "Opens a door to a world that thinks differently. Reminds you that meaning is constructed, not fixed." },
  { id: 32, emoji: "🧦", title: "Disrupt One Small Habit", subtitle: "Different route. Non-dominant hand. Change one small thing.", duration: "5 min", category: "Curiosity", color: "#9B7BB8", front_detail: "Tiny disruption. Surprisingly large signal to the brain.", science_title: "Behavioral Flexibility & Cortical Re-engagement", science: "Disrupting automatized behaviors forces the prefrontal cortex back online — out of autopilot and into active engagement. Research shows even tiny variations in daily routine measurably increase attentional engagement and novelty processing throughout the day.", how_it_helps: "Wakes up the part of you that stopped noticing. Reminds your brain that anything — even the familiar — can become interesting." },
  { id: 33, emoji: "🌬️", title: "Open a Window, Just Breathe", subtitle: "Open a window. Stand in front of it. Breathe.", duration: "5 min", category: "Calm", color: "#6B8EA6", front_detail: "Outside air. Outside sounds. Outside light. Just stand there.", science_title: "Olfactory-Limbic Pathway & Air Quality", science: "Fresh air contains phytoncides, negative ions, and varied olfactory compounds that activate the limbic system directly through the olfactory bulb — the only sensory system with a direct pathway to the emotional brain. Indoor air recirculation correlates with increased fatigue and depressed mood.", how_it_helps: "Changes the literal chemical environment of your brain. Takes less than five minutes. You already have a window." },
  { id: 34, emoji: "🖋️", title: "Copy a Paragraph by Hand", subtitle: "Find a paragraph you love. Transcribe it slowly.", duration: "10 min", category: "Making", color: "#C1603A", front_detail: "A book, a poem, a letter. Copy it word by word. Feel each one.", science_title: "Slow Reading, Haptic Memory & Deep Encoding", science: "Handwriting simultaneously engages visual, motor, and linguistic cortices — a unique multimodal encoding that typing entirely lacks. Research shows handwritten content is retained with significantly greater depth and personal resonance. The physical act of inscription changes your relationship to the words.", how_it_helps: "Slows you down to the speed of meaning. You feel every word differently when your hand traces it." },
  { id: 35, emoji: "🦉", title: "Watch Something Small & Wild", subtitle: "A bird. An ant. A bee. Follow it with full attention.", duration: "10–15 min", category: "Presence", color: "#7A9E7E", front_detail: "From outside or a window. Just watch one thing, fully.", science_title: "Focused Attention & Micro-Awe", science: "Research on micro-awe by Keltner and colleagues shows that careful, sustained attention to small natural events activates the same awe circuitry as grand experiences. Five or more minutes of focused attention on non-human life measurably improves mood and reduces self-referential thinking.", how_it_helps: "Something is fully alive out there, completely absorbed in its own existence, with no awareness of you at all. That is a profound kind of perspective." },
  { id: 36, emoji: "🧁", title: "Make Someone Something", subtitle: "Bake, write, draw, make anything small. Give it away.", duration: "20–30 min", category: "Connection", color: "#E8845A", front_detail: "It doesn't have to be good. It does have to be real.", science_title: "Prosocial Creativity & Helper's High", science: "Giving activates the mesolimbic dopamine system — the brain's core reward pathway — producing what researchers call helper's high. Creative production combined with giving creates a compound wellbeing effect documented to be greater than either act alone.", how_it_helps: "Breaks the gravitational pull of self-focus. Makes something that exists entirely for someone else. That is a complete act." },
  { id: 37, emoji: "🎪", title: "Watch a Craft Video, Fully", subtitle: "Glassblowing. Woodworking. Paper marbling. Watch it all.", duration: "10–15 min", category: "Curiosity", color: "#A0785A", front_detail: "No skipping to the good part. The whole process is the point.", science_title: "Vicarious Flow & Mirror Neuron Activation", science: "Observing skilled craft activates mirror neuron networks associated with the motor patterns of the craft — producing a vicarious flow state. Focused craft observation reduces anxiety and increases creative self-efficacy, the belief that you yourself are capable of making things.", how_it_helps: "Reminds you that humans are capable of extraordinary patience and skill. That things that take time are the most beautiful things." },
  { id: 38, emoji: "🌒", title: "Moon or Star Check", subtitle: "Step outside at night. Look up. Five minutes.", duration: "5 min", category: "Calm", color: "#2C4A30", front_detail: "No star-identification app. No facts. Just looking.", science_title: "Cosmic Awe & Self-Transcendence", science: "Keltner's awe research identifies vast stimuli — phenomena that dwarf human scale — as the most potent triggers of self-transcendence, a state associated with reduced anxiety, increased generosity, expanded time perception, and reduced default self-referential network activity.", how_it_helps: "Nothing recalibrates perspective like the actual sky at actual night. Your problems don't become small — you just become proportionately larger." },
  { id: 39, emoji: "🧃", title: "Drink Water, Consciously", subtitle: "One full glass. Slowly. One sip at a time.", duration: "5 min", category: "Grounding", color: "#7A9E7E", front_detail: "You are probably dehydrated. This is genuinely medicinal.", science_title: "Dehydration, Cognition & Interoception", science: "Mild dehydration of just 1–2% of body water impairs mood, attention, and working memory more significantly than most cognitive interventions can compensate for. Drinking water slowly while attending to the sensation activates interoceptive awareness pathways simultaneously.", how_it_helps: "Radically simple. Profoundly underrated. Your brain is 73% water. It has been asking for this all afternoon." },
  { id: 40, emoji: "🗺️", title: "Plan a Tiny Future Adventure", subtitle: "Somewhere 30 minutes away. Plan it like it matters.", duration: "10 min", category: "Curiosity", color: "#9B7BB8", front_detail: "A park you've never entered. A cafe. A bookshop. A viewpoint.", science_title: "Anticipatory Positive Affect & Future Self", science: "Research shows that anticipated experiential events generate wellbeing equivalent to the experience itself. Having even a small near-term positive event to anticipate reduces depressive symptoms and increases daily energy and motivation.", how_it_helps: "Gives your future self a gift. Makes your life feel meaningfully larger than it did this morning." },
  { id: 41, emoji: "🧲", title: "Organize One Small Drawer", subtitle: "One drawer. Empty it. Only put back what earns its place.", duration: "15 min", category: "Making", color: "#A0785A", front_detail: "This is editing. Curation. Not cleaning.", science_title: "Environmental Complexity & Cognitive Load", science: "Cluttered environments increase cortisol and sustained cognitive load. Research by neuroscientists at Princeton shows visual clutter directly competes for neural resources with focused thought, even when we're not conscious of it.", how_it_helps: "Creates a small area of order. Demonstrates that you have the power to make your environment reflect your intentions." },
  { id: 42, emoji: "🎋", title: "Sit in Silence for 10 Minutes", subtitle: "No music. No podcast. No background anything.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "Find the quietest place you have. Sit there. Do nothing.", science_title: "Default Mode Network & Restorative Silence", science: "A 2013 study found that two hours of silence generated new neurons in the hippocampus — the brain region associated with memory, learning, and emotional integration. In an age of constant auditory input, silence is a genuinely scarce and potent restorative resource.", how_it_helps: "Stops the input. Creates space for integration. Lets your mind wander into its own interior rather than someone else's content." },
  { id: 43, emoji: "💌", title: "Write to Your Past Self", subtitle: "Write a letter to you from five years ago.", duration: "15 min", category: "Reflection", color: "#9B7BB8", front_detail: "What would you have needed to hear? Say it.", science_title: "Self-Compassion & Temporal Self-Appraisal", science: "Kristin Neff's self-compassion research shows that writing to a past self activates self-compassion circuits — the same neural systems involved in compassion toward others. Temporal self-appraisal reduces self-criticism and increases psychological resilience.", how_it_helps: "Generates compassion for the person who didn't yet know what you now know. That compassion often transfers, unexpectedly, to the present." },
  { id: 44, emoji: "🌺", title: "Smell Something Beautiful", subtitle: "Flowers, coffee, rain, bread, citrus peel. Just smell.", duration: "5 min", category: "Presence", color: "#E8845A", front_detail: "Slowly. Intentionally. More than once.", science_title: "Olfaction, Emotion & Memory", science: "The olfactory system is the only sensory system with a direct anatomical connection to the amygdala and hippocampus — bypassing the thalamic relay used by all other senses. This makes smell uniquely powerful for emotional memory, mood regulation, and rapid nervous system state change.", how_it_helps: "One of the fastest known routes to a different emotional state. Takes no time. Requires no equipment. You have a nose." },
  { id: 45, emoji: "🧵", title: "Work with Your Hands on Something Tiny", subtitle: "Knot, braid, stitch, fold. Small and precise.", duration: "15–20 min", category: "Making", color: "#C1603A", front_detail: "Precision is meditative. Small scale creates calm.", science_title: "Fine Motor Control & Focused Attention", science: "Precise fine motor tasks activate the cerebellum and motor cortex in patterns associated with focused, calm states. The specificity of scale — working small — narrows attentional bandwidth and naturally excludes extraneous thought. This is the neurological basis of crafts like sewing and origami as stress reduction.", how_it_helps: "The smaller the scale of making, the larger the sense of absorbed presence. Your whole mind fits inside something tiny." },
  { id: 46, emoji: "🌊", title: "Listen to Water", subtitle: "Running tap, rain, a stream, ocean sounds. Just listen.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "Close your eyes. Let it be the only thing.", science_title: "Pink Noise, 1/f Patterns & Neural Synchrony", science: "Water sounds exhibit 1/f (pink noise) frequency patterns — the same statistical structure found in neural oscillations during restful states. Research shows exposure to 1/f noise synchronizes brain waves, reduces sympathetic nervous system activity, and promotes relaxed alertness.", how_it_helps: "Your brain literally resonates with water. This is not metaphor. It is neuroscience." },
  { id: 47, emoji: "🖼️", title: "Spend Time with One Artwork", subtitle: "Find one painting, photo, or sculpture. Really look.", duration: "10–15 min", category: "Presence", color: "#9B7BB8", front_detail: "Online, in a book, on a wall. One piece. Ten minutes.", science_title: "Slow Looking & Visual Contemplation", science: "Harvard art educator Philip Yenawine's research shows that sustained looking at a single artwork — even for ten minutes — develops tolerance for ambiguity, deepens observational skills, and generates genuine aesthetic emotion that brief viewing does not.", how_it_helps: "Teaches you to stay with something. To look longer than is comfortable. To let meaning emerge rather than be grabbed." },
  { id: 48, emoji: "🌿", title: "Make Herbal Tea from Scratch", subtitle: "Dried herbs, hot water. Go slowly. Notice everything.", duration: "10–15 min", category: "Making", color: "#7A9E7E", front_detail: "Chamomile, mint, ginger, lavender. Whatever you have.", science_title: "Phytochemistry, Ritual & Embodied Presence", science: "Several common culinary herbs contain compounds with documented anxiolytic effects — apigenin in chamomile, linalool in lavender, rosmarinic acid in lemon balm. Combined with slow preparation ritual and olfactory activation from steeping, the multi-pathway effect is significant.", how_it_helps: "Chemistry and ceremony in one cup. You made medicine with your hands. Slowly. On purpose." },
  { id: 49, emoji: "🧸", title: "Do Something Playful and Pointless", subtitle: "Blow bubbles. Skip. Make a paper airplane. Play.", duration: "10 min", category: "Presence", color: "#E8845A", front_detail: "Deliberately, unabashedly, unproductively pointless.", science_title: "Adult Play & Prefrontal Deactivation", science: "Stuart Brown's play research shows that adult play — activity done for its own sake with no outcome attached — produces prefrontal deactivation patterns associated with children at play. Play is not frivolous; it is a primary mechanism for neural flexibility, creativity, and resilience maintenance in adults.", how_it_helps: "You forgot that you are allowed to be ridiculous. This is the reminder. You are still allowed." },
  { id: 50, emoji: "📻", title: "Listen to Radio from Somewhere Else", subtitle: "Pick a city. Find their local radio. Listen.", duration: "15 min", category: "Curiosity", color: "#7B6E8D", front_detail: "Tokyo jazz. Nairobi news. Icelandic pop. Anywhere else.", science_title: "Vicarious Travel & Perspective Expansion", science: "Exposure to unfamiliar cultural contexts — even passively — activates perspective-taking neural networks and temporarily disrupts the egocentric processing that chronic stress and habitual routine entrench. Even simulated distance from your immediate context improves creative thinking.", how_it_helps: "Someone is having a completely different Tuesday on the other side of the planet right now. That is worth a few minutes of your attention." },
  { id: 51, emoji: "🏔️", title: "Look at Something Far Away", subtitle: "Out a window or outside. Let your eyes rest on distance.", duration: "5 min", category: "Calm", color: "#6B8EA6", front_detail: "No screens. No near objects. Just distance.", science_title: "Ciliary Muscle Rest & Nervous System State", science: "Extended close-focus work chronically contracts the ciliary muscles of the eye and correlates with increased sympathetic nervous system activation. Focusing on distant objects — ideally 20 or more feet away — releases ciliary tension and is associated with a measurable shift toward parasympathetic states.", how_it_helps: "Your eyes have been straining to see things that are very close and very urgent. The horizon is neither. Let them rest." },
  { id: 52, emoji: "🌀", title: "Doodle for 15 Minutes", subtitle: "No subject, no plan. Let the pen go where it wants.", duration: "15 min", category: "Making", color: "#9B7BB8", front_detail: "Patterns, spirals, shapes. Nothing has to mean anything.", science_title: "Unstructured Drawing & Default Mode Activation", science: "Unlike observational drawing, purposeless doodling activates the default mode network — the brain's creative, self-referential, meaning-making system. Research showed that doodling during a task improved recall by 29%, suggesting it maintains optimal arousal rather than indicating inattention.", how_it_helps: "Lets the hand think. Lets meaning emerge from motion rather than from intention. The most democratic creative act there is." },
  { id: 53, emoji: "🌾", title: "Walk Barefoot on Grass", subtitle: "Find some grass. Remove your shoes. Just stand.", duration: "10 min", category: "Grounding", color: "#7A9E7E", front_detail: "Or sand, or soil. Direct contact. Just stand.", science_title: "Earthing & Somatic Grounding", science: "The proprioceptive and interoceptive stimulation of barefoot standing on irregular natural surfaces is well-documented to reduce cortisol. Emerging earthing research suggests direct skin contact with the Earth's surface may facilitate additional anti-inflammatory benefits.", how_it_helps: "Your feet have been inside shoes inside buildings for most of your life. The earth is still there. It remembers you." },
  { id: 54, emoji: "🫀", title: "Check in With Your Body", subtitle: "Pause. What is your body actually feeling right now?", duration: "5 min", category: "Grounding", color: "#C1603A", front_detail: "Temperature. Tension. Hunger. Weight. Tiredness. Breath.", science_title: "Interoception & Emotional Regulation", science: "Interoceptive accuracy — the ability to perceive internal body signals — is one of the strongest predictors of emotional regulation, empathy, and subjective wellbeing. Most adults operating under chronic stress have severely reduced interoceptive awareness, having learned to ignore the body to maintain productivity.", how_it_helps: "Your body has been sending signals all day. This is five minutes of actually listening to them before the day ends." },
  { id: 55, emoji: "🎯", title: "Practice Something for 15 Min", subtitle: "Anything with a skill curve. Just practice.", duration: "15 min", category: "Making", color: "#C8825A", front_detail: "Juggling. Card tricks. A chord. Anything learnable.", science_title: "Deliberate Practice & Intrinsic Reward", science: "Anders Ericsson's deliberate practice research shows that focused, feedback-rich practice in any domain activates intrinsic reward circuits independent of external validation. The experience of getting marginally better at anything is neurologically reinforcing, regardless of the domain.", how_it_helps: "Reminds you that you are capable of growth outside your professional identity. That learning is inherently pleasurable." },
  { id: 56, emoji: "🌻", title: "Put a Flower Somewhere New", subtitle: "One flower. One new place. Just because.", duration: "10 min", category: "Making", color: "#E8845A", front_detail: "Garden, grocery store, a field, a weed in a crack. It counts.", science_title: "Aesthetic Placement & Environmental Enrichment", science: "Research on environmental enrichment shows the deliberate introduction of novel, beautiful stimuli into an environment produces sustained positive effects on mood, attention, and creative capacity. The act of placement is itself a creative decision that activates aesthetic neural networks.", how_it_helps: "You changed the room. You put beauty somewhere it wasn't. That is a small act of making the world slightly more like it should be." },
  { id: 57, emoji: "🎻", title: "Sit with Unfamiliar Music", subtitle: "Something you'd never choose. Just sit with it.", duration: "15 min", category: "Curiosity", color: "#7B6E8D", front_detail: "Classical, folk, jazz, gnawa, gamelan. Anywhere but your usual.", science_title: "Aesthetic Challenge & Openness to Experience", science: "Research shows that deliberately engaging with unfamiliar musical styles exercises the openness to experience dimension of personality, which is strongly correlated with creativity, wellbeing, and cognitive flexibility. The initial confusion is the practice.", how_it_helps: "Exercises the part of you that can hold 'I don't understand this yet' without closing the door. That capacity matters far beyond music." },
  { id: 58, emoji: "🧁", title: "Make a Playlist for a Feeling", subtitle: "Name the feeling first. Then find every song for it.", duration: "15 min", category: "Curiosity", color: "#7B6E8D", front_detail: "The curation is the practice. Not just the listening.", science_title: "Music Selection as Metacognition", science: "Intentional music selection for a target emotional state requires identifying your current affect, imagining the desired state, and bridging between them through sonic memory. This is emotional regulation through metacognitive musical curation — a remarkably sophisticated act.", how_it_helps: "You are becoming your own emotional musicologist. The playlist is a map of where you want to go." },
  { id: 59, emoji: "📞", title: "Call a Friend with No Agenda", subtitle: "Just to hear their voice. Nothing to catch up on.", duration: "15–20 min", category: "Connection", color: "#C1603A", front_detail: "Not a plan. Not a problem to solve. Just a voice.", science_title: "Social Connection & Longevity", science: "Social connection is the single strongest predictor of longevity across all major population studies. Unexpected positive contact — calling without being called — is weighted more heavily by recipients than routine contact. Unscheduled warmth registers as genuine care.", how_it_helps: "You both needed this. Neither of you was going to initiate it. You did. That matters more than you know." },
  { id: 60, emoji: "🌅", title: "Dance Alone in Your Kitchen", subtitle: "One song. No one watching. Let your body lead.", duration: "5 min", category: "Presence", color: "#E8845A", front_detail: "Your kitchen is a dance floor. It always has been.", science_title: "Spontaneous Movement & Bilateral Integration", science: "Spontaneous dance combines rhythmic entrainment, bilateral motor activation, and playful disinhibition — producing simultaneous dopamine, serotonin, and endorphin release. The absence of an audience removes performance anxiety entirely, leaving only the physiological benefits.", how_it_helps: "No one is watching. This is yours. Your body was designed to move to music. Let it remember." },
  { id: 61, emoji: "💪", title: "Progressive Muscle Relaxation", subtitle: "Tense each muscle group. Hold. Release. Work up the body.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "Start at your feet. Squeeze everything. Then let go.", science_title: "Neuromuscular Tension Release", science: "Edmund Jacobson's foundational research showed that deliberately tensing and releasing muscle groups reduces systemic anxiety by teaching the nervous system to distinguish tension from relaxation. Clinical trials consistently show PMR reduces both physiological and self-reported anxiety in 10-minute sessions.", how_it_helps: "Most chronic stress lives in the body as held muscle tension you've stopped noticing. This makes it visible, then removes it." },
  { id: 62, emoji: "🎯", title: "One-Leg Balance Practice", subtitle: "Stand on one foot. Eyes open, then closed. Switch.", duration: "5 min", category: "Grounding", color: "#7A9E7E", front_detail: "No wall. No props. Just you and your balance.", science_title: "Proprioception & Cerebellar Neuroplasticity", science: "Balance training activates the cerebellum and vestibular system simultaneously, strengthening the proprioceptive loop that keeps you spatially present. Research shows single-leg standing with eyes closed is a reliable predictor of longevity, and regular practice measurably improves it at any age.", how_it_helps: "Forces total presence. You cannot think about email while balancing on one leg with your eyes shut. The body takes over." },
  { id: 63, emoji: "🌞", title: "Sun Salutation", subtitle: "Three slow rounds. Feel each transition.", duration: "10 min", category: "Grounding", color: "#D4945A", front_detail: "Not a workout. A greeting. Do it slowly enough to breathe.", science_title: "Integrated Movement & HPA Axis Regulation", science: "The rhythmic, breath-linked movement of sun salutations activates the hypothalamic-pituitary-adrenal axis in a restorative direction. A 2019 study found 12 weeks of Surya Namaskar practice significantly reduced cortisol and inflammatory markers compared to controls.", how_it_helps: "A complete reset for the body — every major muscle group moves, every breath is counted, every transition is an invitation to arrive." },
  { id: 64, emoji: "🔄", title: "Walk Backward for 5 Minutes", subtitle: "Find a safe space. Walk backward, slowly.", duration: "5 min", category: "Presence", color: "#9B7BB8", front_detail: "A hallway, a garden, a quiet path. Reverse your momentum.", science_title: "Cognitive Disruption & Bilateral Brain Activation", science: "Backward walking activates the prefrontal cortex more strongly than forward walking by forcing active environmental monitoring. A 2019 study found participants who walked backward demonstrated improved working memory and had significantly better cognitive performance on subsequent tasks.", how_it_helps: "Makes the familiar strange. Forces your whole nervous system to pay attention. Everything you've been on autopilot for gets switched back on." },
  { id: 65, emoji: "🤲", title: "Self-Hand Massage", subtitle: "Both hands. Every finger. Take five minutes.", duration: "5 min", category: "Calm", color: "#A0785A", front_detail: "Your hands carry your whole day. Let them be cared for.", science_title: "Touch, Oxytocin & Cortisol Reduction", science: "Self-touch activates the same oxytocin pathways as touch from others. Research from the Touch Research Institute shows hand massage specifically reduces state anxiety by 30% and lowers salivary cortisol. The hands have more sensory nerve endings per square centimeter than almost any other body part.", how_it_helps: "Turns your own hands into the thing that comforts you. No equipment, no one else required. Just the act of attending to yourself." },
  { id: 66, emoji: "👁️", title: "Palming Eye Rest", subtitle: "Cup warm palms over closed eyes. Rest in darkness.", duration: "5 min", category: "Calm", color: "#6B8EA6", front_detail: "Rub palms warm first. Then shut out the world.", science_title: "Optic Nerve Recovery & Ciliary Muscle Release", science: "Extended screen use chronically contracts the ciliary muscles and overstimulates the optic nerve. Palming — covering the eyes with warm, cupped hands — produces complete darkness while gentle warmth relaxes periorbital muscles. Studies show 5-minute palming sessions meaningfully reduce digital eye strain.", how_it_helps: "Your eyes have processed thousands of images today. This is five minutes of nothing. Let them remember what darkness feels like." },
  { id: 67, emoji: "🌀", title: "Qi Gong Arm Swings", subtitle: "Let arms swing loosely side to side. 3 minutes.", duration: "5 min", category: "Calm", color: "#7A9E7E", front_detail: "Completely passive arms. Torso rotates. Arms just follow.", science_title: "Spinal Rotation & Lymphatic Circulation", science: "The passive arm swing of Qi Gong's 'Separating Heaven and Earth' movement stimulates the thoracic lymph nodes and decompresses lumbar vertebrae through gentle spinal rotation. Research shows Qi Gong practice reduces cortisol and increases natural killer cell activity within a single session.", how_it_helps: "The most effortless movement there is. Your arms are just along for the ride. Even the laziest version of this works." },
  { id: 68, emoji: "🦶", title: "Tennis Ball Foot Roll", subtitle: "Slow circles. Every part of the sole. Switch feet.", duration: "5 min", category: "Grounding", color: "#C8825A", front_detail: "Sitting or standing. The pressure does the work.", science_title: "Plantar Fascia & Nervous System Downregulation", science: "The plantar fascia contains a dense concentration of mechanoreceptors connected to the nervous system's tension-regulation pathways. Myofascial release through rolling stimulates these receptors, inhibiting sympathetic activation. Research on reflexology shows foot massage measurably reduces anxiety and blood pressure.", how_it_helps: "Your feet absorb every step of your stress. This is thirty seconds per foot of undoing that. It costs less than a cup of coffee." },
  { id: 69, emoji: "🫁", title: "4-7-8 Breathing", subtitle: "In 4. Hold 7. Out 8. Four rounds.", duration: "5 min", category: "Calm", color: "#6B8EA6", front_detail: "Dr. Andrew Weil's technique. Slower than you think you can manage.", science_title: "Extended Exhale & Parasympathetic Induction", science: "The 4-7-8 technique extends the exhalation significantly beyond the inhalation, which is the key driver of vagal nerve activation. Heart rate variability analysis shows significant parasympathetic dominance within two minutes of practice. The extended hold builds CO2 tolerance, training the breath-holding reflex.", how_it_helps: "If you do nothing else when anxious, do this. Four slow rounds will measurably change your physiological state." },
  { id: 70, emoji: "💆", title: "Scalp Massage", subtitle: "Fingertips only. Slow circles. Every part of your skull.", duration: "5 min", category: "Calm", color: "#9B7BB8", front_detail: "No oil needed. Just pressure and slow circles.", science_title: "Scalp Stimulation & Serotonin Pathways", science: "The scalp contains a dense network of sensory nerves connected to the trigeminal system. Japanese research found that 4 minutes of standardized scalp massage significantly increased thickness of dermal layers and activated serotonin pathways. Even self-administered scalp massage reduces tension headache frequency.", how_it_helps: "Almost no one touches their own head on purpose. This is that. It is surprisingly intimate and surprisingly effective." },
  { id: 71, emoji: "🎭", title: "Facial Tension Release", subtitle: "Open your mouth wide. Squeeze face tight. Release.", duration: "5 min", category: "Calm", color: "#A0785A", front_detail: "Make the most ridiculous faces possible. For your own relief.", science_title: "Facial Musculature & Emotional Feedback Loop", science: "The facial action coding system research shows a bidirectional relationship: not only do emotions create facial expressions, but facial movements themselves create corresponding emotional states (facial feedback hypothesis). Releasing chronic facial tension held from stress has direct downstream effects on mood regulation.", how_it_helps: "You have been clenching your jaw and furrowing your brow all day without knowing it. This gives your face permission to stop performing." },
  { id: 72, emoji: "🌊", title: "Therapeutic Shaking", subtitle: "Shake every limb. Let the tremor move through you.", duration: "5 min", category: "Calm", color: "#7A9E7E", front_detail: "Start at your hands. Let it travel up. Full body trembling.", science_title: "Trauma Release & Sympathetic Discharge", science: "Animals naturally shake after a threat response to discharge excess adrenaline and cortisol — a mechanism described in Peter Levine's Somatic Experiencing work. TRE (Tension & Trauma Releasing Exercises) research shows voluntary shaking reduces muscle tension, PTSD symptoms, and chronic anxiety through neurogenic tremor.", how_it_helps: "Your nervous system knows how to do this. You've been holding the shaking in. This is permission to let it out safely." },
  { id: 73, emoji: "🧊", title: "Cold Water Face Plunge", subtitle: "Fill a bowl with cold water. Submerge your face 30 seconds.", duration: "3 min", category: "Calm", color: "#6B8EA6", front_detail: "Add ice if you can. Hold longer than is comfortable.", science_title: "Dive Reflex & Acute Parasympathetic Response", science: "Cold water immersion of the face triggers the mammalian dive reflex, reducing heart rate by 10-25% within seconds through vagal activation. Used clinically in DBT (Dialectical Behavior Therapy) as a TIPP skill for acute emotional dysregulation. The mechanism is physiological, not psychological — it works immediately.", how_it_helps: "When your mind won't cooperate, your body will. This is the fastest known route to physiological calm that anyone can do at home." },
  { id: 74, emoji: "🌿", title: "Legs Up the Wall", subtitle: "Lie down. Legs straight up the wall. Stay 10 minutes.", duration: "10 min", category: "Calm", color: "#7A9E7E", front_detail: "Viparita Karani. The most restoring pose with no effort.", science_title: "Venous Return & Nervous System Reset", science: "Elevating the legs above the heart reverses venous pooling in the lower limbs, improves cardiac output efficiency, and activates baroreceptors that signal the nervous system to downregulate. Studies of restorative yoga show this pose produces deeper physiological rest than savasana alone in many subjects.", how_it_helps: "No strength, no flexibility, no skill. Just gravity doing the opposite of what it does all day. Your heart is grateful." },
  { id: 75, emoji: "🫀", title: "Physiological Sigh", subtitle: "Double inhale through the nose. Long exhale through the mouth.", duration: "3 min", category: "Calm", color: "#6B8EA6", front_detail: "Two sniffs in, then one long, slow release. Repeat.", science_title: "Alveolar Re-inflation & Rapid Stress Reduction", science: "Stanford neuroscientist Andrew Huberman's research identified the physiological sigh as the fastest known way to reduce physiological stress in real time. The double inhale maximally inflates collapsed alveoli, and the extended exhale activates the vagus nerve. Even one sigh produces measurable heart rate reduction within seconds.", how_it_helps: "One breath. Thirty seconds. Genuinely the fastest evidence-based thing you can do for yourself anywhere, at any moment." },
  { id: 76, emoji: "🏔️", title: "Static Wall Sit", subtitle: "Slide down a wall until thighs are parallel. Hold.", duration: "5 min", category: "Grounding", color: "#C1603A", front_detail: "Sixty seconds feels very long. Start there.", science_title: "Isometric Exercise & Endorphin Release", science: "Isometric exercises like wall sits produce sustained muscle tension that triggers endorphin release without joint stress. Research shows brief isometric holds significantly raise pain threshold and mood. The sustained focus required also quiets the default mode network — identical to meditation in its cognitive effects.", how_it_helps: "Your body has a problem to solve. It will stop worrying about other things. The discomfort is the point: you chose it, and you're managing it." },
  { id: 77, emoji: "🌬️", title: "Alternate Nostril Breathing", subtitle: "Cover right nostril, breathe in left. Switch. Repeat.", duration: "5 min", category: "Calm", color: "#7A9E7E", front_detail: "Nadi Shodhana. The oldest known breathing technique.", science_title: "Hemispheric Synchronization & ANS Balance", science: "Nadi Shodhana pranayama has been studied extensively for its effects on hemispheric EEG synchronization. Research shows it balances left and right hemisphere activity and reduces sympathetic nervous system dominance. Studies report significant reductions in heart rate, blood pressure, and perceived stress after 5-minute sessions.", how_it_helps: "Creates a perceptible, almost immediate sense of balance and calm. The specific mechanism is different from other breathing techniques — you can feel the difference." },
  { id: 78, emoji: "👃", title: "Bhramari Humming Breath", subtitle: "Close ears with thumbs, eyes with fingers. Hum on exhale.", duration: "5 min", category: "Calm", color: "#9B7BB8", front_detail: "Bee breath. The sound resonates in your skull.", science_title: "Nitric Oxide Production & Sinus Resonance", science: "Humming increases nasal nitric oxide production by 15-fold compared to silent breathing. Nitric oxide is a vasodilator that improves oxygen exchange and has direct anxiolytic effects. The internal resonance of Bhramari also stimulates the vagus nerve through laryngeal vibration, producing measurable heart rate slowing.", how_it_helps: "The sound fills your head completely. Nothing else can fit in there. That's not a metaphor — it's acoustics." },
  { id: 79, emoji: "🤸", title: "Spinal Wave Sequence", subtitle: "Cat, cow, child's pose, seated twist. Move like water.", duration: "8 min", category: "Grounding", color: "#C8825A", front_detail: "Your spine moved in every direction today — except it didn't.", science_title: "Intervertebral Disc Nutrition & Parasympathetic Activation", science: "Spinal movement is the primary mechanism by which intervertebral discs receive nutrients (they lack direct blood supply). Gentle spinal flexion, extension, and rotation during yoga significantly improves disc health markers. The sequence also activates the vagus nerve through abdominal compression and release.", how_it_helps: "Your spine sat in one position all day. It wants to move. Give it five minutes and it will thank you immediately and specifically." },
  { id: 80, emoji: "💧", title: "Contrast Shower", subtitle: "30 seconds hot, 30 seconds cold. Three rounds.", duration: "10 min", category: "Grounding", color: "#6B8EA6", front_detail: "End on cold. Every time. Non-negotiable.", science_title: "Thermal Contrast & Norepinephrine Release", science: "Cold-to-hot thermal contrast causes significant norepinephrine release (up to 300% increase documented in Wim Hof research), improving alertness and mood. The alternating dilation and constriction of blood vessels creates a pumping effect in the lymphatic system. Multiple studies confirm cold exposure reduces depression scores.", how_it_helps: "Generates a completely different body state in under ten minutes. The cold is uncomfortable in a way that is under your control — which matters." },
  { id: 81, emoji: "🧠", title: "Memory Palace Construction", subtitle: "Pick a familiar route. Place five things to remember along it.", duration: "15 min", category: "Curiosity", color: "#9B7BB8", front_detail: "Home to a park. Five memories. One image per location.", science_title: "Spatial Memory & Hippocampal Engagement", science: "The method of loci (memory palace) exploits the brain's extraordinarily powerful spatial memory systems, which evolved for navigating three-dimensional environments. fMRI studies of memory champions show intense hippocampal activation during memory palace use. The technique transfers to general hippocampal health over time.", how_it_helps: "Your brain already remembers every route you've ever walked. This uses that power intentionally, and builds the memory capacity itself." },
  { id: 82, emoji: "🔢", title: "Mental Arithmetic Practice", subtitle: "Multiply three two-digit numbers. No paper.", duration: "10 min", category: "Curiosity", color: "#6B8EA6", front_detail: "23 × 47 × 12. Work it slowly in your head.", science_title: "Working Memory Training & Prefrontal Engagement", science: "Mental arithmetic is one of the strongest known activators of working memory and the dorsolateral prefrontal cortex. Regular mental math practice has been linked to preserved cognitive function in aging populations. It also produces neuroplasticity markers similar to physical exercise — BDNF (brain-derived neurotrophic factor) increase.", how_it_helps: "Your phone does all your arithmetic. Your prefrontal cortex is losing the habit of sustained focus. This gives it back." },
  { id: 83, emoji: "🔍", title: "Lateral Thinking Puzzle", subtitle: "One situation puzzle. Work it to the end before looking it up.", duration: "15 min", category: "Curiosity", color: "#9B7BB8", front_detail: "The goal is the process, not the answer.", science_title: "Insight Problem Solving & Right Hemisphere Activation", science: "Lateral thinking puzzles activate right temporal lobe regions associated with insight — the neural substrate of the 'aha moment'. Research shows sustained engagement with insight problems increases gamma wave activity, associated with novel idea generation. The discomfort of not knowing is itself the cognitive stimulus.", how_it_helps: "Trains your mind to hold a question without grasping for an answer. That capacity is rare and valuable." },
  { id: 84, emoji: "📖", title: "One Page of Philosophy", subtitle: "Read slowly. Stop at each claim. Do you agree?", duration: "15 min", category: "Curiosity", color: "#9B7BB8", front_detail: "Marcus Aurelius. Epictetus. Spinoza. Just one page.", science_title: "Abstract Reasoning & Prefrontal Cortex Development", science: "Engaging with philosophical text — following abstract arguments, evaluating premises, imagining counter-cases — activates the prefrontal cortex in complex patterns associated with higher-order reasoning. Longitudinal studies show humanities reading correlates with preserved executive function and reduced cognitive decline.", how_it_helps: "One page is enough. The point is that you slowed down enough to actually think about what you believe. That is rare." },
  { id: 85, emoji: "🗺️", title: "Study a Map of Somewhere New", subtitle: "Pick a place you know nothing about. Learn its geography.", duration: "15 min", category: "Curiosity", color: "#6B8EA6", front_detail: "Mongolia. Patagonia. The Faroe Islands. Just look.", science_title: "Spatial Cognition & Curiosity-Driven Learning", science: "Map reading activates visuospatial reasoning centers and the hippocampus simultaneously. Dr. Gruber's curiosity research at UC Davis shows curiosity-activated states prime the brain for information retention — content encountered during curious exploration is remembered 40% more effectively than rote learning.", how_it_helps: "Somewhere right now, people are living completely different lives in this geography you just discovered. That expansion of frame is healthy." },
  { id: 86, emoji: "🔭", title: "Learn One Space Mission", subtitle: "Pick any mission. Read everything about it.", duration: "20 min", category: "Curiosity", color: "#2C4A30", front_detail: "Voyager. Cassini. Opportunity. Pick one and go deep.", science_title: "Awe-Induced Self-Transcendence & Perspective Expansion", science: "Keltner's awe research identifies vast, complex, science-rich subjects as potent triggers of the awe response — which demonstrably reduces self-referential anxiety, expands time perception, and increases prosocial motivation. Space topics reliably trigger this response.", how_it_helps: "We sent a machine to the rings of Saturn and received photographs. Reading about this is not escapism. It is perspective." },
  { id: 87, emoji: "📚", title: "Etymology Dive", subtitle: "Pick five words. Look up every part of their history.", duration: "15 min", category: "Curiosity", color: "#A0785A", front_detail: "'Salary' comes from salt. Every word has a story.", science_title: "Language Networks & Semantic Memory Enhancement", science: "Etymology study activates both semantic and episodic memory networks simultaneously. Research on vocabulary acquisition shows that understanding a word's origin makes it 60% more memorable and deepens comprehension of related words through morpheme recognition — strengthening the entire semantic web.", how_it_helps: "Language becomes strange and alive when you see where words came from. Every sentence you speak carries thousands of years of human history." },
  { id: 88, emoji: "🎲", title: "Logic Puzzle Sprint", subtitle: "One Sudoku, KenKen, or nonogram. Complete it.", duration: "15–20 min", category: "Curiosity", color: "#6B8EA6", front_detail: "Rule-based deduction. Every move has an answer.", science_title: "Constraint Satisfaction & Dopaminergic Reward", science: "Logic puzzles activate the dorsal striatum through a continuous cycle of hypothesis testing and reward feedback. Research on puzzle-solving shows sustained engagement with constraint satisfaction problems produces dopamine micro-rewards with each deductive step, creating a self-reinforcing flow state.", how_it_helps: "A problem that has exactly one solution and rewards patient, systematic thought. This is increasingly rare. Savor it." },
  { id: 89, emoji: "🌍", title: "Learn Five Words in a New Language", subtitle: "Any language. Say them aloud. Use them in a sentence.", duration: "10 min", category: "Curiosity", color: "#7A9E7E", front_detail: "Not for a trip. Not to be impressive. Just for the love of it.", science_title: "Phonological Processing & Anterior Cingulate Activation", science: "Even minimal second-language exposure forces the anterior cingulate cortex out of habitual processing pathways. Novel phonemes require the brain to build new motor programs in Broca's area. Research shows even a single session of new-language exposure improves cognitive flexibility scores on unrelated tasks.", how_it_helps: "Another language is another way of experiencing the world. Even five words opens a small door." },
  { id: 90, emoji: "🔬", title: "Read One Scientific Abstract", subtitle: "Any field. Read carefully. Look up every unfamiliar term.", duration: "15 min", category: "Curiosity", color: "#6B8EA6", front_detail: "PubMed, arXiv, Google Scholar. One abstract, fully understood.", science_title: "Domain-Unfamiliar Learning & Neural Flexibility", science: "Engaging with technical material outside one's domain activates prefrontal regions associated with conceptual mapping — building bridges between known and unknown knowledge structures. Research in transfer learning shows breadth of domain exposure significantly improves problem-solving in the primary domain.", how_it_helps: "The world is stranger and more discovered than you think. One abstract is proof of that." },
  { id: 91, emoji: "✍️", title: "Copy a Text by Hand", subtitle: "Find a paragraph you love. Transcribe it word by word.", duration: "10 min", category: "Making", color: "#C1603A", front_detail: "A letter, a poem, a recipe. Copy it slowly.", science_title: "Haptic Encoding & Deep Memory Formation", science: "Handwriting engages visual, motor, and linguistic cortices simultaneously — a multimodal encoding that typing lacks. Studies show handwritten notes are retained with significantly more depth than typed ones. Transcribing another's writing produces a form of muscle memory for their sentence rhythms and rhetorical patterns.", how_it_helps: "You feel every word differently when your hand traces it. Writing it makes it yours in a way reading never does." },
  { id: 92, emoji: "🌿", title: "Origami Crane", subtitle: "One sheet of paper. Fold from memory or follow steps.", duration: "15 min", category: "Making", color: "#7A9E7E", front_detail: "Slow. No shortcuts. The paper remembers every crease.", science_title: "Procedural Memory & Flow State Induction", science: "Origami engages procedural memory, visuospatial reasoning, and fine motor control in a uniquely integrated way. Research on origami in occupational therapy shows consistent flow state induction, reduced anxiety scores, and improved fine motor precision. The iterative correction process builds error-tolerance.", how_it_helps: "A piece of paper becomes a bird. That's not a small thing. You made something from nothing, with nothing." },
  { id: 93, emoji: "🎨", title: "Watercolor Wash", subtitle: "Wet the paper. Drop in color. Watch it move.", duration: "15 min", category: "Making", color: "#E8845A", front_detail: "No brushwork. Just water, pigment, and gravity.", science_title: "Relinquished Control & Anxiety Reduction", science: "The unpredictability of wet-into-wet watercolor forces the release of outcome control — a practice directly mirroring mindfulness-based acceptance. Art therapy research shows the most significant anxiety reductions occur in activities where the practitioner cannot fully control the outcome, because the act of letting go is the therapeutic mechanism.", how_it_helps: "The water goes where it goes. Your only job is to stay curious about what happens next." },
  { id: 94, emoji: "✂️", title: "Paper Cutting", subtitle: "Fold paper, cut shapes. Open it. Be surprised.", duration: "10 min", category: "Making", color: "#9B7BB8", front_detail: "No pattern. Fold in half, quarter, eighth. Cut shapes. Open.", science_title: "Spatial Visualization & Bilateral Hand Coordination", science: "Paper cutting requires continuous spatial visualization — predicting what the unfolded result will look like from a folded cut. This activates the parietal lobe's spatial processing centers and improves spatial reasoning scores. The bilateral hand coordination also integrates left-right brain hemisphere processing.", how_it_helps: "You cannot know what you made until you open it. That surprise is a small form of wonder, available every time." },
  { id: 95, emoji: "🏺", title: "Air-Dry Clay", subtitle: "Make one small thing. Any shape. No plan.", duration: "20 min", category: "Making", color: "#A0785A", front_detail: "A bowl, a face, an abstract lump. It dries real.", science_title: "Tactile Manipulation & Frontal Lobe Quieting", science: "Working with clay produces sustained tactile stimulation across the entire hand, activating the sensory cortex in ways that quiet frontal lobe overactivity — the source of rumination and anxiety. Art therapy research specifically identifies clay work as producing the deepest measurable reductions in state anxiety among creative modalities.", how_it_helps: "Your hands know what to do. Let them go. The clay doesn't judge what you make. Neither should you." },
  { id: 96, emoji: "🖼️", title: "Collage Making", subtitle: "Old magazines, scissors, glue. Make something from pieces.", duration: "20 min", category: "Making", color: "#C8825A", front_detail: "No theme. Just cut what catches your eye.", science_title: "Curation, Agency & Visual Narrative Construction", science: "Collage-making engages the same brain regions as visual narrative comprehension — the right hemisphere processes visual relationships while the left makes meaning of juxtapositions. The curatorial act of selection and arrangement activates a sense of agency and aesthetic mastery shown to reduce helplessness states.", how_it_helps: "You are making something out of existing things. Editing the world rather than creating from scratch. That's a different kind of power." },
  { id: 97, emoji: "🌱", title: "Terrarium Building", subtitle: "A jar, some soil, a small plant. Build a tiny world.", duration: "30 min", category: "Making", color: "#6B9E6B", front_detail: "Anything glass works. Pebbles, moss, one plant.", science_title: "Miniature World Creation & Attention Restoration", science: "Creating enclosed natural miniature environments produces fascination responses — the effortless attention described in Attention Restoration Theory (Kaplan, 1995). The contained, manipulable scale gives the creator complete environmental mastery, restoring depleted directed-attention resources.", how_it_helps: "You built an entire world in a jar. It is alive. It requires almost nothing from you. And it will outlast this terrible week." },
  { id: 98, emoji: "🎋", title: "Zentangle Drawing", subtitle: "Fill one square with repeated patterns. No planning.", duration: "20 min", category: "Making", color: "#7B6E8D", front_detail: "Pen only. No erasing. Repetitive marks within the square.", science_title: "Repetitive Mark-Making & Meditative Focus", science: "Zentangle's structured-yet-repetitive drawing method has been specifically studied for anxiety reduction. Research published in Art Therapy found measurable reductions in state anxiety equivalent to guided meditation, with the additional benefit that it is accessible to people who resist sitting still.", how_it_helps: "No drawing skills needed. The patterns repeat and the mind quiets. The pen does the thinking." },
  { id: 99, emoji: "🌾", title: "Pressed Flowers", subtitle: "Gather a few flowers or leaves. Press them in a heavy book.", duration: "15 min", category: "Making", color: "#7A9E7E", front_detail: "Check them in two weeks. Time will make them beautiful.", science_title: "Anticipatory Joy & Preservation Ritual", science: "Collecting and preserving natural objects activates the ventral striatum through anticipated reward — the pleasure of knowing something beautiful is transforming slowly. Research on anticipatory positive affect shows the waiting itself generates wellbeing nearly as strong as the eventual outcome.", how_it_helps: "You are giving your future self a gift. In two weeks, you'll open that book and find something you made today." },
  { id: 100, emoji: "🕯️", title: "Candle Making", subtitle: "Melt wax, pour, set a wick. Make one candle.", duration: "30 min", category: "Making", color: "#D4945A", front_detail: "Basic soy wax and a wick. It's simpler than you think.", science_title: "Embodied Production & Reward Prediction Error", science: "Making a functional object engages the ventromedial prefrontal cortex through what researchers call the 'IKEA effect' — the tendency to value things we create ourselves disproportionately more than identical manufactured objects. The eventual act of lighting your own candle produces significantly stronger positive affect.", how_it_helps: "You made light. Literally. That is a thing humans have done for 70,000 years. Tonight you'll light it and feel that." },
  { id: 101, emoji: "🌲", title: "Forest Bathing", subtitle: "Walk slowly in any green space. No destination. No phone.", duration: "20 min", category: "Presence", color: "#2C4A30", front_detail: "Shinrin-yoku. The Japanese practice that changed medicine.", science_title: "Phytoncide Inhalation & NK Cell Activation", science: "Dr. Qing Li's landmark research in Japan showed that 2-hour forest walks increase natural killer cell activity by 40% for up to 30 days afterward. Trees emit phytoncides — antimicrobial volatile organic compounds that directly activate human immune cells. Forest environments also dramatically lower cortisol and adrenaline.", how_it_helps: "Every moment in a forest is doing something to your biology that no medication replicates. Even an urban park has measurable effect." },
  { id: 102, emoji: "☁️", title: "Cloud Identification", subtitle: "Go outside. Name every cloud type you can see.", duration: "15 min", category: "Presence", color: "#6B8EA6", front_detail: "Cumulus. Cirrus. Stratus. Cumulonimbus. Look and name.", science_title: "Perceptual Attention & Sky Gazing", science: "Deliberate cloud observation requires sustained upward gaze — a postural shift correlated with increased divergent thinking in multiple studies. The Cloud Appreciation Society's research found regular cloud-gazing significantly reduces anxiety and increases a sense of perspective. Identifying species adds cognitive engagement.", how_it_helps: "The sky is the most freely available art installation in the world. It changes every minute. It has no subscription fee." },
  { id: 103, emoji: "🌱", title: "Smell the Soil", subtitle: "Dig a handful of garden soil. Smell it slowly.", duration: "5 min", category: "Grounding", color: "#6B9E6B", front_detail: "That smell is geosmin. It's why humans evolved to love it.", science_title: "Petrichor, Geosmin & Serotonin Activation", science: "Geosmin — the molecule that gives soil its distinctive smell — is produced by Streptomyces bacteria. Research shows Mycobacterium vaccae in soil triggers serotonin production when absorbed through skin or inhaled. Human sensitivity to geosmin is extreme (parts per trillion), suggesting deep evolutionary significance of human-soil interaction.", how_it_helps: "Your ancestors evolved to love this smell because soil meant water, food, and survival. Your nervous system still knows this." },
  { id: 104, emoji: "🪨", title: "Rock Collection Walk", subtitle: "Walk a short route. Collect only what genuinely interests you.", duration: "20 min", category: "Grounding", color: "#A0785A", front_detail: "No geological knowledge required. Attraction is enough.", science_title: "Curiosity-Driven Collecting & Tactile Satisfaction", science: "Object collection engages the reward system through repeated small discoveries. Handling stones activates the sensory cortex through varied tactile input (weight, texture, temperature, smoothness) — providing grounding sensory information that interrupts anxious mental cycling. Children naturally collect; the impulse survives into adulthood.", how_it_helps: "You are choosing things from the world and bringing them home. Each one is a small decision that was entirely yours." },
  { id: 105, emoji: "🌳", title: "Tree Bark Rubbing", subtitle: "Paper against bark. Rub a crayon or pencil. Reveal the tree.", duration: "15 min", category: "Making", color: "#6B9E6B", front_detail: "Every tree has a completely different texture. Collect five.", science_title: "Texture Perception & Nature Connection", science: "Bark rubbing requires sustained tactile contact with tree surfaces while producing a physical record. Research on nature engagement through touch shows tactile interaction with natural materials activates the somatosensory cortex in patterns associated with calm and reduces cortisol more than visual contact alone.", how_it_helps: "You bring a piece of the tree home. The paper holds a moment of genuine contact with something much older than you." },
  { id: 106, emoji: "🐦", title: "Birdsong Identification", subtitle: "Sit still outside. List every bird sound you hear.", duration: "15 min", category: "Presence", color: "#7A9E7E", front_detail: "Don't know the names? Describe the sounds anyway.", science_title: "Auditory Discrimination & Presence Induction", science: "Research from the University of Exeter found that birdsong is one of the strongest predictors of positive affect in urban environments. The cognitive task of discriminating individual bird sounds from ambient noise requires focused auditory attention — producing the same presence-induction as formal meditation.", how_it_helps: "Birdsong tells your nervous system that the environment is safe. Evolutionary biology: predators go quiet. Birds don't." },
  { id: 107, emoji: "🌧️", title: "Sit with Rain", subtitle: "Find a covered spot. Watch and listen to rain fall.", duration: "15 min", category: "Presence", color: "#6B8EA6", front_detail: "Not through glass. Be near it. Hear the full sound.", science_title: "Pink Noise, 1/f Patterns & Cortical Entrainment", science: "Rain produces 1/f (pink noise) frequency patterns that mirror the statistical structure of resting neural oscillations. Research shows pink noise exposure improves slow-wave sleep, reduces anxiety, and synchronizes brain waves toward calm, alert states. The pattern is mathematically similar to relaxed brain activity itself.", how_it_helps: "You don't need to do anything with the rain. Just be near it. Your brain will synchronize to it automatically." },
  { id: 108, emoji: "🕸️", title: "Watch a Spider Web", subtitle: "Find a web. Watch it for five full minutes.", duration: "5–10 min", category: "Presence", color: "#7A9E7E", front_detail: "Look for the light through it. Watch for movement.", science_title: "Micro-Awe & Self-Transcendence", science: "Research on micro-awe by Keltner's lab shows that sustained attention to small-scale complex natural structures — spider webs, crystals, wing patterns — reliably triggers the awe response. Even 3-5 minutes reduces default mode network self-referential chatter and expands perceived time.", how_it_helps: "A spider built that from its own body while you slept. Watching it is a form of reverence that costs nothing." },
  { id: 109, emoji: "🌊", title: "Stream or River Sitting", subtitle: "Find moving water. Sit close enough to hear it. Stay.", duration: "15 min", category: "Calm", color: "#6B8EA6", front_detail: "Moving water. Not a screen of moving water. The real thing.", science_title: "Negative Ionization & Limbic Calming", science: "Moving water produces negative air ions through the Lenard effect — the same ions found at waterfalls, after rain, and at the ocean. Research shows negative ion exposure significantly reduces serotonin uptake, with antidepressant effects comparable to some medications. The effect requires actual proximity to the water source.", how_it_helps: "The air at moving water is genuinely different. This is chemistry, not romance. You can feel it within minutes." },
  { id: 110, emoji: "🌕", title: "Moon Phase Tracking", subtitle: "Step outside. Find the moon. Journal its shape.", duration: "5 min", category: "Grounding", color: "#2C4A30", front_detail: "What phase is it? What does it look like tonight?", science_title: "Circadian Rhythm Awareness & Temporal Grounding", science: "Tracking natural cycles activates temporal awareness — a sense of one's own location in time that is increasingly lost in our schedule-driven world. Research shows that people with stronger connections to natural cycles report lower anxiety and better sleep, consistent with intact circadian rhythm function.", how_it_helps: "The moon follows a 29.5-day pattern that has nothing to do with you. Tracking it anchors you in something larger than your calendar." },
  { id: 111, emoji: "❄️", title: "Frost or Dew Pattern Observation", subtitle: "Early morning. Look at every frosted or dewy surface slowly.", duration: "10 min", category: "Presence", color: "#6B8EA6", front_detail: "Blades of grass. Leaves. Spiderwebs. Every surface is different.", science_title: "Perceptual Freshness & Novelty Detection", science: "Morning light conditions and transient natural phenomena like frost or dew require perceptual freshness — an active choice to notice what is available only briefly. Research on savoring shows that attending to transient beauty produces significantly stronger positive affect than attending to permanent features.", how_it_helps: "This will be gone in an hour. That is why it matters right now." },
  { id: 112, emoji: "🍂", title: "Leaf Pressing", subtitle: "Collect five interesting leaves. Press them in a heavy book.", duration: "15 min", category: "Making", color: "#D4945A", front_detail: "Different shapes, colors, textures. Let the book do the work.", science_title: "Collection, Anticipation & Aesthetic Preservation", science: "The act of collecting and preserving natural objects combines biophilic engagement with anticipatory pleasure. Research on botanical collection shows it activates the ventral striatum through the anticipation of an artifact that doesn't yet exist — a uniquely human form of deferred gratification.", how_it_helps: "In three weeks, you'll open that book and the autumn will still be there." },
  { id: 113, emoji: "🌀", title: "Sand or Soil Drawing", subtitle: "Draw in dirt, sand, or gravel with a stick.", duration: "10 min", category: "Making", color: "#A0785A", front_detail: "It doesn't matter what you make. It will be erased.", science_title: "Ephemeral Art & Attachment Release", science: "Making art that is inherently temporary produces a distinct psychological state studied in the context of sand mandalas. Buddhist psychology and Western art therapy both document that ephemeral creation reduces attachment to outcomes and increases present-moment focus. The deletion is part of the practice.", how_it_helps: "You can make whatever you want because it will be gone. That freedom is rarer than you realize." },
  { id: 114, emoji: "✍️", title: "Write a Thank-You Note by Hand", subtitle: "To anyone. One specific, true thing you're grateful for.", duration: "10 min", category: "Connection", color: "#C1603A", front_detail: "Not a card. A real letter. One thing, said honestly.", science_title: "Gratitude Expression & Relationship Strengthening", science: "Dr. Martin Seligman's 'gratitude visit' research found that delivering a handwritten gratitude letter produced lasting increases in wellbeing for both writer and recipient — the writer's wellbeing elevated significantly for a full month. Writing the letter produced immediate measurable mood improvement even before sending.", how_it_helps: "You thought of them, and told them specifically why. That is an increasingly rare act. The specificity is what makes it real." },
  { id: 115, emoji: "🍳", title: "Cook for Someone Else", subtitle: "Make one thing specifically for another person to enjoy.", duration: "30 min", category: "Connection", color: "#C8825A", front_detail: "Consider what they love. Make it well. Give it without expectation.", science_title: "Prosocial Giving & Dopamine-Oxytocin Co-release", science: "Preparing food specifically for another person activates both dopamine (anticipatory reward) and oxytocin (social bonding) circuits simultaneously. This is a compound wellbeing effect documented to be greater than receiving food, receiving a gift, or making food for oneself. Cooking for others is one of the oldest forms of love.", how_it_helps: "You thought about another person long enough to make something for them. That thinking is the gift, before the food." },
  { id: 116, emoji: "💌", title: "Leave an Anonymous Kind Note", subtitle: "Write something kind. Leave it somewhere a stranger will find it.", duration: "10 min", category: "Connection", color: "#E8845A", front_detail: "A bench, a book in a library, a car windscreen.", science_title: "Anonymized Giving & Helper's High Without Social Cost", science: "Anonymous acts of kindness produce the helper's high (mesolimbic dopamine activation) without the social complexity of acknowledged giving. Research shows anonymous giving maintains the wellbeing benefit while removing the potential social awkwardness that can diminish the joy of recognized generosity.", how_it_helps: "Someone will find it and not know who wrote it. You will know. That gap is a kind of private joy." },
  { id: 117, emoji: "👂", title: "Practice Deep Listening", subtitle: "Let someone speak without interrupting, advising, or solving.", duration: "15 min", category: "Connection", color: "#7A9E7E", front_detail: "No fixing. No stories of your own. Just listening.", science_title: "Attentive Listening & Social Nervous System Regulation", science: "Stephen Porges' polyvagal theory shows that being genuinely listened to activates the ventral vagal complex — the social nervous system's 'safe-connect' mode. The listener also benefits through the cultivation of prosocial neural circuits associated with empathy. Research shows attentive listeners are rated as significantly more trustworthy and competent.", how_it_helps: "Everyone walks around being half-listened to. You giving full, quiet attention is a genuinely radical act." },
  { id: 118, emoji: "📹", title: "Video Call a Distant Friend", subtitle: "Just to see their face. Nothing to report.", duration: "20 min", category: "Connection", color: "#C1603A", front_detail: "Not to catch up. Not because something happened. Just because.", science_title: "Face-to-Face Contact & Mirror Neuron Activation", science: "Video calls, unlike phone calls, activate mirror neuron systems through facial expression observation. Research comparing phone to video calls shows significantly greater oxytocin release during face-to-face video contact. The 'just because' framing removes the social cost that prevents spontaneous connection.", how_it_helps: "They will wonder why you called. You can tell them, or not. Either way, both of you will be glad you did." },
  { id: 119, emoji: "📝", title: "Teach Someone One Skill", subtitle: "One thing you know how to do. Teach it, however small.", duration: "20 min", category: "Connection", color: "#7B6E8D", front_detail: "Folding a fitted sheet. A card trick. One cooking technique.", science_title: "The Protégé Effect & Knowledge Consolidation", science: "Research on the protégé effect shows that teaching something consolidates the teacher's own understanding more powerfully than additional study. Explaining knowledge to others requires identifying gaps in one's own model — producing the most durable form of learning and increasing the teacher's self-efficacy.", how_it_helps: "You know more than you think. And someone benefits from what you know. Teaching reveals both facts simultaneously." },
  { id: 120, emoji: "🎲", title: "Play a Board Game", subtitle: "One board or card game. With another human.", duration: "30 min", category: "Connection", color: "#C1603A", front_detail: "Not on a screen. In the same room.", science_title: "Playful Social Interaction & Relationship Quality", science: "Research on adult play from Stuart Brown's Play Institute shows that shared playful activity — particularly games with mild competition and laughter — is among the most effective known methods for relationship maintenance and repair. Play creates oxytocin bonding equivalent to shared vulnerability.", how_it_helps: "You are competing with someone and laughing about it. That is a completely different mode of relating to a person." },
  { id: 121, emoji: "👴", title: "Interview an Elder", subtitle: "Ask one person what life was like when they were your age.", duration: "30 min", category: "Connection", color: "#A0785A", front_detail: "Not their advice. Their life. The specific details.", science_title: "Narrative Identity & Intergenerational Bonding", science: "Listening to elder narratives activates perspective-taking circuits and strengthens narrative identity — the individual's own sense of their life as a coherent story. Research shows that people with stronger connections to intergenerational stories demonstrate greater resilience and psychological flexibility.", how_it_helps: "Everyone over 70 has lived through things that would break what we think of as normal. They also somehow didn't break." },
  { id: 122, emoji: "🙏", title: "Tell Someone What You Admire", subtitle: "One specific thing. In person or in writing.", duration: "5 min", category: "Connection", color: "#7A9E7E", front_detail: "Not a general compliment. Something specific and true.", science_title: "Received Admiration & Self-Concept Clarity", science: "Research on the 'freshness of admiration' effect shows that telling someone what specifically you admire about them provides them with self-concept clarity — a firmer sense of how they are perceived — which is associated with greater life satisfaction and lower anxiety than self-generated self-esteem.", how_it_helps: "You see something in them that they may not be sure is there. Saying it is a gift that costs nothing to give." },
  { id: 123, emoji: "📬", title: "Write a Letter to a Pen Pal", subtitle: "Find one. Write to them. A real letter, on paper.", duration: "30 min", category: "Connection", color: "#9B7BB8", front_detail: "Slowly Changing the World, postcrossing.com, a friend abroad.", science_title: "Correspondence, Delayed Gratification & Anticipatory Joy", science: "Written correspondence activates a distinct set of social cognition processes — constructing what to communicate to someone who cannot respond immediately requires sustained perspective-taking. The wait for a reply produces anticipatory positive affect, a wellbeing state research shows is as powerful as the reward itself.", how_it_helps: "Someone is going to open something you made with your hands. That's a different category of connection than text." },
  { id: 124, emoji: "🫶", title: "Volunteer for One Hour", subtitle: "Find a local organization. Show up once. Do one thing.", duration: "60 min", category: "Connection", color: "#6B9E6B", front_detail: "Food bank. Animal shelter. Park cleanup. Just once.", science_title: "Prosocial Behavior & Subjective Wellbeing", science: "A meta-analysis of 40 studies found volunteering is associated with a 22% reduction in mortality risk and significant increases in life satisfaction. Even a single volunteering session produces the helper's high. The effect is strongest when the volunteer has direct human contact rather than anonymous contribution.", how_it_helps: "An hour in service of something beyond yourself changes how the rest of the day feels. This has been documented reliably." },
  { id: 125, emoji: "😊", title: "Genuinely Smile at Three Strangers", subtitle: "Not a polite smile. A real one. Eye contact.", duration: "10 min", category: "Connection", color: "#E8845A", front_detail: "On a walk, in a shop, waiting somewhere.", science_title: "Duchenne Smile & Social Affiliative Response", science: "Genuine smiling (engaging the orbicularis oculi muscle — the Duchenne marker) activates the reward systems in both the smiler and the recipient. Research shows authentic smiling in brief encounters increases both parties' sense of social belonging and reduces cortisol within minutes of the interaction.", how_it_helps: "You are offering a tiny dose of human warmth to people who are probably more depleted than they look. So are you." },
  { id: 126, emoji: "🎵", title: "Create a Collaborative Playlist", subtitle: "Share a playlist. Ask them to add five songs. Listen together.", duration: "20 min", category: "Connection", color: "#7B6E8D", front_detail: "The adding is the conversation.", science_title: "Musical Self-Disclosure & Intimacy Building", science: "Research on music preferences shows that sharing music creates intimacy equivalent to personal disclosure. Each song added to a shared playlist is a form of emotional self-revelation — the receiver gains insight into inner states the giver may not be able to express directly. Music is a language for what words can't reach.", how_it_helps: "The playlist becomes a conversation that neither of you would have otherwise had." },
  { id: 127, emoji: "📖", title: "Read Aloud to Someone", subtitle: "A few pages. A poem. A chapter.", duration: "15 min", category: "Connection", color: "#C1603A", front_detail: "No one reads to adults anymore. This is a gift.", science_title: "Vocal Prosody & Co-Regulation", science: "Reading aloud activates prosodic processing in the listener — the emotional content conveyed by voice tone, rhythm, and pacing. Co-regulation through shared auditory experience synchronizes respiratory rhythms between reader and listener, producing a form of physiological bonding not possible through silent reading.", how_it_helps: "Someone using their voice to give you a story is an ancient form of care. It still works the same way." },
  { id: 128, emoji: "🌿", title: "Plant Something Together", subtitle: "Any plant, any pot, any two people.", duration: "20 min", category: "Connection", color: "#7A9E7E", front_detail: "The shared thing you both watch grow afterward.", science_title: "Shared Endeavor & Relationship Maintenance", science: "Joint activities that produce a lasting artifact (a plant, a meal, a project) create shared ownership — a cognitive and emotional state that strengthens relational bonds. Research on relationship maintenance shows shared creative projects provide more lasting relationship satisfaction than shared consumption experiences.", how_it_helps: "You made something alive together. You both get to watch it grow. That gives you something to talk about for months." },
  { id: 129, emoji: "🧩", title: "Send a Voice Message", subtitle: "Instead of text, record your voice. Just one message.", duration: "5 min", category: "Connection", color: "#A0785A", front_detail: "The warmth in a voice that a text can never carry.", science_title: "Paralinguistic Cues & Emotional Transmission", science: "Research by Amit Kumar at the University of Texas shows that voice messages are significantly more effective at conveying warmth, competence, and genuine care than identical text messages. People consistently underestimate how much emotional information their voice carries and overestimate how much text compensates.", how_it_helps: "They hear your actual voice. Not the words — the voice. That's different." },
  { id: 130, emoji: "🕯️", title: "Eat a Meal Fully Mindfully", subtitle: "One meal. No phone, no reading, no screen. Just the food.", duration: "20 min", category: "Presence", color: "#D4945A", front_detail: "Notice taste, temperature, texture, smell. Chew more than usual.", science_title: "Mindful Eating & Digestive Regulation", science: "Mindful eating activates the cephalic phase of digestion — the neurological priming of stomach acid, enzyme production, and insulin sensitivity that precedes eating. Research shows mindful eating reduces caloric intake by 20-30% naturally, improves satiety signals, and significantly reduces binge eating episodes. The meal is the practice.", how_it_helps: "You've been eating while doing something else your whole life. This is the first time some of these foods will actually taste like what they are." },
  { id: 131, emoji: "🌅", title: "Watch the Sunrise", subtitle: "Set an alarm. Go outside. Witness the transition.", duration: "15 min", category: "Presence", color: "#D4945A", front_detail: "Even from a window. The full arc of light change.", science_title: "Morning Light Exposure & Circadian Anchoring", science: "Morning light exposure within the first hour of waking anchors the circadian clock through retinal ipRGC cells sensitive to short-wavelength (blue) light. A single morning light exposure session regulates cortisol awakening response, melatonin timing, and sleep quality for subsequent days — improving mood and alertness across 24 hours.", how_it_helps: "Your brain needs this light. It uses it to set every biological clock you have. You're also watching something beautiful." },
  { id: 132, emoji: "🌇", title: "Watch the Full Sunset", subtitle: "Find a good view. Watch from first color to last light.", duration: "20 min", category: "Presence", color: "#C8825A", front_detail: "Stay the whole time. Don't leave early.", science_title: "Awe Response & Time Perception Expansion", science: "Keltner's awe research identifies sunsets as reliable triggers of the awe response — which measurably expands perceived time, reduces self-referential thinking, and increases feelings of connection to something larger than oneself. Watching the full transition, rather than glancing, is what activates this response.", how_it_helps: "You've seen hundreds of sunsets and missed most of them. Staying for the whole thing is a different experience. Try it." },
  { id: 133, emoji: "🌬️", title: "Sense Wind Direction", subtitle: "Go outside. Feel which way the wind comes from. Sit with it.", duration: "10 min", category: "Presence", color: "#7A9E7E", front_detail: "Wet a finger, or just stand and pay attention.", science_title: "Environmental Attunement & Sensory Awakening", science: "Attending to subtle environmental stimuli like wind direction activates the same perceptual attention systems as formal mindfulness practice. Research on environmental attunement shows that individuals who regularly attend to subtle weather and natural cues demonstrate higher scores on mindfulness scales and lower anxiety measures.", how_it_helps: "You become oriented to something real and external rather than internal and circular. The wind is always doing something." },
  { id: 134, emoji: "🌫️", title: "Smell Rain Before It Arrives", subtitle: "Petrichor. The scent of the earth preparing.", duration: "5 min", category: "Presence", color: "#6B8EA6", front_detail: "Go outside when clouds gather. Breathe slowly.", science_title: "Olfactory-Limbic Pathway & Anticipatory Pleasure", science: "Petrichor (geosmin + plant oils released before rain) is detectable by humans at concentrations of parts per trillion — suggesting extreme evolutionary significance. The smell directly activates the limbic system via the olfactory bulb, producing anticipatory pleasure responses. It is one of the most universally loved scents across all cultures.", how_it_helps: "This smell is ancient. The pleasure you feel when you smell it has been selected for over millions of years. Just breathe it in." },
  { id: 135, emoji: "🌿", title: "Touch Moss", subtitle: "Find some moss. Sit near it. Touch it slowly.", duration: "5 min", category: "Grounding", color: "#6B9E6B", front_detail: "The softest thing in the forest. It lives on almost nothing.", science_title: "Texture, Touch & Parasympathetic Grounding", science: "Handling soft, yielding natural materials activates skin mechanoreceptors that trigger parasympathetic responses through the same pathways as therapeutic touch. Moss has a unique combination of moisture, softness, and thermal neutrality that provides a complex sensory experience associated with calm across multiple studies of nature-based therapy.", how_it_helps: "It is impossibly soft. It grew there without being asked. Touching it is enough." },
  { id: 136, emoji: "🦎", title: "Watch a Small Wild Creature", subtitle: "Find any small animal. Follow it with your eyes for five minutes.", duration: "5–10 min", category: "Presence", color: "#7A9E7E", front_detail: "A beetle. A snail. A sparrow. An earthworm.", science_title: "Voluntary Attention & Ego Dissolution", science: "Sustained attention to non-human life for five or more minutes activates attention circuits in ways that reduce default mode network activity — the neural substrate of self-referential anxiety. The creature is entirely absorbed in its own existence. Watching it without agenda creates a temporary experience of ego dissolution.", how_it_helps: "It does not know you are watching. It does not care about anything you care about. That is a profound perspective." },
  { id: 137, emoji: "🌙", title: "Night Walk Without a Destination", subtitle: "After dark. Slowly. No earphones.", duration: "20 min", category: "Presence", color: "#2C4A30", front_detail: "Familiar streets become different places in the dark.", science_title: "Low-Light Perception & Melatonin Production", science: "Walking outdoors after dark — in the absence of artificial light — allows natural melatonin production to begin through the absence of short-wavelength stimulation. The changed acoustic and visual landscape also activates novelty-processing circuits in familiar environments, producing a mild but genuine sense of wonder.", how_it_helps: "Darkness makes the familiar strange. The streets you walk every day become somewhere else entirely at night." },
  { id: 138, emoji: "🔭", title: "Find One Constellation", subtitle: "Go outside, away from screens. Find one constellation by name.", duration: "15 min", category: "Curiosity", color: "#2C4A30", front_detail: "Orion. Cassiopeia. The Plough. Pick one and find it.", science_title: "Cosmic Scale & Self-Transcendence", science: "Identifying constellations requires simultaneously holding awareness of human-scale pattern-recognition and cosmic-scale distance. Research shows that contemplating astronomical scale reliably triggers self-transcendence — a state associated with reduced anxiety, expanded time perception, and increased prosocial motivation.", how_it_helps: "The light entering your eye left those stars before you were born. You are seeing the past right now." },
  { id: 139, emoji: "🌡️", title: "Weather Observation Journal", subtitle: "Note temperature, sky, wind, humidity. Daily for a week.", duration: "5 min", category: "Grounding", color: "#6B8EA6", front_detail: "A small notebook. The same spot. Every day.", science_title: "Environmental Attunement & Circadian Health", science: "Regular attention to environmental conditions maintains circadian entrainment and improves wellbeing in multiple studies. Research on phenology (the study of cyclical natural phenomena) shows observers develop measurably reduced nature-deficit scores and higher baseline positive affect compared to controls.", how_it_helps: "You become a person who notices. That noticing doesn't stay in the weather — it spreads into everything." },
  { id: 140, emoji: "🍃", title: "Observe Microhabitats", subtitle: "Pick one square foot of ground. Observe everything in it.", duration: "15 min", category: "Presence", color: "#6B9E6B", front_detail: "Under a log. Between paving stones. At the base of a tree.", science_title: "Ecological Attention & Complexity Perception", science: "Microhabitat observation activates fascination attention — the effortless, restorative form of attention described in Kaplan's Attention Restoration Theory. Research shows sustained attention to biological complexity in small spaces produces ART's four restorative components: being away, extent, fascination, and compatibility.", how_it_helps: "An entire world fits in one square foot. You've been walking over worlds every day." },
  { id: 141, emoji: "🎨", title: "Loving-Kindness Meditation", subtitle: "Send warmth: to yourself, a friend, a stranger, an enemy.", duration: "10 min", category: "Calm", color: "#9B7BB8", front_detail: "Start with yourself. That part is the hardest.", science_title: "Metta Practice & Positive Emotion Broadening", science: "Barbara Fredrickson's research on loving-kindness meditation at UNC Chapel Hill showed that even brief metta practice significantly increases positive emotions, social connection, and a sense of purpose. Daily practice over 7 weeks produced lasting increases in life satisfaction, personal resources, and reduced depression symptoms.", how_it_helps: "Sending warmth to yourself first is not narcissism — it is the prerequisite for genuinely sending it to others." },
  { id: 142, emoji: "🧘", title: "Open Monitoring Meditation", subtitle: "Sit quietly. Notice whatever arises without preference.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "No object of focus. Just awareness of awareness itself.", science_title: "Non-Reactive Awareness & Default Mode Quieting", science: "Open monitoring meditation — a form with no specific focus object — has been shown to increase EEG alpha and theta wave coherence and reduce default mode network reactivity. Research at MIT shows it produces different neurological changes than focused-attention meditation, specifically targeting rumination and mind-wandering.", how_it_helps: "You are practicing watching your mind without being pulled into its contents. That skill transfers to every waking moment." },
  { id: 143, emoji: "🌊", title: "Noting Practice", subtitle: "Sit still. Silently label every experience: 'thinking', 'feeling', 'hearing'.", duration: "10 min", category: "Calm", color: "#7A9E7E", front_detail: "One soft word per observation. Let each one go.", science_title: "Affect Labeling & Amygdala Regulation", science: "Naming experiences activates the prefrontal cortex and simultaneously reduces amygdala reactivity — an effect demonstrated in fMRI studies by Matthew Lieberman at UCLA. The simple act of labeling an emotion or sensation 'cools' the emotional response and increases reflective rather than reactive processing.", how_it_helps: "Naming what is happening is the difference between being inside an experience and observing it. The label creates the distance." },
  { id: 144, emoji: "🌿", title: "5-4-3-2-1 Grounding", subtitle: "Name 5 things you see, 4 feel, 3 hear, 2 smell, 1 taste.", duration: "5 min", category: "Calm", color: "#7A9E7E", front_detail: "Used in acute anxiety treatment. Works immediately.", science_title: "Sensory Grounding & Panic Interruption", science: "The 5-4-3-2-1 technique recruits multiple sensory cortices simultaneously, creating a sensory load that interrupts the default mode network's anxiety loop. Research in trauma therapy shows this technique measurably reduces physiological arousal within 2-3 minutes — it is now standard in PTSD treatment protocols.", how_it_helps: "This is the technique clinicians teach in crisis. You don't need to be in crisis to use it. It works whenever the mind spirals." },
  { id: 145, emoji: "🏔️", title: "Mountain Visualization", subtitle: "Imagine yourself as a mountain. Seasons change. You remain.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "Storms come. Snow falls. The mountain doesn't move.", science_title: "Embodied Metaphor & Equanimity Training", science: "Jon Kabat-Zinn's mountain meditation uses embodied metaphor — the psychological mechanism of conceptual mapping between the self and a stable physical entity — to build equanimity. Research shows visualization-based metaphor work produces measurable increases in distress tolerance and reduces emotional reactivity in acute stressors.", how_it_helps: "Things will keep happening around you. Practicing being unmoved by them is a skill, not a personality trait." },
  { id: 146, emoji: "🌊", title: "Lake Meditation", subtitle: "Imagine a still lake. You are the depth, not the surface.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "The surface has waves. The depths are always still.", science_title: "Depth Metaphor & Emotional Regulation", science: "The lake metaphor exploits the cognitive linguistic principle of conceptual metaphor — the mind automatically maps abstract concepts onto physical ones. Research on metaphor-based therapy shows lake/depth visualizations specifically activate neural circuits associated with cognitive reappraisal of emotional experience.", how_it_helps: "The storms you feel are real. So is the stillness underneath them. This practice teaches you to find the water, not just watch the waves." },
  { id: 147, emoji: "🍃", title: "Leaves on a Stream", subtitle: "Visualize thoughts as leaves floating past on water.", duration: "10 min", category: "Calm", color: "#7A9E7E", front_detail: "You are the bank. Every thought is just passing through.", science_title: "Cognitive Defusion & ACT Practice", science: "This ACT (Acceptance and Commitment Therapy) technique produces what Hayes terms 'cognitive defusion' — the separating of the self from the content of thoughts. Meta-analyses of ACT show defusion techniques significantly reduce anxiety and depression by changing the function of thoughts rather than their content.", how_it_helps: "A thought on a leaf is just a thought. You don't have to follow it or fight it. Just let it float." },
  { id: 148, emoji: "💙", title: "Coherent Breathing", subtitle: "Breathe in 5 seconds. Out 5 seconds. Ten minutes.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "5 in, 5 out. Exactly. A metronome helps.", science_title: "Heart Rate Variability & Resonance Frequency Breathing", science: "Breathing at exactly 0.1 Hz (the resonance frequency of the cardiovascular system) maximizes heart rate variability, a key marker of health and stress resilience. Research by Stephen Elliott shows coherent breathing at 5-5 creates the largest possible amplitude in HRV, training the nervous system's flexibility.", how_it_helps: "HRV is the single best measurable predictor of stress resilience. This is the direct practice for building it." },
  { id: 149, emoji: "👁️", title: "Soft Gaze Practice", subtitle: "Defocus your eyes. Let peripheral vision expand. Hold.", duration: "5 min", category: "Calm", color: "#7B6E8D", front_detail: "Look at nothing in particular. Let the eyes relax.", science_title: "Peripheral Vision & Sympathetic Downregulation", science: "Andrew Huberman's research identifies panoramic vision — the simultaneous use of peripheral and central fields — as a neurological brake on the fight-flight response. Narrowing gaze activates sympathetic arousal; widening to panoramic vision suppresses it. This is why staring at a single point increases anxiety.", how_it_helps: "Your focused stare activates your stress response all day. Letting your gaze soften literally changes your nervous system state." },
  { id: 150, emoji: "🌟", title: "Awareness of Awareness", subtitle: "Instead of noticing objects, notice the noticing itself.", duration: "10 min", category: "Calm", color: "#9B7BB8", front_detail: "Who is it that is aware? Rest in that question.", science_title: "Meta-Awareness & Pure Consciousness Research", science: "Meditation research identifies 'awareness of awareness' — a non-dual practice — as producing the highest levels of frontal theta wave coherence and the most significant reductions in default mode network activity. Studies by Judson Brewer show this state produces the deepest disruption of the self-referential thought loop.", how_it_helps: "The contents of your mind are not you. This practice makes that clear in a way that description cannot." },
  { id: 151, emoji: "🎵", title: "Listen to Music in Complete Darkness", subtitle: "Room fully dark. Headphones. One full album.", duration: "45 min", category: "Presence", color: "#2C4A30", front_detail: "No visual input. Just sound, full attention.", science_title: "Multisensory Processing & Auditory Detail Resolution", science: "Removing visual input dramatically increases auditory processing depth. Research shows listeners in darkness identify significantly more musical details, experience stronger emotional responses, and report greater immersion than in lit environments. The brain allocates freed visual cortex resources to auditory processing.", how_it_helps: "You've heard these songs a hundred times. In the dark, you'll hear things in them you've never noticed before." },
  { id: 152, emoji: "🫁", title: "Eat One Food Mindfully", subtitle: "One piece of fruit, cheese, or chocolate. Take five full minutes.", duration: "5 min", category: "Presence", color: "#E8845A", front_detail: "The MBSR raisin exercise. With whatever you have.", science_title: "Mindful Eating & Hedonic Adaptation Reversal", science: "Jon Kabat-Zinn's raisin exercise is one of the most replicated mindfulness interventions in clinical research. Attending fully to a single food item reverses hedonic adaptation — the process by which familiar pleasures fade through habituation — producing genuine novelty in what seems ordinary.", how_it_helps: "You will taste a raisin, or a grape, or a piece of cheese as if for the first time. That's not a metaphor." },
  { id: 153, emoji: "🌿", title: "Explore One Smell in Depth", subtitle: "Coffee, lemon peel, earth, rosemary. Smell slowly, five minutes.", duration: "5 min", category: "Presence", color: "#7A9E7E", front_detail: "What changes as you keep smelling? What does it remind you of?", science_title: "Olfactory Processing & Autobiographical Memory", science: "The olfactory bulb has direct connections to both the amygdala and hippocampus — bypassing the thalamic relay used by all other senses. This means smell uniquely activates both emotional and autobiographical memory simultaneously. Sustained olfactory attention produces involuntary memories (Proust phenomenon) associated with elevated positive affect.", how_it_helps: "A single smell can return you to somewhere you haven't been in twenty years. That is its own form of travel." },
  { id: 154, emoji: "💧", title: "Feel Water Mindfully", subtitle: "Run your hands under warm water. Feel every sensation.", duration: "5 min", category: "Presence", color: "#6B8EA6", front_detail: "Temperature. Pressure. Sound. Movement. All of it.", science_title: "Sensory Attention & Cortical Activation", science: "Water's unique thermal and tactile properties activate the largest area of the somatosensory cortex per stimulus of any common household experience. Research on sensory awareness interventions shows that sustained attention to water sensation produces parasympathetic activation within minutes — the same effect as handwashing rituals across cultures.", how_it_helps: "You've washed your hands thousands of times. This is the first time you'll actually be there for it." },
  { id: 155, emoji: "🎸", title: "Listen to Silence for Three Minutes", subtitle: "Find the quietest place. Listen to what silence actually sounds like.", duration: "3 min", category: "Calm", color: "#7B6E8D", front_detail: "It isn't actually silent. What do you hear?", science_title: "Acoustic Rest & Neural Regeneration", science: "A 2013 study found that two hours of silence per day generated new hippocampal neurons in mice — a proxy for cognitive regeneration. The absence of auditory input reduces cognitive load on the auditory cortex, freeing resources for consolidation and integration. Even 3-minute silence sessions measurably reduce blood pressure.", how_it_helps: "In an age of constant auditory input, silence is a genuinely scarce resource. This is a direct, physiological rest for your brain." },
  { id: 156, emoji: "🌈", title: "Observe One Color in Full Depth", subtitle: "Pick one color. Find every shade of it in your environment.", duration: "10 min", category: "Presence", color: "#E8845A", front_detail: "Blue. Every blue in this room, street, or garden.", science_title: "Color Attention & Visual Cortex Engagement", science: "Selective color attention — systematically identifying all instances of a target hue — trains voluntary attention in the same way meditation does, while using the visual system's specialization for chromatic discrimination. Research on color awareness exercises shows measurable improvements in attentional focus and novelty detection after practice.", how_it_helps: "You've been in this room a thousand times. There are blues in it you have never consciously seen." },
  { id: 157, emoji: "🏋️", title: "Describe a Smell in Five Words", subtitle: "Pick anything with a scent. Find five precise words.", duration: "5 min", category: "Reflection", color: "#A0785A", front_detail: "Not 'nice' or 'good'. Five specific words.", science_title: "Descriptive Language & Interoceptive Precision", science: "Research on interoceptive awareness shows that people with richer vocabulary for internal experience have significantly better emotional regulation — they can differentiate fine-grained emotional states rather than experiencing global undifferentiated affect. Practicing precise description of sensory experience builds this capacity.", how_it_helps: "The more specifically you can name an experience, the more precisely you can relate to it. This is practice for that." },
  { id: 158, emoji: "🎹", title: "Listen to the Same Song Two Ways", subtitle: "Once through speakers. Once through headphones. Compare.", duration: "10 min", category: "Curiosity", color: "#7B6E8D", front_detail: "What changes? What sounds different? What did you miss?", science_title: "Auditory Perception & Comparative Attention", science: "Spatial audio processing differs fundamentally between bone conduction and air conduction pathways. Headphones shift sound from external to internal space; speakers create spatial localization. Comparing the same music through both modes exercises comparative auditory attention — the cognitive act of holding two percepts simultaneously for comparison.", how_it_helps: "Music you know becomes new when the delivery system changes. Your ears will find things they missed." },
  { id: 159, emoji: "✋", title: "Explore Texture for Five Minutes", subtitle: "Find ten different textures near you. Feel each one slowly.", duration: "5 min", category: "Presence", color: "#A0785A", front_detail: "Fabric, wood, glass, skin, paper, stone. Don't categorize. Just feel.", science_title: "Somatosensory Cortex Engagement & Grounding", science: "Systematic tactile exploration activates the full somatosensory cortex through mechanoreceptor stimulation — specifically targeting Meissner's corpuscles (light touch), Merkel's discs (pressure), and Ruffini endings (sustained stretch). This multi-receptor activation produces grounding effects equivalent to formal body scan meditation.", how_it_helps: "You have been touching things all day without noticing them. This is five minutes of actually being in your hands." },
  { id: 160, emoji: "🌡️", title: "Temperature Contrast on Hands", subtitle: "Warm water, then cold. Feel the difference. Repeat slowly.", duration: "5 min", category: "Presence", color: "#6B8EA6", front_detail: "This is a sensory practice. Not a cold training. Just noticing.", science_title: "Thermal Sensitivity & Sensory Awareness Training", science: "Alternating thermal stimulation exercises the thermal receptor system's dynamic range — the ability to detect relative change rather than absolute temperature. Research on sensory training shows this improves interoceptive accuracy (the ability to perceive bodily states) which is a strong predictor of emotional regulation.", how_it_helps: "The contrast is everything. Not just warm. Not just cold. The difference between them." },
  { id: 161, emoji: "😴", title: "20-Minute Power Nap", subtitle: "Set a timer for 20 minutes. Lie down. Don't worry if you sleep.", duration: "20 min", category: "Calm", color: "#7B6E8D", front_detail: "Sleep is optional. Rest is the point.", science_title: "Stage 2 Sleep & Memory Consolidation", science: "NASA research on pilot performance found that a 26-minute nap improved performance by 34% and alertness by 100%. Naps of 20 minutes stay in Stage 2 sleep — avoiding sleep inertia (grogginess) while producing significant improvement in declarative memory, motor learning, and mood.", how_it_helps: "You don't need to sleep. Closing your eyes and lying still for 20 minutes is itself restorative. The rest is a bonus." },
  { id: 162, emoji: "🌙", title: "Non-Sleep Deep Rest", subtitle: "20 minutes lying still, eyes closed, no agenda.", duration: "20 min", category: "Calm", color: "#2C4A30", front_detail: "No guided audio. No meditation. Just deliberate stillness.", science_title: "Parasympathetic Rest & Dopamine Replenishment", science: "Andrew Huberman's research on NSDR (Non-Sleep Deep Rest) documents significant dopamine restoration after 20-minute sessions of deliberate rest — returning dopamine to baseline after depletion more effectively than equivalent passive rest. The deliberate stillness produces a distinct restorative state from sleeping or simply sitting.", how_it_helps: "The most underrated practice on this list. Twenty minutes of real stillness and you will feel measurably different afterward." },
  { id: 163, emoji: "💤", title: "Create an Evening Wind-Down Ritual", subtitle: "Design one thing to do every night before bed.", duration: "15 min", category: "Calm", color: "#9B7BB8", front_detail: "The same thing, every night. Your nervous system learns the signal.", science_title: "Conditioned Relaxation & Sleep Onset Facilitation", science: "Consistent presleep rituals create conditioned relaxation responses — through classical conditioning, the ritual itself begins triggering the physiological changes associated with sleep onset. Research shows sleep latency (time to fall asleep) decreases significantly with consistent bedtime rituals across all age groups.", how_it_helps: "You are training your nervous system to recognize the signal. The ritual is the cue. Sleep becomes easier every time." },
  { id: 164, emoji: "📓", title: "Dream Journal", subtitle: "Keep paper by the bed. Write what you remember immediately on waking.", duration: "10 min", category: "Reflection", color: "#9B7BB8", front_detail: "Even fragments. Even feelings. Write before you move.", science_title: "REM Processing & Emotional Memory Consolidation", science: "Dreams represent the brain's primary emotional memory processing system. Research by Matthew Walker at UC Berkeley shows REM sleep specifically processes emotional memories and strips away their emotional charge. Dream journaling increases recall of this processing, building the metacognitive capacity to observe one's own emotional life.", how_it_helps: "Your sleeping mind has been working on your problems all night. This catches what it was doing." },
  { id: 165, emoji: "🛁", title: "Epsom Salt Bath", subtitle: "Warm water, two cups of salts, 20 minutes minimum.", duration: "25 min", category: "Calm", color: "#6B8EA6", front_detail: "Dim the lights. No phone. Just hot water and salt.", science_title: "Magnesium Transdermal Absorption & Muscle Relaxation", science: "Magnesium, absorbed transdermally during Epsom salt baths, is a cofactor for over 300 enzymatic reactions including those governing muscle relaxation and GABA receptor function. Research shows magnesium deficiency is extremely common and directly associated with anxiety, insomnia, and muscle tension. The bath corrects all three.", how_it_helps: "The warmth relaxes you. The magnesium does the rest — at the cellular level. This is a genuinely physiological intervention." },
  { id: 166, emoji: "🧠", title: "Write Tomorrow's Worry List", subtitle: "Empty every worry from your head onto paper. Then close it.", duration: "10 min", category: "Reflection", color: "#9B7BB8", front_detail: "Not to solve them. Just to move them from mind to page.", science_title: "Cognitive Offloading & Rumination Interruption", science: "Research by Borkovec on 'worry postponement' shows that designating a specific time and place for worry dramatically reduces cognitive intrusion throughout the rest of the day and evening. Writing down worries provides external storage — the brain stops rehearsing the list because it trusts the page to hold it.", how_it_helps: "Your brain rehearses worries at night because it's afraid of forgetting them. Writing them down is permission to let them go." },
  { id: 167, emoji: "📚", title: "Read a Paper Book Before Sleep", subtitle: "Any paper book. Twenty pages. No e-reader.", duration: "20 min", category: "Calm", color: "#A0785A", front_detail: "The smell, the pages, the absence of notifications.", science_title: "Blue Light Reduction & Melatonin Preservation", science: "Electronic screens emit short-wavelength blue light that suppresses melatonin production for up to 3 hours. Physical books produce no light emission. Research comparing e-readers to physical books found measurably better sleep quality, faster onset, and greater alertness the following morning with physical book reading.", how_it_helps: "The story will carry you somewhere. The absence of light will let your melatonin rise. Both matter." },
  { id: 168, emoji: "❄️", title: "Cool the Room for Sleep", subtitle: "Set the bedroom temperature to 65-68°F/18-20°C.", duration: "5 min", category: "Calm", color: "#6B8EA6", front_detail: "Core body temperature must drop to initiate deep sleep.", science_title: "Thermoregulation & Sleep Architecture", science: "Core body temperature naturally drops during sleep onset. Matthew Walker's sleep research at UC Berkeley shows that ambient temperatures above 70°F disrupt deep NREM sleep by preventing the required temperature drop. Optimal sleep temperature is consistently found to be 65-68°F across multiple sleep architecture studies.", how_it_helps: "The single most impactful environmental change you can make for sleep quality. It costs nothing. Open the window." },
  { id: 169, emoji: "🔢", title: "Count Backward from 300 by 3s", subtitle: "300, 297, 294... until you lose track or fall asleep.", duration: "10 min", category: "Calm", color: "#6B8EA6", front_detail: "In bed, in the dark. The math is the point.", science_title: "Cognitive Load & Anxiety Interruption for Sleep", science: "Mild cognitive tasks that require just enough attention to prevent rumination without generating arousal have been studied as sleep-onset aids. Counting backward by 3s occupies working memory at a level that disrupts the anxiety spiral while remaining dull enough not to activate the alerting system.", how_it_helps: "You will lose track. That's the goal. The math puts your mind somewhere boring enough to let sleep in." },
  { id: 170, emoji: "😌", title: "Body Scan for Sleep", subtitle: "Start at toes. Soften each area. Work to the crown.", duration: "15 min", category: "Calm", color: "#7A9E7E", front_detail: "Not checking in — releasing. Invite each part to let go.", science_title: "Progressive Relaxation & Sleep Inertia Reduction", science: "Body scan meditation adapted for sleep has been studied extensively in MBSR sleep protocols. Research shows it reduces sleep latency by an average of 14 minutes and increases time in slow-wave sleep. The directing of attention to non-cognitive body parts reduces prefrontal cortex activity — the prime obstacle to sleep onset.", how_it_helps: "Your mind keeps you awake. Your body can bring you back. Start at the toes. Let them lead." },
  { id: 171, emoji: "🎵", title: "Cognitive Shuffle", subtitle: "Imagine random, unconnected images. A cat. A mountain. A spoon.", duration: "10 min", category: "Calm", color: "#7B6E8D", front_detail: "Deliberately nonsensical. Random images, no story.", science_title: "Hypnagogic State Induction & Default Mode Disruption", science: "Luc Beaudoin's cognitive shuffle technique intentionally disrupts the narrative-seeking default mode network to trigger the hypnagogic (presleep) state. Random imagery mimics the brain's own sleep-onset signal and has been shown to reduce sleep latency significantly compared to thought suppression or relaxation techniques.", how_it_helps: "Your brain tries to make stories out of everything. This deliberately gives it things it can't connect. Sleep fills the gap." },
  { id: 172, emoji: "🌟", title: "Write What You're Outgrowing", subtitle: "One honest paragraph about what you are no longer becoming.", duration: "15 min", category: "Reflection", color: "#9B7BB8", front_detail: "Not a criticism of the past self. Just an honest observation.", science_title: "Narrative Identity & Self-Concept Development", science: "Research on narrative identity by Dan McAdams at Northwestern shows that articulating one's own development — including what one is moving away from — strengthens the coherence of the life story. People with more developed narrative identities demonstrate greater psychological flexibility, resilience, and purpose.", how_it_helps: "You are not the same person you were. Writing about what you are leaving behind makes room for what you are becoming." },
  { id: 173, emoji: "📝", title: "List What Makes You Distinctly You", subtitle: "Ten things. Small and specific. Not achievements.", duration: "15 min", category: "Reflection", color: "#C1603A", front_detail: "Not what you do. What you are like. The small things.", science_title: "Self-Concept Clarity & Wellbeing", science: "Research by Jennifer Campbell at UBC shows that self-concept clarity — a stable, internally consistent sense of who one is — predicts wellbeing, resilience, and relationship quality more reliably than self-esteem. Writing specific, idiosyncratic self-descriptions strengthens this clarity.", how_it_helps: "The ten things you write will probably surprise you. They're the truest things about you, and you barely think about them." },
  { id: 174, emoji: "✉️", title: "Write a Letter to Your Future Self", subtitle: "Ten years from now. What do you hope for them?", duration: "20 min", category: "Reflection", color: "#9B7BB8", front_detail: "Not advice. Hopes. What do you want for that person?", science_title: "Future Self Continuity & Prosocial Decision Making", science: "Research by Hal Hershfield at UCLA shows that people with stronger identification with their future selves make decisions that are more beneficial to long-term wellbeing. Exercises that increase future self continuity — like letter-writing — measurably shift decision-making toward delayed gratification and prosocial behavior.", how_it_helps: "When you care about your future self the way you care about a friend, you treat them better. This is the start of that." },
  { id: 175, emoji: "🗺️", title: "Map Your Emotional Geography", subtitle: "Draw a map of places that feel like home. Note why.", duration: "20 min", category: "Reflection", color: "#7B6E8D", front_detail: "Not just literal places. Situations, times of day, types of weather.", science_title: "Place Attachment & Identity Grounding", science: "Place attachment research demonstrates that the emotional bonds people form with environments are primary contributors to psychological security and identity. Mapping and articulating these bonds activates memory consolidation networks and produces clarity about what environments support vs. deplete the individual.", how_it_helps: "You know which rooms, cities, and moments feel like you. Naming them tells you something important about who you actually are." },
  { id: 176, emoji: "🎭", title: "Describe Yourself from Someone Who Loves You", subtitle: "Write how someone who loves you would describe you. Honestly.", duration: "15 min", category: "Reflection", color: "#C1603A", front_detail: "Not how they would flatter you. How they would describe you truly.", science_title: "Compassionate Self-Perception & Self-Criticism Reduction", science: "Research on self-compassion by Kristin Neff shows that viewing oneself through the lens of a caring observer significantly reduces self-criticism and increases psychological wellbeing. The perspective-shift produces different neural activation than direct self-evaluation — reducing the prefrontal self-judgment loop.", how_it_helps: "Someone who loves you sees you more accurately than your inner critic does. Let them describe you for once." },
  { id: 177, emoji: "💡", title: "Write What You Believe About One Big Question", subtitle: "God. Meaning. Death. Time. Choose one. Write honestly.", duration: "20 min", category: "Reflection", color: "#9B7BB8", front_detail: "Not what you're supposed to believe. What you actually think.", science_title: "Philosophical Reflection & Existential Grounding", science: "Research on existential concerns shows that writing directly about one's own beliefs regarding fundamental questions reduces existential anxiety and increases sense of purpose — both through the process of articulation and through self-concept clarity. Terror Management Theory research confirms that facing mortality consciously reduces defensive avoidance.", how_it_helps: "You have beliefs about these things whether or not you've articulated them. Writing them makes them available to you." },
  { id: 178, emoji: "🏆", title: "List Ten Moments of Pride", subtitle: "Not achievements. Moments. Where you did something that felt right.", duration: "15 min", category: "Reflection", color: "#D4945A", front_detail: "Include small ones. Especially the small ones.", science_title: "Positive Memory Retrieval & Self-Efficacy", science: "Deliberate retrieval of past success memories activates the hippocampus and strengthens the neural pathways associated with self-efficacy — the belief in one's ability to succeed. Albert Bandura's research shows self-efficacy is one of the strongest predictors of motivation and persistence in the face of difficulty.", how_it_helps: "You have already done things that required courage and skill. This list is proof. Read it when you doubt yourself." },
  { id: 179, emoji: "✍️", title: "Personal Manifesto", subtitle: "One page. What do you stand for? What won't you compromise?", duration: "20 min", category: "Reflection", color: "#C1603A", front_detail: "Not aspirational. Actual. What you already live by.", science_title: "Values Clarification & Decision-Making Coherence", science: "Values clarification research, foundational to ACT therapy, shows that explicit identification of personal values reduces decisional conflict, improves the quality of ethical decision-making, and produces lasting wellbeing improvements. People who can clearly articulate their values report significantly greater life satisfaction.", how_it_helps: "Most people have values without knowing what they are. Writing yours down gives you something to navigate by." },
  { id: 180, emoji: "🌿", title: "Write a Letter to Your Body", subtitle: "Say what you've never said. Apologize. Thank it. Ask for something.", duration: "15 min", category: "Reflection", color: "#7A9E7E", front_detail: "Not a performance. Just honesty to the thing that carries you.", science_title: "Embodied Self-Compassion & Body Image Research", science: "Research on body image and self-compassion shows that written exercises addressing the body as a partner rather than an object significantly improve body satisfaction, reduce disordered eating behaviors, and increase physical self-care. The shift from 'my body' to 'you' produces a different psychological relationship.", how_it_helps: "Your body has never stopped working for you. It has never had a chance to hear that you noticed." },
  { id: 181, emoji: "🫧", title: "Blow Soap Bubbles", subtitle: "Slowly. Watch each one. Let them go.", duration: "5 min", category: "Presence", color: "#6B8EA6", front_detail: "Childhood. Transience. Iridescent physics.", science_title: "Awe, Transience & Prefrontal Deactivation", science: "Soap bubbles are objects of documented micro-awe — transient, iridescent, physically complex. Research on adult play shows that unstructured, purposeless activity with inherently impermanent objects produces prefrontal deactivation patterns associated with children at play. The brevity of each bubble is the stimulus, not the inconvenience.", how_it_helps: "Each one is perfect and then it's gone. That's not sad. That's just what everything is like." },
  { id: 182, emoji: "🏠", title: "Build a Blanket Fort", subtitle: "Cushions, chairs, any fabric you can find. Climb in.", duration: "20 min", category: "Presence", color: "#A0785A", front_detail: "You are allowed to do this. You are still allowed.", science_title: "Enclosed Space, Security & Nervous System Safety", science: "Enclosed, low-ceilinged, bounded spaces activate the nervous system's safety response through the same mechanisms as physical shelter. Polyvagal theory explains small enclosed spaces as activating the ventral vagal 'safe and connected' mode. Research on therapeutic environments shows enclosed architectural features consistently lower cortisol.", how_it_helps: "Inside a blanket fort, adult problems seem proportionally smaller. That is not an illusion — it is perspective." },
  { id: 183, emoji: "📐", title: "Draw with Your Non-Dominant Hand", subtitle: "Anything. For ten minutes. Only the other hand.", duration: "10 min", category: "Making", color: "#9B7BB8", front_detail: "It will look wrong. That is the entire point.", science_title: "Bilateral Brain Activation & Cognitive Flexibility", science: "Non-dominant hand drawing forces the contralateral hemisphere into active motor planning, creating cross-hemispheric neural recruitment. Research shows non-dominant hand use increases activity in underutilized hemisphere regions and is associated with improved creative fluency and access to non-habitual thought patterns.", how_it_helps: "Your dominant hand is on autopilot. The other hand is learning. You can feel the difference — that's neuroplasticity." },
  { id: 184, emoji: "🎪", title: "Learn to Juggle Three Objects", subtitle: "Any three similar objects. Start with scarves or rolled socks.", duration: "15 min", category: "Making", color: "#E8845A", front_detail: "You will drop them many times. That's practice.", science_title: "Motor Learning & Gray Matter Growth", science: "A landmark study by Draganski et al. (2004) used MRI to show that three months of juggling practice produced measurable increases in gray matter in visual and motor regions of the brain — the first direct demonstration of neuroplasticity through skill learning in healthy adults. Even beginners show changes in the first weeks.", how_it_helps: "Your brain is literally growing right now. Every dropped ball is data. Every catch is a new connection." },
  { id: 185, emoji: "🌊", title: "Make Paper Boats and Float Them", subtitle: "Fold a few. Find any water. Let them go.", duration: "15 min", category: "Presence", color: "#6B8EA6", front_detail: "A puddle, a stream, a bathtub. Just float them.", science_title: "Ephemeral Making & Anticipatory Delight", science: "Making objects whose destiny is to leave or dissolve combines creative production with the deliberate practice of non-attachment. Research on ephemeral art and object-play shows this combination produces unusually high flow-state scores because the impermanence removes outcome anxiety entirely.", how_it_helps: "You made something with your hands and then you watched it go. That's a complete little story." },
  { id: 186, emoji: "🎭", title: "Shadow Puppets", subtitle: "A lamp and a wall. Make anything your hands can make.", duration: "10 min", category: "Making", color: "#2C4A30", front_detail: "No technique required. Just your hands and the light.", science_title: "Embodied Play & Fine Motor Improvisation", science: "Shadow puppetry requires real-time proprioceptive awareness, spatial problem-solving, and imaginative projection — a combination that activates multiple right-hemisphere processes. Research on improvised creative play shows it reduces state anxiety equivalently to guided mindfulness through the complete absorption it requires.", how_it_helps: "Your hands can become anything. That's an extraordinary fact that costs nothing to rediscover." },
  { id: 187, emoji: "🔮", title: "Build a Tower from Desk Objects", subtitle: "Use only what's within reach. Make it as tall as possible.", duration: "10 min", category: "Making", color: "#C8825A", front_detail: "Books, mugs, pens, phones. How high can you go?", science_title: "Structural Problem Solving & Agency Restoration", science: "Constructive play with real objects activates the same problem-solving circuits as engineering tasks — engaging physics intuition, spatial reasoning, and iterative hypothesis testing. Research on object manipulation shows immediate improvements in creative divergent thinking and agency restoration after even brief constructive tasks.", how_it_helps: "You made something real with things that weren't a tower before. It will fall eventually. That's also fine." },
  { id: 188, emoji: "🗺️", title: "Draw a Treasure Map of Your Home", subtitle: "Mark the best spots. Name each room. Add some lore.", duration: "15 min", category: "Making", color: "#D4945A", front_detail: "Where is the warm spot? The best light? The hiding place?", science_title: "Spatial Autobiography & Place Attachment", science: "Cognitive mapping — internally representing one's environment — is a hippocampal function with strong correlations to wellbeing. Personalizing that map with emotional associations (the good chair, the window that catches morning light) reinforces place attachment, a key buffer against social disconnection and anxiety.", how_it_helps: "You've been living in this space without really seeing it. A map forces you to actually know where you are." },
  { id: 189, emoji: "🎯", title: "Skip Stones (or Practice the Motion)", subtitle: "Find water, find flat stones. Or practice the wrist action anywhere.", duration: "10 min", category: "Presence", color: "#6B9E6B", front_detail: "Three skips is already a small triumph.", science_title: "Attention, Physics Intuition & Micro-Achievement", science: "Stone skipping requires the integration of visual prediction, motor planning, and physical intuition — activating cerebellum, motor cortex, and visual prediction circuits simultaneously. The immediate, observable feedback creates a rapid success/failure learning loop that research associates with high flow state entry.", how_it_helps: "Your body has to figure out the physics. Your mind gets completely out of the way. That's exactly what you needed." },
  { id: 190, emoji: "💬", title: "Narrate Your Day as a Nature Documentary", subtitle: "Out loud, to yourself. In David Attenborough's voice.", duration: "5 min", category: "Presence", color: "#9B7BB8", front_detail: "'Here, the human approaches the refrigerator...'", science_title: "Cognitive Reappraisal & Third-Person Perspective", science: "Research on third-person self-talk (Ethan Kross, University of Michigan) shows that observing one's own experience from the outside significantly reduces emotional reactivity and improves decision-making under stress. Narrative reframing of daily events as documentary produces the same psychological distance as formal self-distancing techniques.", how_it_helps: "Nothing in your life is boring if you describe it like it is the most interesting thing on Earth. Try it for five minutes." },
  { id: 191, emoji: "🌀", title: "Count How Many Greens You Can See", subtitle: "Right now, from where you are. Name each shade.", duration: "5 min", category: "Presence", color: "#7A9E7E", front_detail: "Olive, jade, hunter, sage, chartreuse... keep going.", science_title: "Perceptual Discrimination & Habitual Attention Disruption", science: "Color discrimination tasks require the visual cortex to overcome perceptual grouping — the tendency to treat similar stimuli as identical. Research on perceptual learning shows fine-grained discrimination training increases sensory acuity and forces attentional re-engagement with familiar environments.", how_it_helps: "Your world is full of greens you have stopped seeing. This practice un-stops you." },
  { id: 192, emoji: "🏺", title: "Set a Pointless World Record", subtitle: "Most socks put on at once. Longest time staring at a wall. Yours to design.", duration: "10 min", category: "Presence", color: "#E8845A", front_detail: "A record you can actually achieve. Right now.", science_title: "Intrinsic Motivation & Playful Achievement", science: "Self-set goals with immediate, verifiable outcomes activate the dopamine reward system without the social anxiety of externally evaluated performance. Research on self-directed micro-challenge shows it produces measurable improvements in mood and motivation equivalent to receiving external positive feedback.", how_it_helps: "You can be the best in the world at something right now, today. That should be funnier than it is." },
  { id: 193, emoji: "☕", title: "Have a Solo Tea Ceremony", subtitle: "One cup. Deliberate preparation. Full attention to the ritual.", duration: "15 min", category: "Presence", color: "#A0785A", front_detail: "Not quick tea. A ceremony. Heat the cup. Choose carefully.", science_title: "Ritual, Mindfulness & Reward Amplification", science: "Research on ritualized consumption shows that even simple rituals before eating or drinking significantly increase enjoyment and perceived value of the experience. The predictable sequence of actions reduces anxiety and increases the salience of sensory information — you taste more deeply what you prepared with attention.", how_it_helps: "You are making one cup of tea the most important thing in the world for fifteen minutes. That is enough." },
  { id: 194, emoji: "🎬", title: "Make a Time Capsule", subtitle: "A small box or envelope. Objects, notes, a photo. Open in one year.", duration: "20 min", category: "Reflection", color: "#9B7BB8", front_detail: "What matters most right now? What are you hoping for?", science_title: "Future Self Continuity & Temporal Perspective", science: "Time capsule creation forces explicit awareness of temporal distance between present and future self — a cognitive operation that increases future self continuity and prosocial behavior. Anticipating opening the capsule creates an extended positive anticipatory experience that research shows sustains wellbeing beyond the creation event itself.", how_it_helps: "Future you will be so glad present you did this. That's not speculation — it's how humans are made." },
  { id: 195, emoji: "🍽️", title: "Design Your Dream Restaurant Menu", subtitle: "Every course. Every drink. Name the restaurant. Write the description.", duration: "20 min", category: "Making", color: "#D4945A", front_detail: "As specific as you can make it. Use your actual preferences.", science_title: "Gustatory Imagination & Reward Simulation", science: "Mental simulation of sensory experience activates the same cortical regions as the actual experience — including gustatory cortex and reward circuits. Research on prospective imagination shows that detailed sensory fantasy produces positive affect nearly as potent as the experience itself, through the same dopamine pathways.", how_it_helps: "You get to eat at this restaurant in your mind right now. Make it exactly what you want." },
  { id: 196, emoji: "🏠", title: "Design Your Dream Home Room by Room", subtitle: "On paper. In detail. What does every room feel like?", duration: "20 min", category: "Making", color: "#A0785A", front_detail: "Exact materials. The light in the morning. The sounds.", science_title: "Spatial Imagination & Environmental Mastery", science: "Architectural imagination activates the hippocampus through spatial simulation — the same mechanism as actual navigation. Research on mental architectural design shows it improves spatial cognition, generates positive affect through the experience of mastery, and increases awareness of what environmental features one actually values.", how_it_helps: "This is a map of what you actually want. The specificity will tell you things about yourself." },
  { id: 197, emoji: "📻", title: "Listen to Radio from Another Country", subtitle: "Find a live radio stream from somewhere far. Just listen.", duration: "15 min", category: "Curiosity", color: "#7B6E8D", front_detail: "Tokyo. Lagos. Reykjavik. Copenhagen. Just find and listen.", science_title: "Perspective Taking & Egocentric Processing Disruption", science: "Exposure to unfamiliar cultural contexts — even passively — activates perspective-taking neural networks and disrupts the egocentric processing that chronic stress entrains. Research on cultural exposure shows even brief engagement with radically different contexts measurably improves creative thinking and reduces self-focused anxiety.", how_it_helps: "Someone in another timezone is having a completely different version of today right now. That's worth a few minutes of your attention." },
  { id: 198, emoji: "🦋", title: "Eat a Meal with Wrong Utensils", subtitle: "Use a spoon for everything, or eat something with hands that you'd normally use a fork for.", duration: "20 min", category: "Presence", color: "#C8825A", front_detail: "Not to be messy. To actually pay attention to what you're eating.", science_title: "Habit Disruption & Sensory Re-engagement", science: "Eating with unfamiliar utensils disrupts automatized food behavior — the set of unconscious habits that reduce eating to a mechanical background activity. Research on habit disruption shows even minimal contextual changes (different hand, different utensil) significantly increase sensory engagement and reduce mindless eating.", how_it_helps: "You will taste your food. You haven't been doing that. This makes you do it." },
  { id: 199, emoji: "🌄", title: "Watch a Time-Lapse of Something Real", subtitle: "Clouds, flowers opening, cities at night. Watch the whole thing.", duration: "10 min", category: "Presence", color: "#D4945A", front_detail: "Time-lapses of natural phenomena. Watch without multitasking.", science_title: "Temporal Scale Expansion & Awe Induction", science: "Time-lapse videos compress timescales beyond normal human perception, producing awe-like responses — a sense of vastness requiring cognitive accommodation. Research shows this temporal expansion reliably produces the awe response: expanded perceived time, reduced self-referential thinking, and increased prosocial motivation.", how_it_helps: "Things are happening all the time at speeds you cannot normally see. Time-lapse lets you borrow a wider perspective." },
  { id: 200, emoji: "🎤", title: "Record Yourself Talking for 3 Minutes", subtitle: "Just talk. Anything. Don't listen back until the next day.", duration: "5 min", category: "Reflection", color: "#C1603A", front_detail: "What's on your mind? What's hard right now? Just say it.", science_title: "Verbal Processing & Narrative Formation", science: "Speaking about experiences activates both Broca's area (language production) and the hippocampus (narrative formation) simultaneously — a dual-process encoding that creates psychological distance and closure more effectively than writing or rumination. Research shows even 3-minute verbal processing reduces emotional charge in reported concerns.", how_it_helps: "Sometimes you just need to say it out loud. Not to anyone. Just to say it and let it leave." },
  { id: 201, emoji: "🔥", title: "Sit by a Fire or Flame", subtitle: "Fireplace, firepit, or a single candle. Sit and watch.", duration: "15 min", category: "Calm", color: "#D4945A", front_detail: "No screen. Just the actual light of actual combustion.", science_title: "Firelight, Blood Pressure & Ancestral Safety", science: "Evolutionary psychology researcher Christopher Lynn's study found that the flickering visual and auditory properties of fire uniquely reduce blood pressure in a dose-dependent way — more fire exposure, greater reduction. Firelight matches the frequency range of neural synchronization associated with restful alertness.", how_it_helps: "Your nervous system has been interpreting fire as 'safe and home' for 400,000 years. It still does." },
  { id: 202, emoji: "🎨", title: "Finger Painting", subtitle: "No brushes. Just your hands and paint or food coloring.", duration: "15 min", category: "Making", color: "#E8845A", front_detail: "Hands only. Make a mess on purpose.", science_title: "Tactile Creativity & Regressive Play", science: "Finger painting bypasses the usual technical barriers of art-making, returning the creative act to a purely tactile and spontaneous form. Research on regressive play — deliberately adopting childlike behavior — shows it reduces performance anxiety and increases intrinsic creative motivation. The mess is part of the mechanism.", how_it_helps: "You are smearing color with your hands like you did before anyone told you that wasn't enough." },
  { id: 203, emoji: "🪴", title: "Re-pot a Plant", subtitle: "One plant. Larger pot. New soil. See the roots.", duration: "20 min", category: "Grounding", color: "#6B9E6B", front_detail: "Knock it gently from its pot. Look at what grew underground.", science_title: "Soil Contact, Microbiome & Care Giving", science: "Handling soil delivers Mycobacterium vaccae through skin contact, triggering serotonin production through the immune system. The act of re-potting also activates caregiving neural circuits — the same circuits activated by caring for a dependent child — producing measurable increases in sense of purpose and nurturing satisfaction.", how_it_helps: "You'll find roots that have been trying to grow for months. Give them room. This is what tending looks like." },
  { id: 204, emoji: "🧵", title: "Learn One Embroidery Stitch", subtitle: "Running stitch, cross stitch, or French knot. One, done slowly.", duration: "20 min", category: "Making", color: "#9B7BB8", front_detail: "Thread a needle. Make one kind of mark, many times.", science_title: "Repetitive Fine Motor & Relaxation Response", science: "Repetitive needle work — consistent needle threading, pulling, and knotting — produces relaxation response markers equivalent to meditation. The bilateral hand coordination also integrates right and left hemisphere processing. Research on needlework across cultures identifies it as one of the most universally documented stress reduction practices.", how_it_helps: "The stitch is the same every time. That repetition is exactly what your nervous system needed." },
  { id: 205, emoji: "🌿", title: "Make Herbal Tea From Scratch", subtitle: "Fresh or dried herbs, hot water, patience. No tea bag.", duration: "15 min", category: "Making", color: "#7A9E7E", front_detail: "Mint, chamomile, ginger, rosemary. Whatever you have.", science_title: "Plant Chemistry, Ritual & Anxiolytic Compounds", science: "Several culinary herbs contain documented anxiolytic compounds: apigenin in chamomile acts on GABA receptors, linalool in lavender activates the olfactory-limbic pathway, rosmarinic acid in lemon balm inhibits GABA transaminase. The preparation ritual amplifies these effects through anticipatory attention.", how_it_helps: "You made medicine from plants. Slowly. On purpose. Drink it the same way." },
  { id: 206, emoji: "📷", title: "Spend an Hour Photographing One Subject", subtitle: "One object, one plant, one window. Thirty different angles.", duration: "60 min", category: "Making", color: "#A0785A", front_detail: "Light. Angle. Distance. The same thing seen entirely differently.", science_title: "Sustained Visual Attention & Perceptual Learning", science: "Photographing a single subject across multiple compositional approaches trains sustained visual attention and perceptual learning — the ability to see new information in familiar stimuli. Research shows photography-based attention training produces measurable improvements in observational acuity and present-moment awareness.", how_it_helps: "By the thirtieth photo, you will see things in this object you had never noticed. That's not a coincidence." },
  { id: 207, emoji: "📖", title: "Read Biography of Someone Radically Different", subtitle: "One chapter. Someone whose life you can barely imagine.", duration: "30 min", category: "Curiosity", color: "#9B7BB8", front_detail: "An explorer, a revolutionary, a craftsperson from another century.", science_title: "Narrative Transportation & Perspective Expansion", science: "Narrative transportation — the state of being absorbed into a story — produces measurable perspective shifts and reductions in prejudice against dissimilar groups. Research shows reading about lives very different from one's own is one of the most effective known methods for developing empathy and expanding one's concept of what is possible.", how_it_helps: "Someone lived completely differently and called it their life. That is either liberating or terrifying, and probably both." },
  { id: 208, emoji: "🎭", title: "Write Your Own Eulogy", subtitle: "From a place of fullness, not fear. What will have mattered?", duration: "20 min", category: "Reflection", color: "#2C4A30", front_detail: "Not as a morbid exercise. As a compass.", science_title: "Mortality Salience & Meaning-Making", science: "Terror Management Theory research shows that consciously confronting mortality — rather than suppressing awareness of it — produces what researchers call post-traumatic growth patterns: increased authenticity, deepened relationships, greater presence, and reduced trivial worry. Writing one's eulogy is a specific exercise in Stoic philosophy and positive psychology.", how_it_helps: "The things you want said about you at the end are the things you should be doing now. This makes them visible." },
  { id: 209, emoji: "🌺", title: "Create a Ritual for Ending Each Day", subtitle: "Design one small deliberate act that signals day's end.", duration: "10 min", category: "Calm", color: "#C8825A", front_detail: "Not a routine. A ritual. Something with meaning.", science_title: "Ritualized Transition & Cortisol Clearance", science: "Research on psychological detachment from work shows that deliberate, ritualized end-of-day transitions are the most effective method for clearing residual work stress. The key variable is intentionality — the ritual signals to the nervous system that role-switching has occurred. Without it, the physiological work state persists into evening.", how_it_helps: "Work doesn't end when you stop working unless you tell your nervous system it does. This is how you tell it." },
  { id: 210, emoji: "🎵", title: "Learn One Music Theory Concept", subtitle: "What is a fifth? A pentatonic scale? A minor chord? One thing.", duration: "20 min", category: "Curiosity", color: "#7B6E8D", front_detail: "Music is a language. This is one word.", science_title: "Structural Learning & Generative Curiosity", science: "Learning music theory activates the analytic left hemisphere to structure what the emotional right hemisphere hears — creating what researchers call 'musical literacy.' Studies show that music theory knowledge increases listening pleasure by creating informed expectation and violation of expectation, the primary drivers of musical emotion.", how_it_helps: "Every song you've ever loved will sound slightly different once you understand what's actually happening in it." },
  { id: 211, emoji: "🔍", title: "Study One Optical Illusion Deeply", subtitle: "Find one illusion. Read the explanation. Try to see both states.", duration: "15 min", category: "Curiosity", color: "#9B7BB8", front_detail: "Your perception is an act of construction. This proves it.", science_title: "Perceptual Ambiguity & Top-Down Processing", science: "Optical illusions demonstrate the brain's generative, predictive nature — visual experience is constructed by the brain, not received from reality. Research on ambiguous figure perception shows that people who can deliberately shift between interpretations demonstrate higher cognitive flexibility and openness to experience scores.", how_it_helps: "Your brain is constantly making up what it sees. Illusions are the only moment you can catch it doing that." },
  { id: 212, emoji: "🌍", title: "Learn About One Endangered Species", subtitle: "Its habitat, behavior, what threatens it, what might save it.", duration: "20 min", category: "Curiosity", color: "#6B9E6B", front_detail: "Read everything. Let yourself care about this one species.", science_title: "Biophilic Concern & Moral Circle Expansion", science: "Deep engagement with a specific non-human species activates both epistemic curiosity and moral concern simultaneously — expanding the individual's sphere of moral consideration. Research on conservation psychology shows deep species knowledge is the strongest predictor of conservation behavior, stronger than abstract environmental concern.", how_it_helps: "Specific care is more powerful than general concern. Know one species. Care about that one." },
  { id: 213, emoji: "🏺", title: "Learn the History of One Everyday Object", subtitle: "Fork. Pencil. Window. Mattress. Pick one and go deep.", duration: "20 min", category: "Curiosity", color: "#A0785A", front_detail: "'The Pencil' by Henry Petroski. Everything has this story.", science_title: "Material Culture & Novelty Detection", science: "Learning the history of ordinary objects disrupts perceptual habituation — the adaptive but deadening process by which the brain stops registering familiar stimuli. Research on material culture studies shows that understanding an object's origin and evolution produces sustained positive novelty responses in otherwise habituated individuals.", how_it_helps: "There is a fork in your kitchen. Someone invented it. Knowing that story changes the fork forever." },
  { id: 214, emoji: "🌌", title: "Learn One Astronomical Phenomenon", subtitle: "Black holes, neutron stars, the Fermi Paradox. One, in depth.", duration: "20 min", category: "Curiosity", color: "#2C4A30", front_detail: "Read until you understand one truly strange thing about the universe.", science_title: "Complexity Awe & Self-Transcendence", science: "Astronomical phenomena reliably trigger the awe response through the combination of vastness and complexity — two key awe-eliciting features identified in Keltner's research. Deep engagement with astronomical complexity produces what researchers call 'the overview effect in proxy' — perspective changes similar to those reported by astronauts.", how_it_helps: "The universe contains things stranger than anything human experience prepares you for. That strangeness is a gift." },
  { id: 215, emoji: "🔬", title: "Learn How One Technology Works", subtitle: "GPS. WiFi. Transistors. Touch screens. One, at mechanism level.", duration: "20 min", category: "Curiosity", color: "#6B8EA6", front_detail: "Not the history. The mechanism. How does it actually do that?", science_title: "Mechanistic Understanding & Wonder Restoration", science: "Understanding mechanisms — rather than accepting functional descriptions — is associated with higher scientific literacy scores and, counterintuitively, greater sense of wonder rather than disenchantment. Research shows that knowledge of how things work increases appreciation for their elegance rather than reducing it.", how_it_helps: "You carry GPS in your pocket and have no idea what it's actually doing. This fixes that." },
  { id: 216, emoji: "📜", title: "Read About One Ancient Civilization", subtitle: "Sumer. Indus Valley. Çatalhöyük. Mycenae. One hour, one culture.", duration: "30 min", category: "Curiosity", color: "#D4945A", front_detail: "How did they organize life? What did they build? What ended them?", science_title: "Historical Perspective & Temporal Expansion", science: "Engagement with deep historical time scales produces cognitive effects similar to natural awe — expanding perceived time and reducing the felt urgency of present-day concerns. Research on historical perspective-taking shows it reliably reduces anxiety about contemporary problems by contextualizing them within longer arcs.", how_it_helps: "Someone built a city five thousand years ago. It is gone. What they did still mattered. So does what you do." },
  { id: 217, emoji: "🧪", title: "Learn One Chemistry Principle", subtitle: "Entropy. Oxidation. pH. Catalysis. One, until it makes sense.", duration: "20 min", category: "Curiosity", color: "#9B7BB8", front_detail: "Look up the mechanism, not just the definition.", science_title: "Scientific Reasoning & Cognitive Pleasure", science: "Research on 'aha moments' in scientific comprehension shows that grasping a mechanism — moving from confusion to coherent understanding — produces a distinct reward signal through the dopaminergic system. The pleasure of understanding science is not metaphorical. It is a measurable neurological event.", how_it_helps: "Every time you understand why something is the way it is, the world becomes a more coherent place to live in." },
  { id: 218, emoji: "🗣️", title: "Learn One Word with No English Equivalent", subtitle: "Sonder. Mamihlapinatapai. Hygge. One word, its full meaning.", duration: "10 min", category: "Curiosity", color: "#7B6E8D", front_detail: "Find the word your language was missing.", science_title: "Linguistic Relativity & Emotional Granularity", science: "Research by Lisa Feldman Barrett shows that having words for emotional states significantly increases the precision with which the brain can regulate those states. Languages that have words for experiences English lacks give their speakers distinct emotional advantages. Learning these words expands your emotional vocabulary and regulation toolkit.", how_it_helps: "Once you have the word for a feeling, you can find it more easily. Language creates experience as much as it describes it." },
  { id: 219, emoji: "🎼", title: "Listen to One Symphony Movement", subtitle: "A full movement. No skipping. Really listen.", duration: "20 min", category: "Presence", color: "#7B6E8D", front_detail: "Beethoven's 5th, 2nd movement. Debussy's La Mer. One full arc.", science_title: "Large-Scale Musical Structure & Emotional Narrative", science: "Symphonic music unfolds emotional arcs over timescales of 10-25 minutes — requiring and training sustained attention in ways that popular music, structured around 3-minute repetitions, does not. Research shows sustained musical attention improves working memory span and produces stronger emotional catharsis than brief listening.", how_it_helps: "Give it twenty minutes. Something happens around the eighth minute that only happens if you stayed." },
  { id: 220, emoji: "🗺️", title: "Trace a River to Its Source", subtitle: "Any river on any map. Follow it all the way up.", duration: "15 min", category: "Curiosity", color: "#6B8EA6", front_detail: "The Amazon. The Thames. The Mississippi. Where does it begin?", science_title: "Geographical Curiosity & Spatial Reasoning", science: "Tracing geographical features activates the hippocampus through spatial mapping while simultaneously engaging curiosity-driven exploration. The act of following a course from end to origin activates the brain's causal explanation drive — the deeply human need to understand where things come from.", how_it_helps: "Every great river started as a trickle on a hillside somewhere. Following it back is a small form of discovery." },
  { id: 221, emoji: "🌱", title: "Grow One Herb on Your Windowsill", subtitle: "One pot, one plant, one windowsill. Water when soil is dry.", duration: "15 min", category: "Grounding", color: "#7A9E7E", front_detail: "Basil, mint, chives, or rosemary. All survive on almost nothing.", science_title: "Living System Care & Sense of Responsibility", science: "Maintaining a living plant creates a low-stakes caregiving relationship with measurable wellbeing effects. Research on horticultural therapy shows even minimal plant care reduces loneliness, provides a sense of routine, and produces biophilic contact benefits. The herb is useful; the caring for it is the more important outcome.", how_it_helps: "Something lives here that you are responsible for. It is very small. It is completely alive. That is enough." },
  { id: 222, emoji: "🌿", title: "Make a Botanical Sketch", subtitle: "Find one leaf or flower. Draw it as accurately as you can.", duration: "15 min", category: "Making", color: "#6B9E6B", front_detail: "Not artistically — observationally. Draw what is actually there.", science_title: "Observational Drawing & Right-Hemisphere Shift", science: "Drawing from direct observation induces what Betty Edwards describes as a right-hemisphere shift — a change in the dominant processing mode from verbal-symbolic to spatial-perceptual. Research confirms this shift produces measurable changes in brain lateralization during the activity, quieting the verbal critic.", how_it_helps: "You will look at this leaf for fifteen minutes. By the end, you will have seen it for the first time." },
  { id: 223, emoji: "🎭", title: "Improvise a Recipe", subtitle: "Open the fridge. No recipe. Make something from what's there.", duration: "30 min", category: "Making", color: "#C8825A", front_detail: "Constraints breed creativity. What can these ingredients become?", science_title: "Constrained Creativity & Executive Function", science: "Research on creative cognition shows that constraints — including limited ingredient sets — significantly increase creative output quality by forcing the brain to recruit non-habitual solutions. The constraint activates the prefrontal cortex's executive coordination, while the sensory feedback of cooking engages the reward system.", how_it_helps: "You made dinner out of nothing. Whatever it tastes like, it is entirely yours." },
  { id: 224, emoji: "🖊️", title: "Write Stream of Consciousness", subtitle: "Ten minutes. Don't stop writing. Don't edit. Keep the pen moving.", duration: "10 min", category: "Reflection", color: "#C1603A", front_detail: "Julia Cameron's Morning Pages, at any time of day.", science_title: "Automatic Writing & Prefrontal Inhibition Release", science: "Continuous writing tasks inhibit the prefrontal cortex's self-editing function, allowing access to thought streams that are normally suppressed before reaching awareness. Research on expressive writing shows sustained free-writing produces significant reductions in intrusive thoughts and increases self-understanding compared to structured journaling.", how_it_helps: "Your thinking brain gets exhausted trying to keep up. What's underneath it starts to show. That's the useful part." },
  { id: 225, emoji: "🌸", title: "Ikebana: Arrange Three Stems", subtitle: "Three flowers or branches. Asymmetrical. Lots of negative space.", duration: "15 min", category: "Making", color: "#E8845A", front_detail: "Japanese flower arranging. The space between is also the art.", science_title: "Aesthetic Restraint & Negative Space Attention", science: "Ikebana's philosophical emphasis on negative space and asymmetry trains attention to absence — the non-figure areas of visual composition. Research on aesthetic training shows that attention to negative space improves spatial reasoning and produces a distinct form of contemplative calm associated with Zen practice.", how_it_helps: "Three stems, placed with intention. The empty space you leave is as important as what you put in." },
  { id: 226, emoji: "🪞", title: "Draw Your Own Hand", subtitle: "Your non-drawing hand, posed. Draw what you actually see.", duration: "15 min", category: "Making", color: "#A0785A", front_detail: "Dürer did this. So did Da Vinci. Your hand is enough.", science_title: "Observational Drawing & Self-Awareness", science: "Drawing one's own hand is the most common introductory exercise in observational drawing precisely because it forces simultaneous awareness of the hand as both tool and subject — activating proprioception and visual perception simultaneously. This dual-attention produces unique cross-modal neural integration.", how_it_helps: "You will look at your own hand longer and more carefully than you ever have. It is stranger and more beautiful than you thought." },
  { id: 227, emoji: "🎸", title: "Learn One Guitar or Piano Chord", subtitle: "One chord. Practice the transition from open to fretted. Repeat.", duration: "15 min", category: "Making", color: "#7B6E8D", front_detail: "G chord. C chord. A minor. One, clean.", science_title: "Motor Learning & Myelin Formation", science: "Musical instrument learning produces myelination of neural pathways — the wrapping of nerve fibers in myelin sheaths that speeds signal transmission. Research shows even a few weeks of chord practice produces measurable changes in motor cortex organization. The learning itself is the neurological exercise.", how_it_helps: "Your fingers will find it difficult. That difficulty is the exact sensation of your brain rewiring." },
  { id: 228, emoji: "🌊", title: "Practice 4-7-8 Breathing Before a Difficult Task", subtitle: "Four rounds before you begin. Then begin.", duration: "5 min", category: "Calm", color: "#6B8EA6", front_detail: "In 4. Hold 7. Out 8. Notice what changes.", science_title: "Pre-Task Arousal Regulation & Performance", science: "Research on performance anxiety shows that pre-task breathing interventions reduce cortisol, improve working memory access, and lower performance anxiety scores. The extended exhale activates the parasympathetic response before the stressor, creating a physiological baseline that supports rather than undermines performance.", how_it_helps: "You start from calm. Whatever you do next, you do it better when you're not running from the baseline." },
  { id: 229, emoji: "🎭", title: "Practice Mirroring (Solo)", subtitle: "Move one hand slowly. Mirror it exactly with the other. Then reverse.", duration: "10 min", category: "Presence", color: "#9B7BB8", front_detail: "Perfectly synchronized, perfectly slow. No rushing.", science_title: "Bilateral Coordination & Interhemispheric Integration", science: "Precise bilateral motor mirroring requires continuous interhemispheric coordination through the corpus callosum. Research shows bilateral coordination tasks improve executive function and are used in trauma therapy (EMDR adaptation) because they require the same left-right integration that distinguishes rested from stressed states.", how_it_helps: "The precision required for perfect mirroring produces complete, forced presence. Nothing else can be in your mind." },
  { id: 230, emoji: "🌙", title: "Take a 20-Minute Walk With No Destination", subtitle: "Start walking. Turn wherever feels right. Stop when you want.", duration: "20 min", category: "Presence", color: "#2C4A30", front_detail: "Flâneur. The art of wandering without purpose.", science_title: "Undirected Walking & Default Mode Network Restoration", science: "Unstructured walking — without route, goal, or pace target — activates the default mode network in a restorative rather than ruminative mode. Research by Oppezzo and Schwartz at Stanford showed that walking specifically (not sitting) increased creative output by 81%, with the benefit persisting after the walk ended.", how_it_helps: "Walking without a destination is a practice in not needing one. Your body knows which way to go if you let it." },
  { id: 231, emoji: "🧠", title: "Study One Psychological Experiment", subtitle: "Milgram. Stanford Prison. The marshmallow test. One, in full.", duration: "20 min", category: "Curiosity", color: "#9B7BB8", front_detail: "What it actually found vs. what everyone thinks it found.", science_title: "Scientific Literacy & Self-Knowledge Through Research", science: "Understanding landmark psychology experiments provides both scientific literacy and genuine self-knowledge — a window into the automatic processes that govern behavior. Research shows that knowledge of behavioral research measurably increases self-awareness and reduces susceptibility to the very biases the research identified.", how_it_helps: "The experiments that changed how we understand human behavior often reveal something about you specifically. Worth knowing." },
  { id: 232, emoji: "🌿", title: "Learn One Principle of Ecology", subtitle: "Predator-prey dynamics. Keystone species. Succession. One.", duration: "15 min", category: "Curiosity", color: "#6B9E6B", front_detail: "How do living systems regulate themselves?", science_title: "Systems Thinking & Ecological Intelligence", science: "Ecological thinking — understanding living systems as networks of interdependence rather than collections of objects — develops systems reasoning, a cognitive mode associated with better decision-making under complexity. Research shows people with stronger ecological literacy demonstrate better risk assessment and long-term thinking.", how_it_helps: "Nothing exists alone. Understanding how living systems actually work changes how you see everything." },
  { id: 233, emoji: "📐", title: "Explore One Mathematical Paradox", subtitle: "Zeno's paradox. The Banach-Tarski paradox. Gabriel's Horn. One.", duration: "20 min", category: "Curiosity", color: "#6B8EA6", front_detail: "Read until you understand why it's impossible, and why it isn't.", science_title: "Mathematical Intuition & Epistemic Humility", science: "Mathematical paradoxes productively violate logical intuition — they demonstrate that the brain's probabilistic reasoning system, highly tuned for everyday experience, breaks down at extremes. Research shows sustained engagement with genuine paradoxes develops epistemic humility and increases tolerance for cognitive dissonance.", how_it_helps: "Your brain will resist it. That resistance is the exact sensation of encountering something genuinely true." },
  { id: 234, emoji: "🗣️", title: "Listen to a Podcast in a Field You Know Nothing About", subtitle: "Geology. Linguistics. Ornithology. Mycology. Anywhere new.", duration: "30 min", category: "Curiosity", color: "#A0785A", front_detail: "Don't worry about understanding everything. Just follow the enthusiasm.", science_title: "Expert Enthusiasm Transmission & Curiosity Priming", science: "Exposure to experts passionate about their fields produces what researchers call curiosity contagion — the emotional and cognitive transmission of domain enthusiasm. Research shows that passion is more contagious than facts, and that a single encounter with genuine expert enthusiasm measurably increases listeners' interest in the domain.", how_it_helps: "Someone devoted their life to this thing you know nothing about. Their reasons are worth thirty minutes of your time." },
  { id: 235, emoji: "✍️", title: "Write About a Regret With Self-Compassion", subtitle: "One regret. Then write what you'd say to a friend who felt it.", duration: "20 min", category: "Reflection", color: "#9B7BB8", front_detail: "The regret first, honestly. The compassion second, honestly.", science_title: "Self-Compassion Writing & Ruminative Thought Reduction", science: "Kristin Neff's self-compassion research shows that reframing regrets through a self-compassionate lens reduces rumination, shame, and depression more effectively than positive reframing or self-esteem boosting. The key element is writing as if to a friend — the same words read differently from that position.", how_it_helps: "You would never speak to a friend the way you speak to yourself about this. Try speaking to yourself the way you'd speak to them." },
  { id: 236, emoji: "🏔️", title: "Learn About One Mountain or Geological Formation", subtitle: "The Himalayas. The Grand Canyon. The Great Rift Valley. One.", duration: "20 min", category: "Curiosity", color: "#6B8EA6", front_detail: "How old is it? What forces made it? How long will it last?", science_title: "Deep Time Contemplation & Perspective Restoration", science: "Contemplating geological time scales — millions to billions of years — produces reliable perspective restoration effects. Research shows engagement with deep time significantly reduces catastrophizing of present-day problems by providing temporal context that the human-scale timeframe systematically lacks.", how_it_helps: "The Grand Canyon is the result of five million years of patient erosion. That's one way to think about patience." },
  { id: 237, emoji: "🎯", title: "Make a Mind Map", subtitle: "One central idea. Branch outward freely. No hierarchy.", duration: "15 min", category: "Making", color: "#7B6E8D", front_detail: "Pen and paper. Everything the idea connects to.", science_title: "Radial Thinking & Knowledge Organization", science: "Mind mapping exploits the brain's natural associative organization — knowledge is stored as networks of associations, not linear sequences. Tony Buzan's original research and subsequent studies show that radial, visual knowledge mapping improves recall by 10-15% over linear notes and better represents the brain's actual storage architecture.", how_it_helps: "What you know about something is much larger than what you can say about it. A mind map shows you both." },
  { id: 238, emoji: "🌸", title: "Study One Flower's Biology", subtitle: "Any flower. What are its parts? How does it reproduce?", duration: "15 min", category: "Curiosity", color: "#E8845A", front_detail: "Sepal, petal, stamen, pistil. The tiny machinery of seed-making.", science_title: "Biological Curiosity & Perceptual Enhancement", science: "Learning the biological function of observed structures transforms passive aesthetic appreciation into active perceptual engagement. Research on expert attention shows that people with knowledge of what they observe attend to significantly more detail and report higher aesthetic experience scores than naive observers of the same stimuli.", how_it_helps: "A flower you know is more beautiful than a flower you don't. The structure makes the beauty more, not less." },
  { id: 239, emoji: "🎵", title: "Write a Haiku", subtitle: "5-7-5. One moment. The present weather.", duration: "10 min", category: "Making", color: "#7A9E7E", front_detail: "What is actually here right now? Three lines.", science_title: "Constrained Expression & Attentional Focus", science: "Haiku's strict formal constraints (5-7-5 syllables, seasonal reference, present moment) force the writer into a state of intense perceptual attention to immediate sensory reality. Research on form-constrained creative writing shows it produces stronger mindfulness effects than free writing, because the form directs attention outward.", how_it_helps: "You must pay attention to what is actually here right now. The form will not let you be anywhere else." },
  { id: 240, emoji: "🎭", title: "Invent a New Word and Define It", subtitle: "A word for something that has no name. Define it precisely.", duration: "10 min", category: "Making", color: "#9B7BB8", front_detail: "'Vemödalen.' 'Lachesism.' Your term for the unnamed thing.", science_title: "Linguistic Creation & Conceptual Clarification", science: "Creating words for unnamed experiences (as John Koenig does in The Dictionary of Obscure Sorrows) clarifies inchoate experiences into explicit concepts — an act of emotional granularity that research associates with better emotional regulation. The process of naming also produces satisfaction through the completion of a conceptual gap.", how_it_helps: "Name the feeling you've been carrying around without a word for it. Having the word changes what you can do with the feeling." },
  { id: 241, emoji: "🍳", title: "Learn One Culinary Technique", subtitle: "Julienning. Braising. Emulsifying. Blooming spices. One.", duration: "20 min", category: "Making", color: "#C8825A", front_detail: "Not a recipe. A technique. The why of how food works.", science_title: "Procedural Learning & Embodied Knowledge", science: "Culinary technique learning combines procedural memory encoding with immediate sensory feedback — you see, smell, hear, and taste the results of each technique. This multimodal learning produces particularly durable procedural memories and activates what researchers call 'embodied knowledge' — understanding that lives in the body.", how_it_helps: "Every technique is a key that opens thousands of recipes. You're not learning a dish. You're learning a language." },
  { id: 242, emoji: "🌊", title: "Study Fermentation Science", subtitle: "How does yeast turn sugar into CO2? How does milk become cheese?", duration: "20 min", category: "Curiosity", color: "#6B9E6B", front_detail: "The oldest human biotechnology. Still the most magical.", science_title: "Microbiology, Wonder & Everyday Science", science: "Fermentation science makes visible the normally invisible microbial world responsible for bread, wine, cheese, beer, kimchi, and kombucha. Research on scientific wonder shows that learning the mechanism behind familiar processes produces the 'knowledge deepens awe' effect — understanding the science increases appreciation for the product.", how_it_helps: "Bread rises because a living organism ate sugar and breathed carbon dioxide into your dough. That should be stranger than we let it be." },
  { id: 243, emoji: "🏛️", title: "Learn One Architectural Style", subtitle: "Gothic. Brutalism. Wabi-sabi. Art Nouveau. One, in depth.", duration: "20 min", category: "Curiosity", color: "#A0785A", front_detail: "What are its principles? What problems did it try to solve?", science_title: "Architectural Aesthetics & Environment-Behavior Research", science: "Architecture literally shapes human psychology — environmental psychology research documents measurable effects of ceiling height on abstract thinking, light angles on mood, and spatial complexity on restorative attention. Understanding architectural principles increases appreciation and provides a vocabulary for why environments feel the way they do.", how_it_helps: "Every building you walk into is making choices about you. Knowing the choices makes you more awake to them." },
  { id: 244, emoji: "📖", title: "Read About One Social Movement", subtitle: "Suffrage. Civil Rights. Solidarity. One movement, its full arc.", duration: "30 min", category: "Curiosity", color: "#C1603A", front_detail: "How did it start? What did it cost? What changed?", science_title: "Historical Agency & Collective Efficacy", science: "Research on historical consciousness shows that deep engagement with social movement history increases belief in collective agency — the sense that organized human effort can change conditions. This belief is a strong predictor of civic participation and a powerful buffer against political helplessness and cynicism.", how_it_helps: "Change has happened before. It cost something. It was done by people who weren't sure it would work. So can this." },
  { id: 245, emoji: "🧬", title: "Learn One Biology Concept", subtitle: "DNA replication. Mitosis. The Krebs cycle. Apoptosis. One.", duration: "20 min", category: "Curiosity", color: "#6B9E6B", front_detail: "Your body does this billions of times per day.", science_title: "Biological Self-Knowledge & Awe at the Body", science: "Understanding biological mechanisms operating within one's own body produces a distinct form of awe — directed inward at the complexity of processes occurring continuously without awareness. Research suggests body-directed awe is associated with increased self-care behavior, reduced health anxiety, and greater bodily self-compassion.", how_it_helps: "Your cells are doing something so complex that Nobel prizes are still being awarded for understanding it. That's happening in your body right now." },
  { id: 246, emoji: "🌍", title: "Learn About One Indigenous Navigation Technique", subtitle: "Polynesian wayfinding. San tracking. Inuit ice reading. One.", duration: "20 min", category: "Curiosity", color: "#D4945A", front_detail: "Before GPS. Before compasses. Before writing. How did they know?", science_title: "Environmental Perception & Knowledge System Diversity", science: "Traditional ecological knowledge systems encode sophisticated observational and inferential frameworks developed over millennia. Research on Polynesian wayfinding demonstrates cognitive capabilities (swell reading, star tracking, bird observation) that require and develop multisensory integration and long-term environmental pattern recognition.", how_it_helps: "Someone read the ocean the way you read a page. That is not a metaphor. That is a cognitive achievement we lost." },
  { id: 247, emoji: "🎨", title: "Study One Painter's Complete Body of Work", subtitle: "Not just their famous pieces. Everything. Early and late.", duration: "30 min", category: "Curiosity", color: "#E8845A", front_detail: "See how they changed. What they abandoned. What they found.", science_title: "Aesthetic Development & Creative Trajectory", science: "Studying an artist's complete development activates narrative processing — the brain constructs the artist's creative arc as a story. Research on aesthetic biography shows that understanding an artist's development significantly deepens appreciation of individual works by providing context that disambiguates aesthetic choices.", how_it_helps: "Rembrandt painted himself from youth to death. Watching that arc over an afternoon is a form of biography you can see." },
  { id: 248, emoji: "🌸", title: "Learn One Word in Sign Language", subtitle: "'Thank you'. 'I love you'. 'Hello'. One gesture, practiced.", duration: "10 min", category: "Curiosity", color: "#9B7BB8", front_detail: "A language that lives in the body and space.", science_title: "Spatial Language & Cross-Modal Cognition", science: "Sign language learning engages visuospatial processing centers in addition to language networks — a neurological distinction from spoken language learning that activates unique cortical regions. Research shows even minimal sign language exposure strengthens the neural bridges between spatial and linguistic processing.", how_it_helps: "Language can live in the hands. That is worth knowing in your body, not just your mind." },
  { id: 249, emoji: "🔭", title: "Learn About One Person History Forgot", subtitle: "An inventor, scientist, artist, or thinker erased from the record.", duration: "20 min", category: "Curiosity", color: "#9B7BB8", front_detail: "Rosalind Franklin. Ignaz Semmelweis. Nikola Tesla. Countless others.", science_title: "Historical Justice & Counterfactual Thinking", science: "Learning about historically marginalized contributors activates both moral reasoning and counterfactual thinking — the cognitive process of imagining alternate histories. Research on moral exemplar learning shows engagement with unjustly forgotten people increases moral motivation and a desire to correct invisibility in one's own sphere.", how_it_helps: "Someone changed the world and was not credited for it. Knowing their name is a small act of restoration." },
  { id: 250, emoji: "🌊", title: "Spend 5 Minutes Doing Absolutely Nothing", subtitle: "Sit. Don't meditate. Don't breathe deliberately. Just... be.", duration: "5 min", category: "Calm", color: "#6B8EA6", front_detail: "No technique. No goal. Just existing without an agenda.", science_title: "Boredom, Creativity & Default Mode Network", science: "Research by Sandi Mann at the University of Central Lancashire shows that unstructured boredom — doing literally nothing — significantly increases creative output on subsequent tasks compared to distraction. The default mode network, when not directed or disturbed, engages in the associative, imaginative processing that generates insight.", how_it_helps: "Your brain has never been bored since the smartphone. Give it five minutes with nothing to do. See what it does." },
  { id: 251, emoji: "🎋", title: "Practice Slow Calligraphy", subtitle: "Any letter, any style. Write one word very slowly.", duration: "15 min", category: "Making", color: "#7B6E8D", front_detail: "Speed is the enemy. Each stroke is complete.", science_title: "Slow Movement & Motor Cortex Refinement", science: "Deliberate slow movement training refines motor cortex representations more effectively than fast practice. Research on motor learning shows that slowed practice — moving at a fraction of target speed — produces superior skill acquisition by allowing conscious correction before automatic execution. Calligraphy is optimal slow practice.", how_it_helps: "Every letter is a small practice in doing one thing perfectly. The word you make is less important than the attention you spent on it." },
  { id: 252, emoji: "🧵", title: "Macramé: One Basic Knot", subtitle: "Square knot. Half hitch. Lark's head. One, practiced until smooth.", duration: "20 min", category: "Making", color: "#C8825A", front_detail: "Rope or cord. Any two cords. One knot, twenty times.", science_title: "Tactile Learning & Working Memory Reduction", science: "Manual knotting requires sustained fine motor attention that reduces working memory's verbal rehearsal loop — the part of the brain that produces rumination. Research on craft activities specifically identifies rope and fiber work as producing significant reductions in anxious thought intrusion through the attentional demand of procedural execution.", how_it_helps: "Your hands are too busy to worry. That's not an accident. That's why people have made things with their hands for thousands of years." },
  { id: 253, emoji: "🌿", title: "Nature Color Palette Collection", subtitle: "Find every color in a small area. Arrange what you collect.", duration: "20 min", category: "Making", color: "#6B9E6B", front_detail: "Leaves, petals, pebbles, bark. The full spectrum in one patch.", science_title: "Foraging Attention & Color Perception Training", science: "Systematic color collection in natural environments trains chromatic discrimination — the visual system's ability to distinguish fine differences within a hue category. Research on nature-based perceptual training shows consistent improvements in observational acuity, attention span, and positive affect following collection activities.", how_it_helps: "The palette you make is unique. These exact colors, in this exact moment, have never been arranged this way before." },
  { id: 254, emoji: "🖌️", title: "Do a Wax Resist Painting", subtitle: "Draw on paper with a white crayon. Then paint watercolor over it.", duration: "15 min", category: "Making", color: "#E8845A", front_detail: "The invisible drawing reveals itself. You couldn't see it before.", science_title: "Hidden Revelation & Surprise Reward", science: "The delayed reveal mechanism in wax resist art exploits the reward prediction error system — the hidden drawing produces an unexpected positive outcome that triggers dopamine release more strongly than anticipated rewards. Research on surprise rewards shows they produce stronger positive affect and memory encoding.", how_it_helps: "You drew something you couldn't see. Then you made it visible. That's a small version of what most meaningful work feels like." },
  { id: 255, emoji: "🌱", title: "Learn How Seeds Disperse", subtitle: "Wind, water, animals, explosion. Find one local example.", duration: "15 min", category: "Curiosity", color: "#7A9E7E", front_detail: "Dandelions, burs, maple helicopters, squirting cucumbers.", science_title: "Evolutionary Biology & Functional Beauty", science: "Seed dispersal mechanisms represent millions of years of optimization, producing structures that are both elegantly functional and visually distinctive. Research shows learning the evolutionary function of biological structures produces what scientists call 'functional aesthetics' — appreciation of beauty that is deepened rather than diminished by understanding the mechanism.", how_it_helps: "A dandelion clock is a precisely engineered dispersal mechanism. That makes it more beautiful than it was before you knew." },
  { id: 256, emoji: "📝", title: "Write Your Ideal Ordinary Day", subtitle: "Not a vacation. A regular day, made right.", duration: "20 min", category: "Reflection", color: "#9B7BB8", front_detail: "Hour by hour. What would it feel like to live this?", science_title: "Positive Future Projection & Goal Identification", science: "Writing about an ideal ordinary day — as opposed to ideal extraordinary experiences — reliably reveals core values and unmet needs that vacation fantasies obscure. Research by Laura King on best possible self exercises shows such writing improves wellbeing, clarifies goals, and increases motivation within hours of completion.", how_it_helps: "The gap between this day and your actual days is specific and workable. Writing it makes that specific." },
  { id: 257, emoji: "🎭", title: "Practice Active Gratitude", subtitle: "Find three things right now that are genuinely good. Specific ones.", duration: "5 min", category: "Reflection", color: "#7A9E7E", front_detail: "Not 'my health'. Something specific. Something from today.", science_title: "Specificity & Gratitude Efficacy", science: "Research by Seligman and Peterson shows that the key variable in gratitude's wellbeing effects is specificity — vague gratitude habituates rapidly and loses potency. Specific gratitude (naming an exact moment, person, or sensation) reactivates the original experience through episodic memory, producing genuine rather than performed positive affect.", how_it_helps: "Your mind can generate three genuine good things from today even on the worst days. This is not about denying the bad." },
  { id: 258, emoji: "🌿", title: "Identify Five Plants Within Walking Distance", subtitle: "Go outside. Name or describe five plants you see.", duration: "20 min", category: "Grounding", color: "#6B9E6B", front_detail: "No knowledge needed. Describe what you see. Look it up later.", science_title: "Local Ecological Knowledge & Environmental Belonging", science: "Research on local ecological knowledge shows a strong positive correlation between the number of local plants a person can identify and their sense of place attachment, environmental concern, and wellbeing. The act of naming what surrounds you increases the sense of belonging to a specific place.", how_it_helps: "You live among these plants every day. They were here before you. Knowing their names is an act of introduction." },
  { id: 259, emoji: "🎵", title: "Compose a Short Melody", subtitle: "Hum or whistle until you find four notes that belong together.", duration: "15 min", category: "Making", color: "#7B6E8D", front_detail: "Record it so you don't lose it. It doesn't need to be long.", science_title: "Musical Composition & Creative Identity", science: "Composing music — even minimally — activates creative identity processes distinct from performing or listening. Research on musical creativity shows that even amateur composition attempts activate self-concept as a creative person, with lasting effects on creative confidence and intrinsic motivation.", how_it_helps: "You made a melody that has never existed before. It is entirely yours. That is the smallest scale of composition and still completely real." },
  { id: 260, emoji: "🌊", title: "Learn About Ocean Zones", subtitle: "Sunlight, twilight, midnight, abyssal, hadal. What lives where?", duration: "20 min", category: "Curiosity", color: "#6B8EA6", front_detail: "Most of Earth's living space is dark, cold, and unknown.", science_title: "Spatial Scale Awe & Cognitive Accommodation", science: "Ocean zone exploration provides scale-induced awe — the ocean contains 97% of Earth's living space, of which less than 20% has been explored. Research shows that engaging with genuinely vast, complex, partially unknown systems produces cognitive accommodation — a restructuring of understanding that relieves the narrowness of daily concerns.", how_it_helps: "There are creatures living at pressures that would kill you instantly, in complete darkness, two miles below you right now. Worth knowing." },
  { id: 261, emoji: "🏠", title: "Slow Walk Through Your Own Home", subtitle: "As if you've never seen it. Notice everything.", duration: "10 min", category: "Presence", color: "#A0785A", front_detail: "Not to clean or fix. Just to see it with new eyes.", science_title: "Perceptual Freshness & Habitual Attention Disruption", science: "Deliberate observation of familiar environments disrupts perceptual habituation — the adaptive process by which the brain stops registering known stimuli. Research on environmental attunement shows that intentional re-observation of familiar spaces produces the same novelty responses as genuinely new environments.", how_it_helps: "You live here, but you stopped seeing it. This walk is a form of return." },
  { id: 262, emoji: "🌱", title: "Compost Something", subtitle: "Start a small compost bin. Put in today's kitchen scraps.", duration: "15 min", category: "Grounding", color: "#6B9E6B", front_detail: "Coffee grounds, vegetable peels, eggshells. The beginning.", science_title: "Ecological Participation & System Thinking", science: "Composting connects individual action to ecological cycles — transforming waste into fertility through microbial action. Research on ecological behavior shows that direct participation in natural cycles (rather than abstract concern) produces stronger feelings of environmental efficacy and reduces eco-anxiety through tangible engagement.", how_it_helps: "You are turning your leftovers into soil. The loop closes. That matters more than it seems." },
  { id: 263, emoji: "📚", title: "Read One Complete Short Story", subtitle: "One short story. Read it twice. Notice what changed.", duration: "30 min", category: "Presence", color: "#9B7BB8", front_detail: "Chekhov. Borges. Carver. Alice Munro. Just one.", science_title: "Literary Narrative & Theory of Mind", science: "Research by Keith Oatley and Mar & Oatley at the University of Toronto demonstrates that literary fiction reading significantly improves theory of mind — the ability to understand others' mental states. Short stories are particularly effective because they achieve this within a complete, bounded narrative arc.", how_it_helps: "Reading fiction is practiced empathy. The second reading shows you what you missed in the first. Something always changes." },
  { id: 264, emoji: "🎨", title: "Monoprint", subtitle: "Apply ink or paint to a surface. Press paper. Lift.", duration: "20 min", category: "Making", color: "#C1603A", front_detail: "Glass, tile, even a plastic bag. The transfer is the art.", science_title: "Chance Operations & Aesthetic Acceptance", science: "Monoprinting is inherently unpredictable — the transferred image is never exactly what was applied. Research on chance-based art processes shows they develop tolerance for uncertainty and produce the same acceptance-based psychological shifts as mindfulness interventions, by training the artist to appreciate rather than control outcomes.", how_it_helps: "What comes off the glass is exactly what it is. Not what you planned. Learning to love that is the entire practice." },
  { id: 265, emoji: "🌿", title: "Whittle Something Simple", subtitle: "A stick. A spatula shape. A pointed twig. Just remove wood.", duration: "30 min", category: "Making", color: "#A0785A", front_detail: "A sharp knife and a stick. People have done this for 500,000 years.", science_title: "Tool Use, Embodied Cognition & Focus", science: "Whittling requires complete sensorimotor integration — visual, proprioceptive, and tactile feedback in a real-time feedback loop. Research on tool-mediated tasks shows they produce deep flow states through the requirement for sustained, precise, consequence-rich attention. The material's resistance provides constant feedback.", how_it_helps: "The wood tells you what it wants to become. Your job is to listen carefully enough to help." },
  { id: 266, emoji: "🌊", title: "Learn One Deep Sea Creature", subtitle: "Anglerfish. Giant squid. Barreleye fish. One species, fully.", duration: "15 min", category: "Curiosity", color: "#2C4A30", front_detail: "Find out what it looks like, how it survives, how it reproduces.", science_title: "Biological Extremophilia & Possibility Expansion", science: "Deep sea creatures operate under physical conditions (pressure, temperature, darkness) that should, by surface-based intuition, preclude life. Research on biophilic curiosity shows that exposure to biological extremes reliably produces cognitive accommodation — the restructuring of what one believes is possible.", how_it_helps: "Life found a way in complete darkness at crushing pressure. That fact belongs in your head." },
  { id: 267, emoji: "🎭", title: "Write a One-Star Review of Something You Love", subtitle: "Make it specific, funny, deeply unfair. A place you love dearly.", duration: "10 min", category: "Making", color: "#E8845A", front_detail: "'The light is so beautiful in the morning it's almost rude.'", science_title: "Playful Reframing & Hedonic Flexibility", science: "Deliberately adopting a contrary evaluative position on a beloved subject produces cognitive flexibility — the ability to hold multiple frames simultaneously. Research on humor and reframing shows that playful inversion of genuine positive experience produces oxytocin and dopamine responses associated with shared laughter, even when done alone.", how_it_helps: "Making fun of something you love is a form of fondness so deep it can afford to be irreverent." },
  { id: 268, emoji: "🌿", title: "Learn One Traditional Medicine Practice", subtitle: "Ayurveda. Traditional Chinese Medicine. Humorism. One system.", duration: "20 min", category: "Curiosity", color: "#D4945A", front_detail: "Not to practice it. To understand how different cultures have thought about the body.", science_title: "Medical Pluralism & Epistemological Flexibility", science: "Studying diverse medical knowledge systems exercises epistemic flexibility — the ability to understand how valid observations can be organized into radically different explanatory frameworks. Research on cross-cultural medical literacy shows it improves understanding of one's own cultural assumptions and increases empathy for patients from different backgrounds.", how_it_helps: "Every tradition organized the same observable symptoms into a different story. Understanding the stories is understanding the humans." },
  { id: 269, emoji: "📖", title: "Read One Chapter of a Classic You've Avoided", subtitle: "Moby Dick. Middlemarch. Ulysses. Just one chapter. Really try.", duration: "30 min", category: "Curiosity", color: "#9B7BB8", front_detail: "It won't be what you expect. Most avoided classics aren't.", science_title: "Cognitive Challenge & Reading Depth", science: "Syntactically complex or historically distant texts require more active processing than contemporary prose — engaging metacognitive monitoring, context reconstruction, and sustained semantic attention. Research shows difficult literary reading produces greater cognitive benefit than accessible reading, precisely because of its resistance.", how_it_helps: "The difficulty is the point. Your reading brain needs to work sometimes." },
  { id: 270, emoji: "🔬", title: "Learn How Your Immune System Works", subtitle: "Innate and adaptive immunity. B cells and T cells. One mechanism.", duration: "20 min", category: "Curiosity", color: "#6B9E6B", front_detail: "Your body has a memory. It learns. It trains.", science_title: "Immune System Knowledge & Body Trust", science: "Research on health literacy shows that people with accurate knowledge of immune function demonstrate significantly lower health anxiety than those with incomplete or inaccurate models. Understanding the immune system's sophisticated capabilities (memory, specificity, self/non-self discrimination) builds confidence in the body's own defenses.", how_it_helps: "Your immune system remembered a virus from childhood and is ready for it. It has been doing this your entire life." },
  { id: 271, emoji: "🎵", title: "Learn Five Facts About One Composer", subtitle: "Bach. Coltrane. Piazzolla. Reich. Five things you didn't know.", duration: "15 min", category: "Curiosity", color: "#7B6E8D", front_detail: "Their life, their method, what they were trying to solve.", science_title: "Person Knowledge & Aesthetic Deepening", science: "Knowing biographical context for an artist's work produces what researchers call 'contextual enrichment' — the artwork becomes layered with human meaning beyond its formal properties. Research shows biographical knowledge consistently increases emotional response to art, music, and literature.", how_it_helps: "Bach wrote over 1,000 pieces. His first wife died. He had 20 children. He never left Germany. The music carries all of this." },
  { id: 272, emoji: "🌺", title: "Pick and Arrange Wildflowers", subtitle: "Whatever grows nearby. Arrange them in anything you have.", duration: "15 min", category: "Making", color: "#E8845A", front_detail: "Weeds count. They always count.", science_title: "Foraged Beauty & Gratuitous Care", science: "Collecting and arranging found natural materials combines foraging behavior (evolutionarily significant) with aesthetic agency (producing reward through creative control). Research on ecological art shows that making beauty from freely available natural materials produces some of the strongest positive affect scores of any craft activity.", how_it_helps: "You made something beautiful from things you found on the ground. The effort required was completely optional. That's the whole point." },
  { id: 273, emoji: "🏗️", title: "Build Something From Cardboard", subtitle: "A box becomes a house, a boat, a shelf. Build one thing.", duration: "30 min", category: "Making", color: "#C8825A", front_detail: "Old packaging. Tape and scissors. Make something that stands.", science_title: "Structural Problem Solving & Agency", science: "Cardboard construction activates three-dimensional spatial reasoning, engineering physics intuition, and iterative problem-solving. Research on constructive play shows it produces significantly stronger executive function activation than passive activities, with agency restoration effects lasting beyond the construction session.", how_it_helps: "It will probably be imperfect. It will stand because of physics, which you managed. That counts." },
  { id: 274, emoji: "🌙", title: "Study Your Own Chronotype", subtitle: "Are you a lark, owl, or third bird? Learn your body's actual timing.", duration: "20 min", category: "Curiosity", color: "#2C4A30", front_detail: "Take the MEQ questionnaire. Read about what it means.", science_title: "Chronobiology & Self-Knowledge", science: "Chronotype — genetically influenced preference for morning or evening activity — affects cognitive performance, mood, health, and social jet lag. Research by Matthew Walker and Till Roenneberg shows that people living out of alignment with their chronotype suffer measurable cognitive and health consequences. Knowing your type allows alignment.", how_it_helps: "You've been calling yourself lazy or a morning person based on social pressure. Your actual biology may disagree." },
  { id: 275, emoji: "🎶", title: "Drum on Any Surface", subtitle: "Hands on a table, knees, a book. Three minutes of rhythm.", duration: "5 min", category: "Making", color: "#C1603A", front_detail: "No pattern needed. Just pulse. Just sound.", science_title: "Rhythmic Entrainment & Neural Synchrony", science: "Self-generated rhythmic percussion produces neural entrainment — synchronization of brain oscillations to the rhythmic stimulus — reducing anxiety and increasing social bonding. Research shows even simple self-generated drumming activates the same entrainment effects as music, with additional proprioceptive grounding from the physical contact.", how_it_helps: "Rhythm is the oldest human medicine. You don't need an instrument. Your hands and any surface will do." },
  { id: 276, emoji: "🌿", title: "Study the Lifecycle of One Species", subtitle: "From birth to death. Every stage. One species completely.", duration: "20 min", category: "Curiosity", color: "#6B9E6B", front_detail: "Monarch butterfly. Pacific salmon. Mayfly. Elephant.", science_title: "Biological Narrative & Empathic Extension", science: "Tracing the complete lifecycle of another species activates narrative processing and emotional empathy in ways that fragmentary encounters do not. Research on species knowledge shows that people who understand the complete life arc of non-human species demonstrate significantly higher empathic concern for non-human life.", how_it_helps: "A mayfly lives for one day as an adult. It spends two years as a larva for that one day. Think about that." },
  { id: 277, emoji: "🔭", title: "Find the International Space Station", subtitle: "Track its position online. Go outside. Watch it pass.", duration: "10 min", category: "Presence", color: "#2C4A30", front_detail: "It crosses the sky in 6 minutes. Humans are in it.", science_title: "Real-Time Awe & Proximity to the Extraordinary", science: "The ISS is visible to the naked eye and passes over most locations several times per week. Watching it while knowing humans are aboard produces a real-time awe experience — the actual combination of vastness (space) and human presence (the crew) that cognitive research identifies as the purest form of awe induction.", how_it_helps: "There are humans in that light. Right now, above you, in space. That's not abstract." },
  { id: 278, emoji: "🌱", title: "Keep a Sprout Journal", subtitle: "Plant any seed in a cup. Photograph or draw it daily for a week.", duration: "5 min", category: "Grounding", color: "#7A9E7E", front_detail: "Lentil, mung bean, or any garden seed. Watch the first days.", science_title: "Biological Emergence & Daily Attention", science: "Observing daily emergence — the transition from seed to sprout — trains sustained attention to gradual change. Research on phenological observation (watching biological change over time) shows consistent positive affect gains from the daily small discoveries, a form of low-stakes wonder that compounds over the observation period.", how_it_helps: "Something was a seed. Now it's reaching for light. You watched that happen. That's not a small thing." },
  { id: 279, emoji: "🎭", title: "Speak Only in Questions for Five Minutes", subtitle: "With yourself or someone else. Only questions allowed.", duration: "5 min", category: "Curiosity", color: "#9B7BB8", front_detail: "Not rhetorical questions. Genuine ones.", science_title: "Interrogative Self-Talk & Motivational Persistence", science: "Research by Ibrahim Senay at the University of Illinois found that asking yourself questions ('Will I do this?') significantly outperforms affirmations ('I will do this') in generating intrinsic motivation and creative problem-solving. The interrogative mode activates ownership-based processing rather than compliance-based processing.", how_it_helps: "Questions open space. Statements close it. Five minutes of only questions changes how you think about everything you were asserting." },
  { id: 280, emoji: "🌊", title: "Watch a Full Tide Cycle", subtitle: "Sit by the ocean, or watch a live tide cam. Watch it move.", duration: "30 min", category: "Presence", color: "#6B8EA6", front_detail: "The water moves because of the moon. You're watching that force.", science_title: "Tidal Rhythms, Temporal Scale & Gravitational Awe", science: "Tide watching provides direct perceptual access to a force (gravitational pull of the moon) operating at astronomical scale on local, tangible reality. Research on scale-bridging experiences — where the cosmic manifests locally — produces reliable awe responses with associated self-transcendence effects.", how_it_helps: "The moon is pulling the ocean. You can see it. That's the universe demonstrating itself in real time." },
  { id: 281, emoji: "🖋️", title: "Practice Copperplate Lettering", subtitle: "Thick down-strokes, thin up-strokes. One letter, many times.", duration: "20 min", category: "Making", color: "#C1603A", front_detail: "The pressure of the pen matters as much as the direction.", science_title: "Pressure-Sensitive Motor Control & Attentional Refinement", science: "Copperplate calligraphy requires real-time modulation of pen pressure — a motor skill demanding continuous somatosensory feedback processing. Research on fine pressure-sensitive tasks shows they engage the most precise levels of motor cortex organization, producing flow states through the requirement for absolute attentional commitment.", how_it_helps: "Every letter requires a decision about pressure. A practice that small, made that many times, builds a particular kind of patience." },
  { id: 282, emoji: "🌺", title: "Learn About the Anatomy of a Flower", subtitle: "Pistil. Stamen. Anther. Sepal. What does each part do?", duration: "15 min", category: "Curiosity", color: "#E8845A", front_detail: "Find a flower. Identify its parts. Hold them in your fingers.", science_title: "Botanical Morphology & Attention to Structure", science: "Learning the biological function of flower structures transforms passive beauty reception into active functional perception. Research on botanical observation shows that people who can identify floral structures attend to significantly more detail per minute of observation, and report higher aesthetic experience scores than naive observers.", how_it_helps: "The flower is more beautiful once you understand what it's doing. That's always how it works with living things." },
  { id: 283, emoji: "🎯", title: "Spend 30 Minutes on a Skill With a Skill Curve", subtitle: "Chess. Juggling. Pottery. Anything with room to improve.", duration: "30 min", category: "Making", color: "#C8825A", front_detail: "The marginal improvement is the point. Not the mastery.", science_title: "Deliberate Practice & Intrinsic Reward Circuits", science: "Ericsson's deliberate practice research shows that focused practice at the edge of current ability — where mistakes are frequent but progress is visible — produces the strongest intrinsic motivation and the most significant skill gains. The subjective experience of getting better is neurologically rewarding independent of the domain.", how_it_helps: "You are better at this at the end than at the beginning. That feeling is available in anything with a skill curve." },
  { id: 284, emoji: "🌿", title: "Sit Outside at Golden Hour", subtitle: "The hour before sunset. Take nothing to do.", duration: "60 min", category: "Presence", color: "#D4945A", front_detail: "Just be outside while the light changes.", science_title: "Low-Angle Light, Circadian Signaling & Mood", science: "Golden hour light (low-angle, warm-spectrum sunlight) has distinctive effects on both mood and circadian biology. Research shows warm-spectrum evening light activates melanopsin-independent photoreception that signals biological day-end, facilitating cortisol clearance and emotional transition from active to restorative states.", how_it_helps: "The light is doing something to your biology right now. You just have to be in it." },
  { id: 285, emoji: "🎵", title: "Learn a Short Piece of Music by Heart", subtitle: "A few bars. A theme. Something simple you can play from memory.", duration: "30 min", category: "Making", color: "#7B6E8D", front_detail: "Fur Elise first four bars. Twinkle Twinkle. Anything.", science_title: "Musical Memory & Long-Term Potentiation", science: "Memorizing music activates long-term potentiation — the strengthening of synaptic connections through repeated activation — in motor, auditory, and working memory networks simultaneously. Research shows music memorization is one of the most complex neurological tasks, activating more brain regions simultaneously than almost any other human activity.", how_it_helps: "Music you know by heart is always with you. It costs nothing to carry. No one can take it away." },
  { id: 286, emoji: "🌊", title: "Take a Mindful Shower", subtitle: "Notice temperature, pressure, sound, smell. Be completely here.", duration: "10 min", category: "Presence", color: "#6B8EA6", front_detail: "Not planning. Not reviewing. Just the shower.", science_title: "Sensory Presence & Habitual Disruption", science: "Shower routines are among the most heavily automatized behaviors in daily life — most people are entirely mentally elsewhere during them. Bringing attention to shower sensations disrupts this automatization and activates the insula (interoceptive awareness center), producing the same present-moment effects as formal mindfulness practice.", how_it_helps: "You spend ten minutes in hot water every day. This is the first time you'll actually be there." },
  { id: 287, emoji: "📝", title: "Write a Six-Word Story", subtitle: "A complete story. Six words. No more.", duration: "10 min", category: "Making", color: "#C1603A", front_detail: "Hemingway's most famous: 'For sale: baby shoes, never worn.'", science_title: "Constraint, Compression & Meaning Density", science: "Extreme formal constraint (six words) forces compression of narrative meaning to the point of maximum density — every word carries maximum load. Research on constraint-based creative tasks shows they produce superior output quality and greater cognitive engagement than unconstrained tasks, by forcing non-habitual linguistic solutions.", how_it_helps: "Every word must earn its place. That discipline produces writing that means more than its size suggests." },
  { id: 288, emoji: "🌿", title: "Do a Mindful Dishwashing", subtitle: "Warm water. Every dish. Full attention to the task.", duration: "15 min", category: "Presence", color: "#A0785A", front_detail: "From a 2015 FSU study: mindful dishwashing reduces nervousness 27%.", science_title: "Mindful Task Engagement & Sensory Absorption", science: "A landmark 2015 Florida State University study found that mindful dishwashing — attending to warmth, smell, sound, and texture — reduced nervousness by 27% and increased mental inspiration significantly. The repetitive, contained sensory environment provides the optimal conditions for mindfulness induction without formal practice.", how_it_helps: "Your kitchen sink is a meditation room in disguise. The practice makes the dishes clean as a side effect." },
  { id: 289, emoji: "🎨", title: "Find Five Things That Are the Same Color", subtitle: "Any color. Five different objects. Arrange them together.", duration: "10 min", category: "Presence", color: "#E8845A", front_detail: "Navy, terracotta, sage, blush. Any hue. Find its family.", science_title: "Color Attention & Environmental Awareness", science: "Systematic color hunting in everyday environments requires active perceptual engagement with background stimuli that habituation normally renders invisible. Research on perceptual attention tasks shows that color-based environmental scanning improves attentional flexibility and produces novelty responses in familiar spaces.", how_it_helps: "Objects you've ignored for years will suddenly appear when you're looking for a color. The attention makes them visible." },
  { id: 290, emoji: "🌙", title: "Watch Something Grow on Time-Lapse", subtitle: "A plant sprouting, bread rising, cheese ripening. Watch the whole video.", duration: "10 min", category: "Curiosity", color: "#6B9E6B", front_detail: "Find any botanical time-lapse. Watch it beginning to end.", science_title: "Biological Growth Perception & Awe", science: "Witnessing biological processes at compressed timescales makes visible the normally imperceptible vitality of living systems. Research on awe induction shows that witnessing natural processes at altered timescales reliably produces cognitive accommodation — the expansion of existing frameworks required by new experience.", how_it_helps: "Living things are always doing this. You just move at the wrong speed to see it." },
  { id: 291, emoji: "🎸", title: "Practice Call-and-Response Clapping", subtitle: "Clap a rhythm. Answer yourself differently. Repeat.", duration: "10 min", category: "Making", color: "#D4945A", front_detail: "Make a pattern. Make a different answer. Keep going.", science_title: "Rhythmic Improvisation & Bilateral Processing", science: "Rhythmic call-and-response requires both pattern production and pattern variation simultaneously — a high-level executive function task masked by its apparent simplicity. Research on rhythmic improvisation shows it activates the supplementary motor area, prefrontal cortex, and basal ganglia in patterns associated with creative flow.", how_it_helps: "You are having a conversation with yourself in rhythm. That is both more creative and more meditative than it sounds." },
  { id: 292, emoji: "🌿", title: "Visit a Museum and Pick One Piece", subtitle: "Spend 30 minutes on one thing. Read everything about it.", duration: "45 min", category: "Presence", color: "#9B7BB8", front_detail: "Any museum. One object. All your time on that one.", science_title: "Slow Looking, Depth of Engagement & Aesthetic Experience", science: "Harvard educator Philip Yenawine's research on visual thinking strategies shows that spending 30+ minutes on a single artwork produces qualitative changes in observation — new details emerge after 10 minutes, 20 minutes, and 30 minutes that are invisible at first glance. The depth of engagement is the opposite of art tourism.", how_it_helps: "Most people spend 27 seconds per artwork in museums. This is thirty minutes. The difference is not comparable." },
  { id: 293, emoji: "🖊️", title: "Write a Love Letter to a Place", subtitle: "A city, a room, a landscape you love. Write what you love.", duration: "15 min", category: "Reflection", color: "#C1603A", front_detail: "Not what it looks like. What it feels like. The specific things.", science_title: "Place Attachment & Positive Memory Consolidation", science: "Writing about places of deep attachment consolidates positive episodic memories through the elaborative encoding process — adding emotional and sensory detail strengthens the memory trace. Research on place attachment shows it provides psychological shelter: a mental refuge accessible during stress through vivid memory.", how_it_helps: "The place will always be accessible to you through writing. That is a kind of ownership no one can take." },
  { id: 294, emoji: "🎭", title: "Describe Your Emotional Weather Today", subtitle: "Not a metaphor for avoidance. An accurate description of your actual state.", duration: "10 min", category: "Reflection", color: "#7B6E8D", front_detail: "Partly cloudy with gusts of anxiety and occasional clearing.", science_title: "Emotional Granularity & Interoceptive Labeling", science: "Research by Lisa Feldman Barrett on emotional granularity shows that people who describe emotional states with greater nuance and precision experience those emotions less intensely and recover from them faster than people who use coarser labels. The precision of description is inversely correlated with emotional suffering.", how_it_helps: "The more precisely you can name what is happening, the less completely you are inside it." },
  { id: 295, emoji: "🌿", title: "Forage for Something Edible", subtitle: "Identify and taste one wild edible plant. With proper caution.", duration: "30 min", category: "Grounding", color: "#6B9E6B", front_detail: "Dandelion. Wood sorrel. Plantain. Clover. All edible. All everywhere.", science_title: "Foraging, Ecological Connection & Reward", science: "Foraging for edible plants activates the same reward circuits as successful hunting — a deep evolutionary response that combines spatial navigation, botanical recognition, and immediate material reward. Research on foraging as a therapeutic activity shows significant reductions in anxiety and increases in felt competence.", how_it_helps: "You can eat something that was growing wild an hour ago. That capability has always been there. You just forgot." },
  { id: 296, emoji: "🎯", title: "Practice Mindful Walking", subtitle: "Slow down to half speed. Feel each foot placement completely.", duration: "15 min", category: "Presence", color: "#7A9E7E", front_detail: "This slow is uncomfortable at first. Stay with it.", science_title: "Kinesthetic Attention & Somatic Grounding", science: "Mindful walking at deliberately reduced pace shifts attention from destination-orientation to process-orientation, activating proprioceptive attention channels typically suppressed during purposeful movement. Research on kinesthetic mindfulness shows it produces grounding effects equivalent to seated meditation with the added benefit of physical movement.", how_it_helps: "Walking this slowly is strange. Everything looks different. Your body is in a place you've never been, even though it's familiar." },
  { id: 297, emoji: "📖", title: "Read One Piece of Poetry Twice", subtitle: "Any poem. Read it once for meaning. Once for sound.", duration: "10 min", category: "Presence", color: "#9B7BB8", front_detail: "What you notice the second time will be different.", science_title: "Dual Processing in Literary Reading & Affective Response", science: "Reading poetry twice activates complementary processing modes — semantic and phonological — that operate more completely on the second pass because semantic anxiety (not understanding) is reduced. Research on poetry cognition shows the second reading consistently produces stronger emotional responses through the interaction of expectation and fulfillment.", how_it_helps: "The meaning carries the sound on the first reading. The sound carries the meaning on the second. Both are the poem." },
  { id: 298, emoji: "🌊", title: "Practice Non-Dominant Hand Writing", subtitle: "Write three sentences with your non-dominant hand. No rushing.", duration: "10 min", category: "Making", color: "#9B7BB8", front_detail: "What do you want to say? Say it with the other hand.", science_title: "Right Hemisphere Access & Emotional Authenticity", science: "Non-dominant hand writing produces slower, less controlled output that has been used in art therapy and psychological research to access emotional content typically suppressed by the dominant hemisphere's editing function. Research shows non-dominant writing produces more emotionally raw and authentic content in journaling contexts.", how_it_helps: "The slower hand can't edit as fast. What comes out may surprise you." },
  { id: 299, emoji: "🎵", title: "Find a Piece of Music That Matches Your Mood", subtitle: "Not to change your mood. To be exactly accompanied in it.", duration: "15 min", category: "Presence", color: "#7B6E8D", front_detail: "Sad music when sad. Anxious music when anxious. Just company.", science_title: "Iso-Principle & Emotional Processing", science: "The iso-principle in music therapy holds that matching music to current emotional state, rather than attempting to change it, is more therapeutically effective. Research shows mood-matched music allows emotional processing and release, while mood-incongruent music produces resistance. Validation before transformation.", how_it_helps: "Sometimes you need music that understands where you are before you move anywhere else." },
  { id: 300, emoji: "🌿", title: "Write Three True Things From Today", subtitle: "Specific, honest, grounded. Three things that happened.", duration: "5 min", category: "Reflection", color: "#C1603A", front_detail: "Not lessons. Not insights. Three things that were true today.", science_title: "Factual Journaling & Reality Anchoring", science: "Factual, non-evaluative journaling — recording what occurred without interpretation — activates the memory consolidation function of the hippocampus without triggering the evaluation anxiety associated with reflective journaling. Research on narrative journaling shows it reduces intrusive memories and improves next-day mood significantly.", how_it_helps: "Not what it meant. Not how you feel about it. Just what happened. That clarity is its own form of rest." },
];

// ─── Date & Shuffle ───────────────────────────────────────────────────────────
function getTodayKey() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
function strHash(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = Math.imul(31, h) + s.charCodeAt(i) | 0;
  return h;
}
function seededShuffle(arr, seed) {
  const a = [...arr]; let s = Math.abs(seed) >>> 0;
  for (let i = a.length - 1; i > 0; i--) {
    s = (Math.imul(s ^ (s >>> 15), s | 1) ^ (s + Math.imul(s ^ (s >>> 7), s | 61))) >>> 0;
    [a[i], a[s % (i + 1)]] = [a[s % (i + 1)], a[i]];
  }
  return a;
}
function getDailySelection(key) { return seededShuffle(ALL_PRACTICES, strHash(key)).slice(0, 12); }

// ─── Supabase Auth & Log Helpers ──────────────────────────────────────────────
function mapUser(u) {
  if (!u) return null;
  return {
    uid: u.id,
    name: u.user_metadata?.full_name || u.user_metadata?.name || u.email?.split('@')[0] || 'User',
    email: u.email,
    avatar: u.user_metadata?.avatar_url || null,
    provider: u.app_metadata?.provider || 'email',
    createdAt: u.created_at,
  };
}

async function fetchLog(uid) {
  const { data } = await supabase
    .from('practice_logs')
    .select('date_key, entries')
    .eq('user_id', uid);
  if (!data) return {};
  return Object.fromEntries(data.map(r => [r.date_key, r.entries]));
}

async function syncLog(uid, dateKey, entries) {
  await supabase
    .from('practice_logs')
    .upsert(
      { user_id: uid, date_key: dateKey, entries, updated_at: new Date().toISOString() },
      { onConflict: 'user_id,date_key' }
    );
}

// ─── Global CSS ───────────────────────────────────────────────────────────────
const G = `
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;0,900;1,400;1,700&family=Crimson+Pro:ital,wght@0,400;0,600;1,400;1,600&display=swap');
  *, *::before, *::after { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; background: #F5EFE6; }
  ::-webkit-scrollbar { width: 4px; } ::-webkit-scrollbar-thumb { background: #D4B89666; border-radius: 4px; }
  .modal-flip-wrap { transition: transform .55s cubic-bezier(.23,1,.32,1); transform-style: preserve-3d; position:absolute; inset:0; }
  .modal-flip-wrap.flipped { transform: rotateY(180deg); }
  .modal-face { position:absolute; inset:0; backface-visibility:hidden; -webkit-backface-visibility:hidden; border-radius:24px; overflow:hidden; }
  .modal-back-face { transform: rotateY(180deg); }
  @keyframes fadeUp { from { opacity:0; transform:translateY(24px); } to { opacity:1; transform:translateY(0); } }
  @keyframes fadeIn { from { opacity:0; } to { opacity:1; } }
  @keyframes slideUp { from { opacity:0; transform:translateY(60px); } to { opacity:1; transform:translateY(0); } }
  input:-webkit-autofill { -webkit-box-shadow: 0 0 0 30px #FAF6F0 inset !important; -webkit-text-fill-color: #1E1E1E !important; }
`;

// ─── Input Component ──────────────────────────────────────────────────────────
function Input({ label, type = "text", value, onChange, placeholder, error, rightEl }) {
  const [show, setShow] = useState(false);
  const isPassword = type === "password";
  return (
    <div style={{ marginBottom: 16 }}>
      <label style={{ fontFamily: "'Crimson Pro',serif", fontSize: 13, color: P.muted, display: "block", marginBottom: 5 }}>{label}</label>
      <div style={{ position: "relative" }}>
        <input
          type={isPassword && show ? "text" : type}
          value={value}
          onChange={e => onChange(e.target.value)}
          placeholder={placeholder}
          style={{
            width: "100%", padding: rightEl || isPassword ? "11px 42px 11px 14px" : "11px 14px",
            fontFamily: "'Crimson Pro',serif", fontSize: 15, color: P.ink,
            background: P.cream, border: `1.5px solid ${error ? "#C1603A" : P.sand}`,
            borderRadius: 12, outline: "none", transition: "border .2s",
          }}
          onFocus={e => e.target.style.borderColor = P.terracotta}
          onBlur={e => e.target.style.borderColor = error ? "#C1603A" : P.sand}
        />
        {isPassword && (
          <button onClick={() => setShow(s => !s)} style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", cursor: "pointer", color: P.muted, fontSize: 14, padding: 0 }}>
            {show ? "hide" : "show"}
          </button>
        )}
        {rightEl && !isPassword && <div style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)" }}>{rightEl}</div>}
      </div>
      {error && <div style={{ fontFamily: "'Crimson Pro',serif", fontSize: 12, color: P.terracotta, marginTop: 4 }}>{error}</div>}
    </div>
  );
}

// ─── Auth Button ──────────────────────────────────────────────────────────────
function AuthBtn({ children, onClick, variant = "primary", disabled, style: s = {} }) {
  const base = {
    width: "100%", padding: "13px", borderRadius: 14, fontFamily: "'Crimson Pro',serif",
    fontSize: 16, fontWeight: 600, cursor: disabled ? "not-allowed" : "pointer",
    border: "none", transition: "all .2s", opacity: disabled ? .6 : 1, ...s,
  };
  const variants = {
    primary: { background: P.terracotta, color: "#fff", boxShadow: "0 4px 16px rgba(193,96,58,.3)" },
    outline: { background: "transparent", color: P.ink, border: `1.5px solid ${P.sand}`, boxShadow: "none" },
    google: { background: P.cream, color: P.ink, border: `1.5px solid ${P.sand}`, display: "flex", alignItems: "center", justifyContent: "center", gap: 10 },
  };
  return (
    <button onClick={onClick} disabled={disabled} style={{ ...base, ...variants[variant] }}>
      {children}
    </button>
  );
}

